            score = (count, -empty_side, max_run, interior)
            best_score = (best_count, -best_empty_side, best_run,
                          1 if 0 < line_c < W - 1 else 0)

            if score > best_score:
                best_count = count
                best_empty_side = empty_side
                best_run = max_run
                line_c = c
                line_color = color

    if best_count == 0:
        return [list(row) for row in grid]

    # Decide which side is the source side and which is the painted side.
    left_total = 0
    right_total = 0
    for r in range(H):
        for c in range(line_c):
            if int(grid[r][c]) != 0:
                left_total += 1
        for c in range(line_c + 1, W):
            if int(grid[r][c]) != 0:
                right_total += 1

    source_right = right_total > left_total

    out = [[int(grid[r][c]) for c in range(W)] for r in range(H)]

    if source_right:
        target_width = line_c
        scan_range = range(W - 1, line_c, -1)
        for r in range(H):
            for c in range(line_c):
                out[r][c] = 0
    else:
        target_width = W - line_c
        scan_range = range(0, line_c)
        for r in range(H):
            for c in range(line_c + 1, W):
                out[r][c] = 0

    def paint(row_idx: int, color: int, length: int) -> None:
        d = 1
        if source_right:
            while d <= target_width:
                out[row_idx][line_c - d] = color
                d += length
        else:
            while d <= target_width:
                out[row_idx][line_c + d] = color
                d += length

    # Process runs from farthest from the line to closest.
    # Later (closer) runs overwrite earlier (farther) runs.
    for r in range(H):
        current_color = 0
        current_len = 0

        for c in scan_range:
            v = int(grid[r][c])
            if v != 0:
                if current_color == 0:
                    current_color = v
                    current_len = 1
                elif v == current_color:
                    current_len += 1
                else:
                    paint(r, current_color, current_len)
                    current_color = v
                    current_len = 1
            else:
                if current_color != 0:
                    paint(r, current_color, current_len)
                    current_color = 0
                    current_len = 0

        if current_color != 0:
            paint(r, current_color, current_len)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [list(row) for row in grid]

    H = len(grid)
    W = len(grid[0])

    # Find the separator line column
    best_count = 0
    line_c = -1
    line_color = 0
    for c in range(W):
        for color in range(1, 10):
            count = sum(1 for r in range(H) if grid[r][c] == color)
            if count > best_count:
                best_count = count
                line_c = c
                line_color = color

    if line_c == -1 or best_count == 0:
        return [list(row) for row in grid]

    # Determine which side is the source (has more non-zero pixels)
    left_nz = sum(1 for r in range(H) for c in range(line_c) if grid[r][c] != 0)
    right_nz = sum(1 for r in range(H) for c in range(line_c + 1, W) if grid[r][c] != 0)
    source_left = left_nz > right_nz

    out = [list(row) for row in grid]

    if source_left:
        target_start = line_c + 1
        target_width = W - line_c - 1
    else:
        target_start = 0
        target_width = line_c

    for r in range(H):
        # Source pixels ordered from closest to line (index 0) to farthest
        if source_left:
            source_pixels = [grid[r][c] for c in range(line_c - 1, -1, -1)]
        else:
            source_pixels = [grid[r][c] for c in range(line_c + 1, W)]

        # Extract runs of same non-zero color: (color, length, min_distance)
        runs = []
        i = 0
        while i < len(source_pixels):
            if source_pixels[i] != 0:
                color = source_pixels[i]
                j = i
                while j < len(source_pixels) and source_pixels[j] == color:
                    j += 1
                length = j - i
                min_dist = i + 1
                runs.append((color, length, min_dist))
                i = j
            else:
                i += 1

        # Process farthest first so nearer runs overwrite
        runs.sort(key=lambda x: -x[2])

        target = [0] * target_width
        for color, length, _ in runs:
            for d in range(target_width):
                if d % length == 0:
                    target[d] = color

        for d in range(target_width):
            out[r][target_start + d] = target[d]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # Most frequent colour is the background.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda x: counts[x])

    # Connected components of non-background cells (4-neighbour).
    visited = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                color_count = {}

                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    v = grid[x][y]
                    color_count[v] = color_count.get(v, 0) + 1

                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w:
                            if not visited[nx][ny] and grid[nx][ny] != bg:
                                visited[nx][ny] = True
                                stack.append((nx, ny))

                comp_color = max(color_count, key=lambda k: color_count[k])
                components.append({
                    "cells": cells,
                    "color": comp_color,
                    "size": len(cells),
                })

    if not components:
        return [[bg] * w for _ in range(h)]

    # The stamp is the largest non-background connected component.
    color_component_counts = {}
    for comp in components:
        color_component_counts[comp["color"]] = color_component_counts.get(comp["color"], 0) + 1

    def bbox_area(comp):
        rs = [r for r, _ in comp["cells"]]
        cs = [c for _, c in comp["cells"]]
        return (max(rs) - min(rs) + 1) * (max(cs) - min(cs) + 1)

    def comp_score(comp):
        # Prefer the usual case: largest shape; if tied, prefer a colour that
        # also appears as another component (the anchor pixel).
        return (
            comp["size"],
            bbox_area(comp),
            1 if color_component_counts.get(comp["color"], 0) > 1 else 0,
        )

    stamp = max(components, key=comp_score)
    stamp_color = stamp["color"]
    stamp_cells = set(stamp["cells"])

    rs = [r for r, _ in stamp_cells]
    cs = [c for _, c in stamp_cells]
    r0, r1 = min(rs), max(rs)
    c0, c1 = min(cs), max(cs)
    sh, sw = r1 - r0 + 1, c1 - c0 + 1

    # Boolean shape of the stamp, using only the stamp colour cells.
    shape = [[False] * sw for _ in range(sh)]
    for r, c in stamp_cells:
        if grid[r][c] == stamp_color:
            shape[r - r0][c - c0] = True

    # Control pattern: every non-background pixel not in the stamp component.
    control = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r, c) not in stamp_cells:
                control.append((r, c, grid[r][c]))

    if not control:
        return [[bg] * w for _ in range(h)]

    # The anchor is the control pixel having the stamp colour.
    anchor_candidates = [(r, c) for r, c, v in control if v == stamp_color]

    if anchor_candidates:
        if len(anchor_candidates) == 1:
            anchor_r, anchor_c = anchor_candidates[0]
        else:
            def valid_anchor(ar, ac):
                for r, c, _ in control:
                    if (r - ar) % 2 != 0 or (c - ac) % 2 != 0:
                        return False
                return True

            valid = [p for p in anchor_candidates if valid_anchor(*p)]
            pool = valid if valid else anchor_candidates
            anchor_r, anchor_c = min(
                pool,
                key=lambda p: sum((r - p[0]) ** 2 + (c - p[1]) ** 2 for r, c, _ in control)
            )
    else:
        # Fallback: use the visually central control pixel.
        anchor_r, anchor_c = min(
            [(r, c) for r, c, _ in control],
            key=lambda p: sum(abs(r - p[0]) + abs(c - p[1]) for r, c, _ in control)
        )

    # Marker colour is the non-stamp colour in the control pattern.
    marker_counts = {}
    for _, _, v in control:
        if v != stamp_color:
            marker_counts[v] = marker_counts.get(v, 0) + 1

    if marker_counts:
        marker_color = max(marker_counts, key=lambda k: marker_counts[k])
    else:
        marker_color = (stamp_color + 1) % 10

    out = [[bg] * w for _ in range(h)]

    # Place one stamp copy for each control pixel.
    # Offsets are scaled by 2 in the control pattern.
    for r, c, v in control:
        if (r - anchor_r) % 2 != 0 or (c - anchor_c) % 2 != 0:
            continue

        dr = (r - anchor_r) // 2
        dc = (c - anchor_c) // 2

        tr = r0 + dr * sh
        tc = c0 + dc * sw

        copy_color = marker_color if v == stamp_color else stamp_color

        for i in range(sh):
            for j in range(sw):
                if shape[i][j]:
                    nr, nc = tr + i, tc + j
                    if 0 <= nr < h and 0 <= nc < w:
                        out[nr][nc] = copy_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import defaultdict

    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    pts_by_color = defaultdict(list)
    for r in range(H):
        for c in range(W):
            if g[r, c] != 0:
                pts_by_color[int(g[r, c])].append((r, c))

    def dist(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    def same_color_edges(pts):
        pts = list(pts)
        edges = set()
        if len(pts) <= 1:
            return edges
        for i, a in enumerate(pts):
            ds = []
            for j, b in enumerate(pts):
                if i != j:
                    ds.append((dist(a, b), j))
            m = min(d for d, _ in ds)
            for d, j in ds:
                if d == m:
                    a2, b2 = a, pts[j]
                    if (b2[0], b2[1]) < (a2[0], a2[1]):
                        a2, b2 = b2, a2
                    edges.add((a2, b2))
        return edges

    def draw_line(a, b, color):
        x0, y0 = a
        x1, y1 = b
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        x, y = x0, y0
        while True:
            if 0 <= x < H and 0 <= y < W:
                out[x, y] = color
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x += sx
            if e2 <= dx:
                err += dx
                y += sy

    def adjacent_offsets(cell):
        x, y = cell
        offs = set()
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                offs.add((x + dx, y + dy))
        return offs

    # Draw primary same-color nearest-neighbor connections.
    for color, pts in pts_by_color.items():
        for a, b in same_color_edges(pts):
            draw_line(a, b, color)

    # Secondary parallel lines from a single-color "satellite" attached
    # to a pixel that participates in same-color connections.
    for color, pts in pts_by_color.items():
        if len(pts) != 1:
            continue
        p = pts[0]
        for dr, dc in ((1, -1), (0, -1), (-1, -1)):
            q = (p[0] - dr, p[1] - dc)
            if not (0 <= q[0] < H and 0 <= q[1] < W):
                continue
            if g[q[0], q[1]] != 0:
                continue
            # Find a same-color segment adjacent to q.
            target = None
            for ocolor, opt in pts_by_color.items():
                if ocolor == color:
                    continue
                if q not in opt:
                    continue
                for (a, b) in same_color_edges(opt):
                    if a == q or b == q:
                        # other endpoint of the segment
                        other = b if a == q else a
                        # The satellite offset must point toward/along that segment.
                        # Use the first valid consistent direction.
                        target = (ocolor, a, b)
                        break
                if target:
                    break
            if not target:
                continue
            ocolor, a, b = target
            # Draw parallel satellite line: shift the segment by the satellite offset,
            # skipping cells that would overwrite the original main line.
            sx, sy = p[0] - a[0] if a == q else p[0] - b[0], p[1] - a[1] if a == q else p[1] - b[1]
            # Simpler: draw from p toward the shifted other endpoint.
            other = b if a == q else a
            end = (other[0] + (p[0] - q[0]), other[1] + (p[1] - q[1]))
            draw_line(p, end, color)
            break

    # If a satellite is attached above a horizontal segment, draw a short cap.
    for color, pts in pts_by_color.items():
        if len(pts) != 1:
            continue
        p = pts[0]
        q = (p[0] + 1, p[1])
        if 0 <= q[0] < H and 0 <= q[1] < W and g[q[0], q[1]] != 0:
            ocolor = int(g[q[0], q[1]])
            if ocolor in pts_by_color and q in pts_by_color[ocolor]:
                for (a, b) in same_color_edges(pts_by_color[ocolor]):
                    if a == q or b == q:
                        if a[0] == b[0]:  # horizontal
                            if out[p[0], p[1]] == color:
                                # draw one cell left and right if free
                                for dc in (-1, 1):
                                    c2 = p[1] + dc
                                    if 0 <= c2 < W and out[p[0], c2] == 0:
                                        out[p[0], c2] = color
                        break

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math
    from functools import reduce

    def gcd(a, b):
        a, b = abs(int(a)), abs(int(b))
        while b:
            a, b = b, a % b
        return a if a else 1

    def seg_cells(a, b):
        r0, c0 = a
        r1, c1 = b
        if r0 == r1:
            step = 1 if c1 >= c0 else -1
            return [(r0, c) for c in range(c0, c1 + step, step)]
        if c0 == c1:
            step = 1 if r1 >= r0 else -1
            return [(r, c0) for r in range(r0, r1 + step, step)]
        if abs(r1 - r0) == abs(c1 - c0):
            rs = 1 if r1 >= r0 else -1
            cs = 1 if c1 >= c0 else -1
            n = abs(r1 - r0) + 1
            return [(r0 + rs * i, c0 + cs * i) for i in range(n)]
        return [(r0, c0), (r1, c1)]

    def ccw(a, b, c):
        return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

    def convex_hull_simple(points):
        pts = sorted(set(points))
        if len(pts) <= 1:
            return pts
        lower = []
        for p in pts:
            while len(lower) >= 2 and ccw(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and ccw(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        return lower[:-1] + upper[:-1]

    def is_axis_or_diag(a, b):
        dr = abs(a[0] - b[0])
        dc = abs(a[1] - b[1])
        return dr == 0 or dc == 0 or dr == dc

    def nearest_edge_edges(pts):
        pts = list(pts)
        n = len(pts)
        if n < 2:
            return set()
        edges = set()
        for i in range(n):
            ds = []
            for j in range(n):
                if i == j:
                    continue
                d = (pts[i][0] - pts[j][0]) ** 2 + (pts[i][1] - pts[j][1]) ** 2
                ds.append((d, j))
            m = min(d for d, _ in ds)
            for d, j in ds:
                if d == m:
                    e = tuple(sorted((tuple(pts[i]), tuple(pts[j]))))
                    edges.add(e)
        return edges

    def color_edges(pts):
        pts = list(pts)
        if len(pts) <= 1:
            return set()
        edges = set()
        n = len(pts)
        same_axis_or_diag = True
        for i in range(n):
            for j in range(i + 1, n):
                if not is_axis_or_diag(pts[i], pts[j]):
                    same_axis_or_diag = False
        if same_axis_or_diag:
            # Connect every pair that is axis-aligned or diagonal.
            for i in range(n):
                for j in range(i + 1, n):
                    if is_axis_or_diag(pts[i], pts[j]):
                        edges.add(tuple(sorted((tuple(pts[i]), tuple(pts[j])))))
            return edges

        hull = convex_hull_simple(pts)
        k = len(hull)
        for i in range(k):
            a = tuple(hull[i])
            b = tuple(hull[(i + 1) % k])
            if a != b:
                edges.add(tuple(sorted((a, b))))
        return edges

    def cells_for_color(pts):
        edges = color_edges(pts)
        cells = set(tuple(p) for p in pts)
        for a, b in edges:
            cells.update(seg_cells(a, b))
        return cells, edges

    out = [row[:] for row in grid]
    H, W = len(out), len(out[0])

    # Collect input points by color.
    by_color = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0:
                by_color.setdefault(v, []).append((r, c))

    # Draw full color graphs.
    color_graph_cells = {}
    color_graph_edges = {}
    for color, pts in by_color.items():
        cells, edges = cells_for_color(pts)
        color_graph_cells[color] = cells
        color_graph_edges[color] = edges
        for (r, c) in cells:
            if 0 <= r < H and 0 <= c < W:
                out[r][c] = color

    # Satellite copies: single-cell color adjacent to one endpoint of another
    # color's graph. Translate that graph by the offset and paint only cells
    # that are still empty.
    for color, pts in list(by_color.items()):
        if len(pts) != 1:
            continue
        s = pts[0]
        for other, other_pts in by_color.items():
            if other == color or len(other_pts) < 2:
                continue
            edges = color_graph_edges[other]
            endpoints = set()
            for a, b in edges:
                endpoints.add(a)
                endpoints.add(b)
            for ep in endpoints:
                dr = s[0] - ep[0]
                dc = s[1] - ep[1]
                if abs(dr) + abs(dc) == 1:
                    cells, _ = cells_for_color(other_pts)
                    for (r, c) in cells:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W and out[nr][nc] == 0:
                            out[nr][nc] = color
                    break
            else:
                continue
            break

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import math

    H = len(grid)
    W = len(grid[0]) if H else 0

    out = [row[:] for row in grid]

    def set_cell(r, c, v):
        if 0 <= r < H and 0 <= c < W:
            out[r][c] = v

    def draw_line8(p, q, color):
        r1, c1 = p
        r2, c2 = q
        if r1 == r2:
            lo, hi = min(c1, c2), max(c1, c2)
            for c in range(lo, hi + 1):
                set_cell(r1, c, color)
        elif c1 == c2:
            lo, hi = min(r1, r2), max(r1, r2)
            for r in range(lo, hi + 1):
                set_cell(r, c1, color)
        elif abs(r1 - r2) == abs(c1 - c2):
            step_r = 1 if r2 > r1 else -1
            step_c = 1 if c2 > c1 else -1
            r, c = r1, c1
            while True:
                set_cell(r, c, color)
                if r == r2 and c == c2:
                    break
                r += step_r
                c += step_c
        else:
            return

    def draw_line4(p, q, color):
        r1, c1 = p
        r2, c2 = q
        if r1 == r2:
            lo, hi = min(c1, c2), max(c1, c2)
            for c in range(lo, hi + 1):
                set_cell(r1, c, color)
        elif c1 == c2:
            lo, hi = min(r1, r2), max(r1, r2)
            for r in range(lo, hi + 1):
                set_cell(r, c1, color)
        else:
            g = math.gcd(abs(r1 - r2), abs(c1 - c2))
            sr = (r2 - r1) // g
            sc = (c2 - c1) // g
            r, c = r1, c1
            for _ in range(g + 1):
                set_cell(r, c, color)
                r += sr
                c += sc

    def draw_rectangle(p, q, color):
        r1, c1 = p
        r2, c2 = q
        r_lo, r_hi = min(r1, r2), max(r1, r2)
        c_lo, c_hi = min(c1, c2), max(c1, c2)
        for c in range(c_lo, c_hi + 1):
            set_cell(r_lo, c, color)
            set_cell(r_hi, c, color)
        for r in range(r_lo, r_hi + 1):
            set_cell(r, c_lo, color)
            set_cell(r, c_hi, color)

    by_color = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0:
                by_color.setdefault(v, []).append((r, c))

    for color, pts in by_color.items():
        if len(pts) < 2:
            continue

        if len(pts) == 2:
            draw_line8(pts[0], pts[1], color)
            continue

        if len(pts) == 3:
            draw_line8(pts[0], pts[1], color)
            draw_line8(pts[1], pts[2], color)
            continue

        draw_rectangle(pts[0], pts[2], color)
        draw_rectangle(pts[1], pts[3], color)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0

    # Preserve original input points; all final drawings are applied on top.
    out = [row[:] for row in grid]

    def inside(r, c):
        return 0 <= r < H and 0 <= c < W

    def set_cell(r, c, v):
        if inside(r, c):
            out[r][c] = v

    def draw_line_8(p, q, color):
        r1, c1 = p
        r2, c2 = q

        # Draw only the line if it is one of the 8 straight directions.
        if r1 != r2 and c1 != c2 and abs(r1 - r2) != abs(c1 - c2):
            return

        if r1 == r2:
            lo, hi = min(c1, c2), max(c1, c2)
            for c in range(lo, hi + 1):
                set_cell(r1, c, color)
        elif c1 == c2:
            lo, hi = min(r1, r2), max(r1, r2)
            for r in range(lo, hi + 1):
                set_cell(r, c1, color)
        else:
            sr = 1 if r2 > r1 else -1
            sc = 1 if c2 > c1 else -1
            r, c = r1, c1
            while True:
                set_cell(r, c, color)
                if r == r2 and c == c2:
                    break
                r += sr
                c += sc

    # Group input points by color.
    pts_by_color = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0:
                pts_by_color.setdefault(v, []).append((r, c))

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def convex_hull(points):
        # Standard monotone chain. Returns vertices in CCW order.
        pts = sorted(set(points))
        if len(pts) <= 2:
            return pts

        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)

        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)

        hull = lower[:-1] + upper[:-1]

        # For collinear sets, keep only the two endpoints.
        if len(hull) > 2:
            a, b, c = hull[0], hull[1], hull[2]
            if cross(a, b, c) == 0:
                hull = [min(hull), max(hull)]
        return hull

    def draw_shape(color, points, offset=(0, 0), overwrite=True):
        """
        Draw the 8-directional convex-hull boundary of a color's points.
        Edges that are not horizontal, vertical, or 45-degree diagonal are skipped.
        """
        if len(points) < 2:
            return

        hull = convex_hull(points)
        if len(hull) < 2:
            return

        for i in range(len(hull)):
            p = hull[i]
            q = hull[(i + 1) % len(hull)]
            if offset:
                p = (p[0] + offset[0], p[1] + offset[1])
                q = (q[0] + offset[0], q[1] + offset[1])
            draw_line_8(p, q, color)

    # 1) Draw every color's own shape (only if it has at least two pixels).
    for color, pts in pts_by_color.items():
        if len(pts) >= 2:
            draw_shape(color, pts, offset=(0, 0), overwrite=True)

    # 2) A lone pixel directly above-left of another pixel acts as a shadow
    #    of that other pixel's color shape, shifted one cell up-left.
    for color, pts in pts_by_color.items():
        if len(pts) != 1:
            continue

        r, c = pts[0]
        r2, c2 = r + 1, c + 1
        if not inside(r2, c2):
            continue

        base_color = grid[r2][c2]
        if base_color == 0 or base_color == color:
            continue

        base_pts = pts_by_color.get(base_color, [])
        if len(base_pts) < 2:
            continue

        # Draw shadow first in logical order, but since main shapes were already
        # drawn, only place shadow where current cell is background or shadow color.
        hull = convex_hull(base_pts)
        if len(hull) < 2:
            continue

        for i in range(len(hull)):
            p = hull[i]
            q = hull[(i + 1) % len(hull)]
            p = (p[0] - 1, p[1] - 1)
            q = (q[0] - 1, q[1] - 1)

            # Only draw 8-directional edges.
            dr = q[0] - p[0]
            dc = q[1] - p[1]
            if p[0] != q[0] and p[1] != q[1] and abs(dr) != abs(dc):
                continue

            if p[0] == q[0]:
                lo, hi = min(p[1], q[1]), max(p[1], q[1])
                for c in range(lo, hi + 1):
                    if inside(p[0], c) and out[p[0]][c] == 0:
                        out[p[0]][c] = color
            elif p[1] == q[1]:
                lo, hi = min(p[0], q[0]), max(p[0], q[0])
                for r in range(lo, hi + 1):
                    if inside(r, p[1]) and out[r][p[1]] == 0:
                        out[r][p[1]] = color
            else:
                sr = 1 if q[0] > p[0] else -1
                sc = 1 if q[1] > p[1] else -1
                rr, cc = p
                while True:
                    if inside(rr, cc) and out[rr][cc] == 0:
                        out[rr][cc] = color
                    if rr == q[0] and cc == q[1]:
                        break
                    rr += sr
                    cc += sc

    # Ensure values are plain Python ints in a 2D list.
    return [[int(v) for v in row] for row in out]

import math

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0

    def gcd(a, b):
        a = abs(a)
        b = abs(b)
        while b:
            a, b = b, a % b
        return a

    def rasterize(r1, c1, r2, c2):
        if r1 == r2 and c1 == c2:
            return [(r1, c1)]
        dr = r2 - r1
        dc = c2 - c1
        g = gcd(dr, dc)
        return [(r1 + i * (dr // g), c1 + i * (dc // g)) for i in range(g + 1)]

    def out_of_bounds(p):
        r, c = p
        return r < 0 or r >= H or c < 0 or c >= W

    # Draw the outline of the axis-aligned bounding box of a set of points.
    def draw_bbox(points, color):
        if not points:
            return
        rows = [r for r, c in points]
        cols = [c for r, c in points]
        r1, r2 = min(rows), max(rows)
        c1, c2 = min(cols), max(cols)
        segs = [
            ((r1, c1), (r1, c2)),
            ((r2, c1), (r2, c2)),
            ((r1, c1), (r2, c1)),
            ((r1, c2), (r2, c2)),
        ]
        for a, b in segs:
            for p in rasterize(*a, *b):
                if 0 <= p[0] < H and 0 <= p[1] < W:
                    out[p[0]][p[1]] = color

    # Draw a line segment with a small perpendicular offset.
    def draw_offset_segment(a, b, color):
        r1, c1 = a
        r2, c2 = b
        if (r1, c1) == (r2, c2):
            return
        dr = r2 - r1
        dc = c2 - c1
        n = gcd(dr, dc)
        sr, sc = dr // n, dc // n
        # Two unit normal directions in grid coordinates.
        off1 = (sc, -sr)
        off2 = (-sc, sr)
        # Prefer the normal whose first drawn interior point is inside;
        # if both are inside, prefer positive row offset (downward).
        candidates = []
        for off in (off1, off2):
            mid = ((r1 + r2) // 2 + off[0], (c1 + c2) // 2 + off[1])
            if not out_of_bounds(mid):
                candidates.append((off[0] >= 0, off))
        if not candidates:
            candidates = [(False, off1)]
        candidates.sort(reverse=True)
        off = candidates[0][1]
        a2 = (r1 + off[0], c1 + off[1])
        b2 = (r2 + off[0], c2 + off[1])
        for p in rasterize(*a2, *b2):
            if 0 <= p[0] < H and 0 <= p[1] < W:
                out[p[0]][p[1]] = color

    # Draw the boundary of the convex hull of a set of points.
    def draw_convex_hull(points, color):
        pts = sorted(set(points))
        if len(pts) <= 1:
            for r, c in pts:
                if 0 <= r < H and 0 <= c < W:
                    out[r][c] = color
            return
        if len(pts) == 2:
            for p in rasterize(*pts[0], *pts[1]):
                if 0 <= p[0] < H and 0 <= p[1] < W:
                    out[p[0]][p[1]] = color
            return

        def cross(o, a, b):
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

        def hull(points):
            lower = []
            for p in points:
                while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                    lower.pop()
                lower.append(p)
            upper = []
            for p in reversed(points):
                while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                    upper.pop()
                upper.append(p)
            return lower[:-1] + upper[:-1]

        hp = hull(pts)
        for i in range(len(hp)):
            draw_offset_segment(hp[i], hp[(i + 1) % len(hp)], color)

    out = [row[:] for row in grid]

    colors = sorted({grid[r][c] for r in range(H) for c in range(W) if grid[r][c] != 0},
                    key=lambda x: -x)

    for col in colors:
        pts = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == col]
        if len(pts) >= 3:
            draw_convex_hull(pts, col)
        elif len(pts) == 2:
            for p in rasterize(*pts[0], *pts[1]):
                if 0 <= p[0] < H and 0 <= p[1] < W:
                    out[p[0]][p[1]] = col
        else:
            # Single marker: draw the bounding box of the next lower non-zero color,
            # with this color, if such a color exists.
            anchor = None
            for other in colors:
                if other >= col:
                    continue
                other_pts = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == other]
                if other_pts:
                    anchor = other_pts
                    break
            if anchor:
                draw_bbox(anchor, col)
            else:
                out[pts[0][0]][pts[0][1]] = col

    return out

import math

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    def gcd(a, b):
        a, b = abs(a), abs(b)
        while b:
            a, b = b, a % b
        return a

    def inb(r, c):
        return 0 <= r < H and 0 <= c < W

    def line_pts(a, b):
        r1, c1 = a
        r2, c2 = b
        if r1 == r2 and c1 == c2:
            return [a]
        dr = r2 - r1
        dc = c2 - c1
        g = gcd(dr, dc)
        if g == 0:
            return [a]
        sr, sc = dr // g, dc // g
        return [(r1 + i * sr, c1 + i * sc) for i in range(g + 1)]

    def convex_hull(pts):
        pts = sorted(set(pts))
        if len(pts) <= 1:
            return pts
        def cross(o, a, b):
            return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        return lower[:-1] + upper[:-1]

    def bbox(pts):
        rows = [r for r, c in pts]
        cols = [c for r, c in pts]
        return min(rows), max(rows), min(cols), max(cols)

    def shape_points_for_color(pts):
        pts = sorted(set(pts))
        if len(pts) == 1:
            return [pts[0]]
        if len(pts) == 2:
            return line_pts(pts[0], pts[1])
        hull = convex_hull(pts)
        res = []
        if len(hull) <= 2:
            for a, b in zip(hull, hull[1:] + hull[:1]):
                res.extend(line_pts(a, b))
        else:
            for i in range(len(hull)):
                res.extend(line_pts(hull[i], hull[(i + 1) % len(hull)]))
        return sorted(set(res))

    # collect points per color
    color_pts = {}
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v != 0:
                color_pts.setdefault(v, []).append((r, c))

    # base shapes for colors with at least 2 points
    base_shapes = {}
    for col, pts in color_pts.items():
        if len(pts) >= 2:
            base_shapes[col] = shape_points_for_color(pts)

    # attach singleton colors to nearby base shapes
    attachments = []  # (single_color, base_color, shift, adjacent_base_pt)
    singles = [col for col, pts in color_pts.items() if len(pts) == 1]
    singles.sort()

    used_base_attachments = {}
    for s in singles:
        (sr, sc) = color_pts[s][0]
        candidates = []
        for bcol, bpts in color_pts.items():
            if len(bpts) < 2:
                continue
            for bp in bpts:
                if (bp[0], bp[1]) == (sr, sc):
                    continue
                if abs(bp[0] - sr) <= 1 and abs(bp[1] - sc) <= 1:
                    dr = sr - bp[0]
                    dc = sc - bp[1]
                    # Prefer shift that is purely horizontal/vertical, then smaller Manhattan distance.
                    pure = 0 if (dr == 0 or dc == 0) else 1
                    candidates.append((pure, abs(dr) + abs(dc), bcol, bp, (dr, dc)))
        if candidates:
            candidates.sort()
            pure, _, bcol, bp, shift = candidates[0]
            attachments.append((s, bcol, shift, bp))

    # Build output: first draw attached singleton copies, then base shapes on top.
    out = [[0] * W for _ in range(H)]

    # Draw singleton attachments (offset copies of base shapes)
    for s, bcol, (dr, dc), bp in attachments:
        if bcol not in base_shapes:
            continue
        for (r, c) in base_shapes[bcol]:
            nr, nc = r + dr, c + dc
            if inb(nr, nc):
                out[nr][nc] = s

    # Draw base shapes (colors with >=2 points)
    # Order does not matter much because base shapes of different colors are expected not to conflict
    # in the provided rule; still, draw in descending color order for determinism.
    for col in sorted(base_shapes.keys(), reverse=True):
        for (r, c) in base_shapes[col]:
            if inb(r, c):
                out[r][c] = col

    # Preserve singleton colors that had no attachment (plain dots)
    attached_singles = {s for s, _, _, _ in attachments}
    for s in singles:
        if s in attached_singles:
            continue
        r, c = color_pts[s][0]
        out[r][c] = s

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    bg = 7

    dirs = [(0, 1), (1, 0), (1, 1), (1, -1)]
    seen = set()
    segs = []

    def in_grid(r, c):
        return 0 <= r < h and 0 <= c < w

    def cell_val(r, c):
        return grid[r][c]

    for r in range(h):
        for c in range(w):
            col = cell_val(r, c)
            if col == bg:
                continue
            for dr, dc in dirs:
                # Make sure (r,c) is the starting point of the maximal segment
                if in_grid(r - dr, c - dc) and cell_val(r - dr, c - dc) == col:
                    continue
                # Find end of segment
                er, ec = r, c
                nr, nc = r + dr, c + dc
                while in_grid(nr, nc) and cell_val(nr, nc) == col:
                    er, ec = nr, nc
                    nr, nc = nr + dr, nc + dc
                length = max(1, int(np.hypot(abs(er - r), abs(ec - c)) + 1))
                key = (r, c, er, ec)
                if key not in seen:
                    seen.add(key)
                    segs.append({
                        "col": col,
                        "start": (r, c),
                        "end": (er, ec),
                        "dr": dr,
                        "dc": dc,
                        "len": length
                    })

    # If no segments found, return original grid
    if not segs:
        return out

    # Target length: median spatial line's length
    # Spatial key:
    # horizontal -> row
    # vertical -> col
    # diagonal -> r + c for (1,-1), r - c for (1,1)
    def spatial_key(seg):
        dr, dc = seg["dr"], seg["dc"]
        r, c = seg["start"]
        if dr == 0:
            return (0, r, c)
        if dc == 0:
            return (0, c, r)
        if dr == 1 and dc == -1:
            return (0, r + c, r)
        if dr == 1 and dc == 1:
            return (0, r - c, r)
        # fallback
        return (0, r, c)

    sorted_segs = sorted(segs, key=spatial_key)
    median_seg = sorted_segs[len(sorted_segs) // 2]
    target_len = median_seg["len"]

    # Build output on background
    for r in range(h):
        for c in range(w):
            if out[r][c] != bg:
                out[r][c] = bg

    # Draw each segment with target length, keeping the same start/end policy:
    # For horizontal/vertical: keep aligned endpoint (start if left/top-aligned).
    # For diagonal: keep the lower endpoint (maximum row) fixed and extend upward.
    for seg in segs:
        col = seg["col"]
        r0, c0 = seg["start"]
        r1, c1 = seg["end"]
        dr, dc = seg["dr"], seg["dc"]
        L = target_len

        if dr == 0 and dc == 1:
            # horizontal, left-anchored
            rr, cc = r0, c0
            for _ in range(L):
                if in_grid(rr, cc):
                    out[rr][cc] = col
                cc += dc
        elif dr == 0 and dc == -1:
            rr, cc = r0, c0
            for _ in range(L):
                if in_grid(rr, cc):
                    out[rr][cc] = col
                cc += dc
        elif dr == 1 and dc == 0:
            # vertical, top-anchored
            rr, cc = r0, c0
            for _ in range(L):
                if in_grid(rr, cc):
                    out[rr][cc] = col
                rr += dr
        elif dr == 1 and dc == -1:
            # diagonal down-left: keep bottom endpoint fixed
            br, bc = r1, c1
            rr, cc = br - (L - 1) * dr, bc - (L - 1) * dc
            for _ in range(L):
                if in_grid(rr, cc):
                    out[rr][cc] = col
                rr += dr
                cc += dc
        elif dr == 1 and dc == 1:
            # diagonal down-right: keep bottom endpoint fixed
            br, bc = r1, c1
            rr, cc = br - (L - 1) * dr, bc - (L - 1) * dc
            for _ in range(L):
                if in_grid(rr, cc):
                    out[rr][cc] = col
                rr += dr
                cc += dc
        else:
            # fallback: keep start
            rr, cc = r0, c0
            for _ in range(L):
                if in_grid(rr, cc):
                    out[rr][cc] = col
                rr += dr
                cc += dc

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if grid is None:
        return []

    # Allow a single string row as input, though normal input is 2D.
    if isinstance(grid, str):
        grid = [grid]

    H = len(grid)
    if H == 0:
        return []

    # Convert to plain Python ints/lists; also handles list-of-strings or numpy rows.
    grid = [list(map(int, row)) for row in grid]

    W = len(grid[0]) if grid[0] else 0
    if W == 0:
        return []

    visited = [[False] * W for _ in range(H)]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Each object is stored as: (top_row, left_col, is_hollow, crop)
    objects = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0 or visited[r][c]:
                continue

            color = grid[r][c]
            stack = [(r, c)]
            visited[r][c] = True

            min_r = max_r = r
            min_c = max_c = c

            while stack:
                x, y = stack.pop()

                if x < min_r:
                    min_r = x
                if x > max_r:
                    max_r = x
                if y < min_c:
                    min_c = y
                if y > max_c:
                    max_c = y

                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W:
                        if not visited[nx][ny] and grid[nx][ny] == color:
                            visited[nx][ny] = True
                            stack.append((nx, ny))

            crop = [grid[x][min_c:max_c + 1] for x in range(min_r, max_r + 1)]
            h = max_r - min_r + 1
            w = max_c - min_c + 1

            hollow = False
            if h > 2 and w > 2:
                for rr in range(1, h - 1):
                    if 0 in crop[rr][1:-1]:
                        hollow = True
                        break

            objects.append((min_r, min_c, hollow, crop))

    frames = [obj for obj in objects if obj[2]]
    solids = [obj for obj in objects if not obj[2]]

    frames.sort(key=lambda obj: (obj[0], obj[1]))
    solids.sort(key=lambda obj: (obj[0], obj[1]))

    n = max(len(frames), len(solids))
    if n == 0:
        return []

    left_w = max((len(obj[3][0]) for obj in frames), default=0)
    right_w = max((len(obj[3][0]) for obj in solids), default=0)
    width = left_w + right_w

    out = []

    for i in range(n):
        frame = frames[i] if i < len(frames) else None
        solid = solids[i] if i < len(solids) else None

        row_h = 0
        if frame is not None:
            row_h = max(row_h, len(frame[3]))
        if solid is not None:
            row_h = max(row_h, len(solid[3]))

        if row_h == 0:
            continue

        row = [[0] * width for _ in range(row_h)]

        if frame is not None:
            crop = frame[3]
            for rr, src_row in enumerate(crop):
                if rr >= row_h:
                    break
                for cc, val in enumerate(src_row):
                    if cc >= left_w:
                        break
                    row[rr][cc] = val

        if solid is not None:
            crop = solid[3]
            for rr, src_row in enumerate(crop):
                if rr >= row_h:
                    break
                for cc, val in enumerate(src_row):
                    if cc >= right_w:
                        break
                    row[rr][left_w + cc] = val

        out.extend(row)

    return out

import numpy as np
from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the border color.  If the border is not uniform, fall back
    # to the most common colour on the border.
    border = np.concatenate([
        g[0, :], g[-1, :], g[:, 0], g[:, -1]
    ])
    bg = Counter(border.tolist()).most_common(1)[0][0]

    def ring_is_bg(r, c, s):
        """True if the one-cell ring around an s x s box is background
        (out-of-bounds cells are treated as background)."""
        i0 = max(0, r - 1)
        i1 = min(h, r + s + 1)
        j0 = max(0, c - 1)
        j1 = min(w, c + s + 1)

        for i in range(i0, i1):
            for j in range(j0, j1):
                if r <= i < r + s and c <= j < c + s:
                    continue
                if g[i, j] != bg:
                    return False
        return True

    # Find all isolated 5 x 5 solid blocks.
    blocks = []
    for r in range(h - 4):
        for c in range(w - 4):
            col = int(g[r, c])
            if col == bg:
                continue
            block = g[r:r + 5, c:c + 5]
            if block.size and np.all(block == col) and ring_is_bg(r, c, 5):
                blocks.append((r, c, col))

    if not blocks:
        return [row[:] for row in grid]

    # Find all isolated 3 x 3 two-colour patterns.
    # A pattern is a 3 x 3 box containing exactly one non-background colour
    # and at least one background cell, with a one-cell background margin.
    patterns = {}
    for r in range(h - 2):
        for c in range(w - 2):
            pat = g[r:r + 3, c:c + 3]
            colours = set(int(x) for x in pat.tolist())
            non_bg = colours - {bg}
            if len(non_bg) != 1 or bg not in colours:
                continue
            col = int(next(iter(non_bg)))
            if ring_is_bg(r, c, 3):
                # If there are several candidates of the same colour, keep one.
                # The intended instances in this puzzle family are unique.
                if col not in patterns:
                    patterns[col] = pat

    # Crop to the bounding box of the solid blocks plus one border cell.
    min_r = min(r for r, c, _ in blocks)
    max_r = max(r + 4 for r, c, _ in blocks)
    min_c = min(c for r, c, _ in blocks)
    max_c = max(c + 4 for r, c, _ in blocks)

    top = min_r - 1
    left = min_c - 1
    out_h = (max_r - min_r + 1) + 2
    out_w = (max_c - min_c + 1) + 2

    out = np.full((out_h, out_w), bg, dtype=int)

    for r, c, col in blocks:
        orow = r - top
        ocol = c - left

        # 5 x 5 solid border.
        out[orow:orow + 5, ocol:ocol + 5] = col

        # Inner 3 x 3 is the complement of the matching 3 x 3 pattern.
        if col in patterns:
            pat = patterns[col]
            for i in range(3):
                for j in range(3):
                    out[orow + 1 + i, ocol + 1 + j] = (
                        bg if int(pat[i, j]) == col else col
                    )
        # If a pattern is missing, the block simply remains solid.

    return out.tolist()

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Convert to a rectangular Python list of ints.
    grid = [[int(v) for v in row] for row in grid]
    h = len(grid)
    w = len(grid[0])

    # Background is the border colour.  If the border is not uniform,
    # fall back to the most common colour in the whole grid.
    border = (
        grid[0] + grid[-1] +
        [grid[i][0] for i in range(h)] +
        [grid[i][-1] for i in range(h)]
    )
    if len(set(border)) == 1:
        bg = border[0]
    else:
        bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def ring_is_bg(r: int, c: int, s: int) -> bool:
        """One-cell margin around an s x s box is background."""
        for i in range(max(0, r - 1), min(h, r + s + 1)):
            for j in range(max(0, c - 1), min(w, c + s + 1)):
                if r <= i < r + s and c <= j < c + s:
                    continue
                if grid[i][j] != bg:
                    return False
        return True

    # Find isolated solid 5 x 5 blocks.
    blocks = []
    for r in range(h - 4):
        for c in range(w - 4):
            col = grid[r][c]
            if col == bg:
                continue

            solid = True
            for i in range(r, r + 5):
                row = grid[i]
                for j in range(c, c + 5):
                    if row[j] != col:
                        solid = False
                        break
                if not solid:
                    break

            if solid and ring_is_bg(r, c, 5):
                blocks.append((r, c, col))

    if not blocks:
        return [row[:] for row in grid]

    # Find isolated 3 x 3 binary patterns: one non-background colour + bg.
    patterns = {}
    for r in range(h - 2):
        for c in range(w - 2):
            vals = [
                grid[r + di][c + dj]
                for di in range(3)
                for dj in range(3)
            ]
            non_bg = {v for v in vals if v != bg}
            if len(non_bg) != 1 or bg not in vals:
                continue

            col = next(iter(non_bg))
            if ring_is_bg(r, c, 3) and col not in patterns:
                patterns[col] = [
                    [grid[r + di][c + dj] for dj in range(3)]
                    for di in range(3)
                ]

    # Crop to the bounding box of all 5 x 5 blocks, expanded by one cell.
    min_r = min(r for r, _, _ in blocks)
    max_r = max(r + 4 for r, _, _ in blocks)
    min_c = min(c for _, c, _ in blocks)
    max_c = max(c + 4 for _, c, _ in blocks)

    top = max(0, min_r - 1)
    left = max(0, min_c - 1)

    out_h = (max_r + 1) - top + 1
    out_w = (max_c + 1) - left + 1

    out = [[bg] * out_w for _ in range(out_h)]

    # Fill each block: 5 x 5 border is its colour, inner 3 x 3 is
    # the inverted matching 3 x 3 pattern.
    for r, c, col in blocks:
        orow = r - top
        ocol = c - left

        for i in range(5):
            out[orow + i][ocol] = col
            out[orow + i][ocol + 4] = col
        for j in range(5):
            out[orow][ocol + j] = col
            out[orow + 4][ocol + j] = col

        pat = patterns.get(col)
        if pat is not None:
            for i in range(3):
                for j in range(3):
                    out[orow + 1 + i][ocol + 1 + j] = (
                        col if pat[i][j] == bg else bg
                    )

    return out

import numpy as np
from typing import List, Tuple

def _line_cells(p: Tuple[int, int], q: Tuple[int, int]) -> List[Tuple[int, int]]:
    r1, c1 = p
    r2, c2 = q
    dr = r2 - r1
    dc = c2 - c1
    steps = max(abs(dr), abs(dc))
    if steps == 0:
        return [p]
    cells = []
    for i in range(steps + 1):
        r = round(r1 + dr * i / steps)
        c = round(c1 + dc * i / steps)
        cells.append((int(r), int(c)))
    # remove consecutive duplicates if any
    out = []
    for cell in cells:
        if not out or out[-1] != cell:
            out.append(cell)
    return out

def _convex_hull(points: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    pts = sorted(set(points))
    if len(pts) <= 2:
        return pts
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def _is_simple_edge(a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    dr = abs(a[0] - b[0])
    dc = abs(a[1] - b[1])
    return dr == 0 or dc == 0 or dr == dc

def _draw_color_hull(grid, color: int, out: np.ndarray) -> None:
    cells = [(i, j) for i in range(out.shape[0]) for j in range(out.shape[1]) if grid[i][j] == color]
    if len(cells) <= 1:
        return
    hull = _convex_hull(cells)
    if not hull:
        return
    n = len(hull)
    for idx, p in enumerate(hull):
        q = hull[(idx + 1) % n]
        if p == q:
            continue
        if _is_simple_edge(p, q):
            for rr, cc in _line_cells(p, q):
                out[rr, cc] = color

def _draw_single_shadow(grid, color: int, partner: int, dr: int, dc: int, out: np.ndarray) -> None:
    # cells of partner color that will be considered the main shape
    partner_cells = [(i, j) for i in range(out.shape[0]) for j in range(out.shape[1]) if grid[i][j] == partner]
    if not partner_cells:
        return
    # draw partner hull first (already done globally)
    # shadow is partner's simple hull offset by (dr, dc), but avoid overwriting existing non-zero cells
    hull = _convex_hull(partner_cells)
    if not hull:
        return
    n = len(hull)
    for idx, p in enumerate(hull):
        q = hull[(idx + 1) % n]
        if p == q or not _is_simple_edge(p, q):
            continue
        for rr, cc in _line_cells(p, q):
            nr, nc = rr + dr, cc + dc
            if 0 <= nr < out.shape[0] and 0 <= nc < out.shape[1] and out[nr, nc] == 0:
                out[nr, nc] = color

def transform(grid: list[list[int]]) -> list[list[int]]:
    h, w = len(grid), len(grid[0])
    out = np.zeros((h, w), dtype=int)

    # Preserve all input pixels initially; output will overwrite/extend them.
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                out[i, j] = grid[i][j]

    colors = set()
    for row in grid:
        for v in row:
            if v != 0:
                colors.add(v)

    # 1) For every color with multiple pixels, draw the simple-edge convex hull.
    for c in sorted(colors):
        _draw_color_hull(grid, c, out)

    # 2) For diagonal single-pixel "shadow" pairs:
    #    If color A has exactly one pixel and is diagonally adjacent to color B,
    #    and B has multiple pixels, offset B's simple hull toward A.
    single_cells = {}
    for c in colors:
        cells = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == c]
        if len(cells) == 1:
            single_cells[c] = cells[0]

    for a, (r, c) in single_cells.items():
        for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
            rr, cc = r - dr, c - dc
            if 0 <= rr < h and 0 <= cc < w:
                b = grid[rr][cc]
                if b == a or b == 0:
                    continue
                count_b = sum(1 for row in grid for v in row if v == b)
                if count_b > 1:
                    _draw_single_shadow(grid, a, b, dr, dc, out)

    return out.astype(int).tolist()

