import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []
    H = len(grid)
    W = len(grid[0])

    out = [list(row) for row in grid]

    # Background: most common color.
    freq = {}
    for row in grid:
        for v in row:
            freq[v] = freq.get(v, 0) + 1
    bg = min(freq, key=lambda c: (-freq[c], c))

    # Non-background cells and 4-connected components.
    nonbg = [[False] * W for _ in range(H)]
    comp_id = [[-1] * W for _ in range(H)]
    comps = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg and comp_id[r][c] == -1:
                cid = len(comps)
                q = deque([(r, c)])
                comp_id[r][c] = cid
                cells = []
                while q:
                    x, y = q.popleft()
                    cells.append((x, y))
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if grid[nx][ny] != bg and comp_id[nx][ny] == -1:
                                comp_id[nx][ny] = cid
                                q.append((nx, ny))
                comps.append(cells)

    # Border markers: single-cell non-background components touching the border.
    markers = []  # (color, axis, line)
    for cid, cells in enumerate(comps):
        if len(cells) != 1:
            continue
        r, c = cells[0]
        border = []
        if r == 0:
            border.append(('h', c))
        if r == H - 1:
            border.append(('h', c))
        if c == 0:
            border.append(('v', r))
        if c == W - 1:
            border.append(('v', r))
        for axis, line in border:
            markers.append((grid[r][c], axis, line))

    if not markers:
        return out

    # For each object, choose one anchor if it has exactly one unique
    # marker-color cell that admits a consistent valid translation.
    moves = []

    for cid, cells in enumerate(comps):
        # Marker components themselves never move.
        if len(cells) == 1:
            r, c = cells[0]
            if r == 0 or r == H - 1 or c == 0 or c == W - 1:
                continue

        color_counts = {}
        for r, c in cells:
            v = grid[r][c]
            if v != bg:
                color_counts[v] = color_counts.get(v, 0) + 1

        candidate_keys = [
            (color, (r, c))
            for color, cnt in color_counts.items()
            if cnt == 1 and any(m[0] == color for m in markers)
            for r, c in cells
            if grid[r][c] == color
        ]

        # If no unique marker color, skip.
        if not candidate_keys:
            continue

        chosen = None
        # Prefer candidates whose translation keeps the whole component inside.
        for color, (ar, ac) in candidate_keys:
            for mcolor, axis, line in markers:
                if mcolor != color:
                    continue
                if axis == 'h':
                    dc = line - ac
                    dr = 0
                else:
                    dr = line - ar
                    dc = 0

                ok = True
                for r, c in cells:
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < H and 0 <= nc < W):
                        ok = False
                        break
                if ok:
                    chosen = (color, (ar, ac), axis, line, dr, dc)
                    break
            if chosen:
                break

        # If nothing fits, fall back to the first marker in reading order.
        if chosen is None:
            for color, (ar, ac) in candidate_keys:
                m = next((m for m in markers if m[0] == color), None)
                if m:
                    mcolor, axis, line = m
                    if axis == 'h':
                        dc = line - ac
                        dr = 0
                    else:
                        dr = line - ar
                        dc = 0
                    chosen = (color, (ar, ac), axis, line, dr, dc)
                    break

        if chosen is not None:
            moves.append((cid, chosen))

    # Clear all moving cells.
    for cid, (_, _, _, _, _, _) in moves:
        for r, c in comps[cid]:
            out[r][c] = bg

    # Draw moved components.
    for cid, (_, _, _, _, dr, dc) in moves:
        for r, c in comps[cid]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                out[nr][nc] = grid[r][c]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import deque

    h = len(grid)
    w = len(grid[0])

    # background is the most common color (also the corner color in all cases)
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=lambda k: (counts[k], k == grid[0][0]))

    # foreground pixels
    fg = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                fg.append((r, c))

    if not fg:
        return [[bg]]

    # crop to the bounding box of foreground
    rmin = min(r for r, _ in fg)
    rmax = max(r for r, _ in fg)
    cmin = min(c for _, c in fg)
    cmax = max(c for _, c in fg)

    H = rmax - rmin + 1
    W = cmax - cmin + 1

    def val(r, c):
        if 0 <= r < H and 0 <= c < W:
            return grid[rmin + r][cmin + c] != bg
        return False

    # flood-fill background regions that touch the cropped border
    visited = [[False] * W for _ in range(H)]
    q = deque()
    for r in range(H):
        for c in (0, W - 1):
            if not val(r, c) and not visited[r][c]:
                visited[r][c] = True
                q.append((r, c))
    for c in range(W):
        for r in (0, H - 1):
            if not val(r, c) and not visited[r][c]:
                visited[r][c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                if not visited[nr][nc] and not val(nr, nc):
                    visited[nr][nc] = True
                    q.append((nr, nc))

    # enclosed background regions become holes
    holes = set()
    for r in range(H):
        for c in range(W):
            if not val(r, c) and not visited[r][c]:
                holes.add((r, c))

    # For each hole:
    # - draw its full bounding-box border
    # - if it is exactly a 2x2 block, draw one center pixel
    out = [[bg] * W for _ in range(H)]
    for hole in holes:
        r0 = r1 = hole[0]
        c0 = c1 = hole[1]
        for (r, c) in holes:
            if abs(r - hole[0]) <= max(abs(r1 - r0), abs(c1 - c0)) and False:
                pass

    # group holes into connected components (4-connected)
    unprocessed = set(holes)
    for seed in list(unprocessed):
        comp = set()
        dq = deque([seed])
        unprocessed.remove(seed)
        while dq:
            r, c = dq.popleft()
            comp.add((r, c))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nb = (r + dr, c + dc)
                if nb in unprocessed:
                    unprocessed.remove(nb)
                    dq.append(nb)

        r0 = min(r for r, _ in comp)
        r1 = max(r for r, _ in comp)
        c0 = min(c for _, c in comp)
        c1 = max(c for _, c in comp)

        # bounding box border of this hole
        for r in range(r0, r1 + 1):
            out[r][c0] = grid[rmin + r][cmin + c0] if grid[rmin + r][cmin + c0] != bg else bg
            out[r][c1] = grid[rmin + r][cmin + c1] if grid[rmin + r][cmin + c1] != bg else bg
        for c in range(c0, c1 + 1):
            out[r0][c] = grid[rmin + r0][cmin + c] if grid[rmin + r0][cmin + c] != bg else bg
            out[r1][c] = grid[rmin + r1][cmin + c] if grid[rmin + r1][cmin + c] != bg else bg

        # if this hole is exactly a 2x2 square, put one center marker
        if len(comp) == 4 and (r1 - r0) == 1 and (c1 - c0) == 1:
