    # Rebuild a clean output: only border pixels of hole components + center markers.
    # Simpler: reset and redo, directly using fg_color for all output marks.
    out = [[bg] * W for _ in range(H)]
    unprocessed = set(holes)
    for seed in list(unprocessed):
        comp = set()
        dq = deque([seed])
        unprocessed.remove(seed)
