                # 4x4 corners + center 2x2
                if nonzeros == {(dr, dc) for dr in range(4) for dc in range(4)
                                if ((dr == 0 or dr == 3) and (dc == 0 or dc == 3)) or
                                (1 <= dr <= 2 and 1 <= dc <= 2)}:
                    stamp(r0, c0, 7, col)
                    for dr in range(4):
                        for dc in range(4):
                            protected.add((r0 + dr, c0 + dc))
                    continue

    # Pass 2: single-cell markers produce 4x4 stamps.
    marker_kind = {
        2: 4, 4: 4,
        3: 1, 1: 1,
        5: 6, 6: 6,
        8: 7, 7: 7,
    }
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in marker_kind and (r, c) not in protected:
                stamp(r, c, marker_kind[v], 4 if v in (2, 4) else 1 if v in (3, 1) else 6 if v in (5, 6) else 7)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # For a single-cell marker, draw a 4x4 pattern.
    # color 2 -> 4 (border)
    # color 3 -> 1 (diamond)
    # color 5 -> 6 (two diagonal 2x2 blocks)
    # color 8 -> 7 (corners + center 2x2)
    marker_pattern = {
        2: (4, 4),
        3: (1, 1),
        5: (6, 6),
        8: (7, 7),
    }

    out = [[0] * w for _ in range(h)]

    def draw(r0, c0, color, kind):
        """
        kind:
          4: border
          1: diamond
          6: two diagonal 2x2 blocks
          7: corners + center 2x2
        """
        for dr in range(4):
            r = r0 + dr
            if r < 0 or r >= h:
                continue
            for dc in range(4):
                c = c0 + dc
                if c < 0 or c >= w:
                    continue

                if kind == 4:
                    if dr == 0 or dr == 3 or dc == 0 or dc == 3:
                        out[r][c] = color
                elif kind == 1:
                    if ((dr == 0 or dr == 3) and 1 <= dc <= 2) or \
                       ((dc == 0 or dc == 3) and 1 <= dr <= 2):
                        out[r][c] = color
                elif kind == 6:
                    if (dr <= 1 and dc <= 1) or (dr >= 2 and dc >= 2):
                        out[r][c] = color
                elif kind == 7:
                    if ((dr == 0 or dr == 3) and (dc == 0 or dc == 3)) or \
                       (1 <= dr <= 2 and 1 <= dc <= 2):
                        out[r][c] = color

    # Markers are single non-zero cells that are not already part of a larger
    # pre-drawn 4x4 pattern in the input.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in marker_pattern:
                continue

            # A marker is valid only if the 4x4 area starting at (r, c)
            # fits in the grid and contains no other non-zero cell.
            if r + 3 >= h or c + 3 >= w:
                continue

            occupied = False
            for dr in range(4):
                for dc in range(4):
                    if not (dr == 0 and dc == 0) and grid[r + dr][c + dc] != 0:
                        occupied = True
                        break
                if occupied:
                    break
            if occupied:
                continue

            color, kind = marker_pattern[v]
            draw(r, c, color, kind)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0

    out = [row[:] for row in grid]

    def in_bounds(r, c):
        return 0 <= r < H and 0 <= c < W

    # Detect 3x3 "blocks": a center with four orthogonal neighbors of the same
    # non-zero color.  Corners are ignored because they may be 0 or the border color.
    blocks = []
    seen = set()
    for r in range(1, H - 1):
        for c in range(1, W - 1):
            ctr = grid[r][c]
            b = grid[r - 1][c]
            if b == 0 or b == ctr:
                continue
            if (
                grid[r + 1][c] == b and
                grid[r][c - 1] == b and
                grid[r][c + 1] == b
            ):
                key = (r, c)
                if key not in seen:
                    seen.add(key)
                    blocks.append((r, c, b, ctr))

    if not blocks:
        return out

    # Blocks must actually have enough border pixels in this puzzle format.
    # Accept full or plus-shaped 3x3 blocks.
    def border_count(r, c, b):
        cnt = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                rr, cc = r + dr, c + dc
                if in_bounds(rr, cc) and grid[rr][cc] == b:
                    cnt += 1
        return cnt

    blocks = [bl for bl in blocks if border_count(bl[0], bl[1], bl[2]) >= 4]
    if not blocks:
        return out

    def has_source(b, ctr):
        return any(sb == ctr for (_r, _c, sb, _sc) in blocks)

    candidates = [(r, c, b, ctr) for (r, c, b, ctr) in blocks if has_source(b, ctr)]
    if not candidates:
        # No meaningful relation found; leave non-5 cells cleared only if obvious?
        return out

    # Find one consistent stable set:
    # kept blocks have a source and do not point to another kept block.
    # Build directed edges source -> target where source.border == target.center.
    n = len(blocks)
    source_idx = [-1] * n
    for i, (_r, _c, b, ctr) in enumerate(blocks):
        for j, (sr, sc, sb, sctr) in enumerate(blocks):
            if sb == ctr:
                source_idx[i] = j
                break

    # Seed with blocks whose border color is not used as a center by any candidate.
    centers = {ctr for (_r, _c, _b, ctr) in candidates}
    kept_mask = [False] * n

    changed = True
    # Iteratively remove candidates that point to a kept block.
    # Start from candidates whose border is not the center of any candidate.
    for i, (_r, _c, b, ctr) in enumerate(blocks):
        if has_source(b, ctr) and b not in centers:
            kept_mask[i] = True

    # Stabilize: if a kept block points to another kept block, remove the earlier one
    # by propagating backwards from sinks.
    while changed:
        changed = False
        for i, (r, c, b, ctr) in enumerate(blocks):
            if not has_source(b, ctr):
                if kept_mask[i]:
                    kept_mask[i] = False
                    changed = True
                continue
            s = source_idx[i]
            if s != -1 and kept_mask[s]:
                # i points to a kept source, so i cannot be kept
                if kept_mask[i]:
                    kept_mask[i] = False
                    changed = True

    # If too few kept due to ambiguity, try direct sink propagation along chains.
    if not any(kept_mask):
        # Choose blocks with no outgoing edge to any candidate as kept if they have source.
        for i, (r, c, b, ctr) in enumerate(blocks):
            if not has_source(b, ctr):
                continue
            out_ok = True
            for j, (sr, sc, sb, sctr) in enumerate(blocks):
                if b == sctr:
                    out_ok = False
                    break
            if out_ok:
                kept_mask[i] = True

    # If still none, keep the single sink with source if possible.
    if not any(kept_mask):
        for i, (r, c, b, ctr) in enumerate(blocks):
            if has_source(b, ctr):
                kept_mask[i] = True
                break

    # Erase all non-kept blocks.
    for i, (r, c, b, ctr) in enumerate(blocks):
        if kept_mask[i]:
            continue
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if in_bounds(rr, cc) and grid[rr][cc] != 5:
                    out[rr][cc] = 0

    # For kept blocks, replace the center by the center of its source block.
    for i, (r, c, b, ctr) in enumerate(blocks):
        if not kept_mask[i]:
            continue
        s = source_idx[i]
        if s != -1:
            out[r][c] = blocks[s][3]
        # else leave as-is

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0]) if H else 0
    out = [row[:] for row in grid]

    # Detect 3x3 "boxes": center with four orthogonal neighbours of the same
    # non-background colour.  Colour 5 is used as the connecting/background
    # pattern in the examples and is never part of a box.
    nodes = []
    for r in range(1, H - 1):
        for c in range(1, W - 1):
            ctr = grid[r][c]
            b = grid[r - 1][c]
            if b == 0 or b == 5 or ctr == 0 or ctr == 5 or ctr == b:
                continue
            if (
                grid[r + 1][c] == b and
                grid[r][c - 1] == b and
                grid[r][c + 1] == b
            ):
                nodes.append((r, c, b, ctr))

    if not nodes:
        return out

    n = len(nodes)
    border_colors = {node[2] for node in nodes}
    center_colors = {node[3] for node in nodes}

    # Directed edge i -> j when the center colour of i equals the border colour of j.
    succ = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for i, (r, c, b, ctr) in enumerate(nodes):
        for j, (r2, c2, b2, ctr2) in enumerate(nodes):
            if i != j and ctr == b2:
                succ[i].append(j)
                pred[j].append(i)

    # A box is a source if its border colour is not used as a centre anywhere.
    # Track which parities of path-length from a source can reach each node.
    reach = [set() for _ in range(n)]
    queue = []
    for i, (r, c, b, ctr) in enumerate(nodes):
        if b not in center_colors:
            reach[i].add(0)
            queue.append((i, 0))

    while queue:
        i, p = queue.pop(0)
        for j in succ[i]:
            np = p ^ 1
            if np not in reach[j]:
                reach[j].add(np)
                queue.append((j, np))

    kept = [False] * n
    new_centers = [nodes[i][3] for i in range(n)]

    for i, (r, c, b, ctr) in enumerate(nodes):
        # Keep a box only if:
        # - it has a successor (its centre refers to another box);
        # - it is reachable from a source;
        # - every source path to it has even length (no parity conflict).
        if succ[i] and 0 in reach[i] and 1 not in reach[i]:
            kept[i] = True
            # Replace its centre by the centre of its target box.
            targets = succ[i]
            # Deterministic choice if multiple targets exist.
            target = min(targets, key=lambda j: (nodes[j][0], nodes[j][1], nodes[j][3]))
            new_centers[i] = nodes[target][3]

    # Erase all boxes that are not kept.
    for i, (r, c, b, ctr) in enumerate(nodes):
        if kept[i]:
            continue
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < H and 0 <= cc < W:
                    val = out[rr][cc]
                    # Erase only the box's own border/centre pixels, preserving 5s.
                    if val == b or val == ctr:
                        out[rr][cc] = 0

    # Update centres of kept boxes.
    for i, (r, c, b, ctr) in enumerate(nodes):
        if kept[i]:
            out[r][c] = new_centers[i]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Identify the background colour as the most common border colour.
