        for c in range(w):
            v = grid[r][c]
            if v != bg and v != 2:
                objects.append((r, c, v))

    def dist2(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    def choose_mirror(p):
        pr, pc = p
        # Prefer a 2 in the same row, then in the same column.
        row_candidates = [q for q in twos if q[0] == pr]
        if row_candidates:
            best_d = min((abs(pc - q[1]), q[1], q[0]) for q in row_candidates)
            for q in row_candidates:
                if (abs(pc - q[1]), q[1], q[0]) == best_d:
                    return q
        col_candidates = [q for q in twos if q[1] == pc]
        if col_candidates:
            best_d = min((abs(pr - q[0]), q[0], q[1]) for q in col_candidates)
            for q in col_candidates:
                if (abs(pr - q[0]), q[0], q[1]) == best_d:
                    return q

        # Otherwise use the nearest 2 pixel, with a deterministic tie-break.
        best_key = None
        best_q = None
        for q in twos:
            key = (dist2(p, q), q[1], q[0])
            if best_key is None or key < best_key:
                best_key = key
                best_q = q
        return best_q

    for r, c, v in objects:
        mr, mc = choose_mirror((r, c))
        nr, nc = 2 * mr - r, 2 * mc - c
        if 0 <= nr < h and 0 <= nc < w:
            out[nr][nc] = v

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    marker = grid[0][0]

    # Remove every occurrence of the marker color.
    # The top-left marker itself is kept.
    out = [[0] * w for _ in range(h)]
    out[0][0] = marker

    for r in range(h):
        for c in range(w):
            if (r, c) == (0, 0):
                continue
            if grid[r][c] != 0 and grid[r][c] != marker:
                out[r][c] = grid[r][c]

    # Gravity:
    # Each column is compressed downward, preserving the relative order
    # of non-background cells.
    for c in range(w):
        vals = [out[r][c] for r in range(h) if out[r][c] != 0]
        for r in range(h):
            out[r][c] = 0

        start = h - len(vals)
        for i, v in enumerate(vals):
            out[start + i][c] = v

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background: most common colour on the border (ties: smaller colour)
    border_vals = [g[0, :], g[-1, :], g[:, 0], g[:, -1]]
    flat_border = np.concatenate([x.ravel() for x in border_vals])
    vals, counts = np.unique(flat_border, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    # Find components of non-background cells using 4-connectivity
    visited = np.zeros((h, w), dtype=bool)
    components = []
    for i in range(h):
        for j in range(w):
            if g[i, j] != bg and not visited[i, j]:
                stack = [(i, j)]
                visited[i, j] = True
                cells = []
                while stack:
                    r, c = stack.pop()
                    cells.append((r, c, int(g[r, c])))
                    for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                        if 0 <= nr < h and 0 <= nc < w:
                            if not visited[nr, nc] and g[nr, nc] != bg:
                                visited[nr, nc] = True
                                stack.append((nr, nc))
                components.append(cells)

    # Isolated border anchors: non-background border cells with no non-background 4-neighbours
    anchors_by_color = {}
    for r in range(h):
        for c in range(w):
            if g[r, c] == bg:
                continue
            is_border = (r == 0 or r == h - 1 or c == 0 or c == w - 1)
            if not is_border:
                continue
            isolated = True
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < h and 0 <= nc < w and g[nr, nc] != bg:
                    isolated = False
                    break
            if isolated:
                anchors_by_color.setdefault(int(g[r, c]), []).append((r, c))

    # Choose a marker colour for each component:
    # Prefer a colour that appears exactly once in the component and has at least one anchor.
    # If several, choose the one with smallest movement to a compatible anchor.
    moved_components = []
    static_cells = []

    for cells in components:
        colors = {}
        for r, c, col in cells:
            colors.setdefault(col, []).append((r, c))

        candidates = []
        for col, positions in colors.items():
            if len(positions) != 1:
                continue
            if col not in anchors_by_color:
                continue
            mr, mc = positions[0]
            best = None
            for ar, ac in anchors_by_color[col]:
                # If anchor is on left/right border -> align rows.
                # If anchor is on top/bottom border -> align columns.
                if (ar == 0 or ar == h - 1) and not (ac == 0 or ac == w - 1):
                    dr, dc = ar - mr, 0
                elif (ac == 0 or ac == w - 1) and not (ar == 0 or ar == h - 1):
                    dr, dc = 0, ac - mc
                else:
                    # Corner or ambiguous: use axis with smaller absolute difference.
                    if abs(ar - mr) <= abs(ac - mc):
                        dr, dc = ar - mr, 0
                    else:
                        dr, dc = 0, ac - mc
                # Valid if shifted component stays inside grid
                if all(0 <= r + dr < h and 0 <= c + dc < w for r, c, _ in cells):
                    dist = abs(dr) + abs(dc)
                    if best is None or dist < best[0]:
                        best = (dist, dr, dc)
            if best is not None:
                candidates.append((best[0], col, best[1], best[2]))

        if candidates:
            candidates.sort()
            _, col, dr, dc = candidates[0]
            moved_components.append((cells, dr, dc))
        else:
            static_cells.extend((r, c, col) for r, c, col in cells)

    # Build output
    out = np.full((h, w), bg, dtype=int)

    # Static cells first
    for r, c, col in static_cells:
        out[r, c] = col

    # Moved components; if multiple components collide, later ones overwrite earlier ones.
    # Process in the order they were found; this matches the observed examples.
    for cells, dr, dc in moved_components:
        for r, c, col in cells:
            out[r + dr, c + dc] = col

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    H = len(grid)
    W = len(grid[0])

    # Background is the most frequent colour.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def is_uniform_row(row):
        return all(x == row[0] for x in row)

    # Detect the full-width target frames.
    # A frame is:
    #   top row all b
    #   bottom row all b
    #   middle rows: first/last cell b, and all middle cells one colour i
    frames = []
    used_rows = [False] * H

    for s in range(H):
        if used_rows[s]:
            continue
        row = grid[s]
        if not is_uniform_row(row):
            continue
        b = row[0]
        if b == bg:
            continue

        found = None
        # height at least 3
        for e in range(s + 2, H):
            if not is_uniform_row(grid[e]):
                continue
            if grid[e][0] != b:
                continue

            ok = True
            interior_colours = set()
            for r in range(s + 1, e):
                if grid[r][0] != b or grid[r][W - 1] != b:
                    ok = False
                    break
                mid = set(grid[r][1:-1])
                if not mid or b in mid:
                    ok = False
                    break
                interior_colours.update(mid)

            if ok and len(interior_colours) == 1:
                i = next(iter(interior_colours))
                if i != b:
                    found = (s, e, 0, W - 1, b, i)
                    break

        if found:
            frames.append(found)
            for r in range(found[0], found[1] + 1):
                used_rows[r] = True

    # Mask all target frame cells; they are not source cells.
    frame_mask = [[False] * W for _ in range(H)]
    interior_to_frames = {}
    for top, bottom, left, right, border, interior in frames:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                frame_mask[r][c] = True
        interior_to_frames.setdefault(interior, []).append(
            (top, bottom, left, right, border, interior)
        )

    # Start with background, then restore target frames exactly.
    out = [[bg] * W for _ in range(H)]
    for top, bottom, left, right, border, interior in frames:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = grid[r][c]

    # Connected components of each source colour outside frames.
    def components_of(colour):
        visited = [[False] * W for _ in range(H)]
        comps = []
        for r in range(H):
            for c in range(W):
                if (
                    not frame_mask[r][c]
                    and not visited[r][c]
                    and grid[r][c] == colour
                ):
                    stack = [(r, c)]
                    visited[r][c] = True
                    cells = []
                    while stack:
                        x, y = stack.pop()
                        cells.append((x, y))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if (
                                0 <= nx < H
                                and 0 <= ny < W
                                and not frame_mask[nx][ny]
                                and not visited[nx][ny]
                                and grid[nx][ny] == colour
                            ):
                                visited[nx][ny] = True
                                stack.append((nx, ny))
                    comps.append(cells)
        return comps

    # Move every source component into its matching target frame.
    for colour, frame_list in interior_to_frames.items():
        if colour == bg:
            continue
        for cells in components_of(colour):
            comp_bottom = max(r for r, _ in cells)

            # In all provided cases the interior colour matches exactly one frame.
            # Fallback: choose the closest frame below the component.
            if len(frame_list) == 1:
                frame = frame_list[0]
            else:
                below = [f for f in frame_list if f[1] >= comp_bottom]
                if below:
                    frame = min(below, key=lambda f: f[1])
                else:
                    frame = min(frame_list, key=lambda f: abs(f[1] - comp_bottom))

            top, bottom, left, right, border, _ = frame
            shift = bottom - comp_bottom

            for r, c in cells:
                nr = r + shift
                if top <= nr <= bottom and left <= c <= right:
                    out[nr][c] = border

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    H = len(grid)
    W = len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def is_uniform(row):
        return all(x == row[0] for x in row)

    # Detect full-width target frames: (top, bottom, border, interior)
    frames = []
    used = [False] * H
    for s in range(H):
        if used[s] or not is_uniform(grid[s]):
            continue
        B = grid[s][0]
        if B == bg:
            continue
        for e in range(s + 2, H):
            if not is_uniform(grid[e]) or grid[e][0] != B:
                continue
            ok, I = True, None
            for r in range(s + 1, e):
                if grid[r][0] != B or grid[r][W - 1] != B:
                    ok = False
                    break
                mid = set(grid[r][1:-1])
                if len(mid) != 1 or next(iter(mid)) in (B, bg):
                    ok = False
                    break
                c = next(iter(mid))
                if I is None:
                    I = c
                elif c != I:
                    ok = False
                    break
            if ok and I is not None:
                frames.append((s, e, B, I))
                for r in range(s, e + 1):
                    used[r] = True
                break

    # Output: background + frames
    out = [[bg] * W for _ in range(H)]
    frame_mask = [[False] * W for _ in range(H)]
    for top, bot, B, I in frames:
        for r in range(top, bot + 1):
            for c in range(W):
                out[r][c] = grid[r][c]
                frame_mask[r][c] = True

    # 4-connected components of a given colour, excluding frame cells
    def components(colour):
        vis = [[False] * W for _ in range(H)]
        result = []
        for r in range(H):
            for c in range(W):
                if frame_mask[r][c] or vis[r][c] or grid[r][c] != colour:
                    continue
                stack, cells = [(r, c)], []
                vis[r][c] = True
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y))
                    for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < H and 0 <= ny < W
                                and not frame_mask[nx][ny] and not vis[nx][ny]
                                and grid[nx][ny] == colour):
                            vis[nx][ny] = True
                            stack.append((nx, ny))
        result.append(cells)
        return result

    # Place each source component bottom-aligned into its matching frame
    for top, bot, B, I in frames:
        for cells in components(I):
            shift = bot - max(r for r, _ in cells)
            for r, c in cells:
                nr = r + shift
                if top <= nr <= bot and 0 <= c < W:
                    out[nr][c] = B

    return out

