from typing import List

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    boxes = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            center = int(g[r, c])
            border = int(g[r - 1, c])
            if border == 0:
                continue
            if int(g[r + 1, c]) == border and int(g[r, c - 1]) == border and int(g[r, c + 1]) == border and center != border:
                boxes.append((r, c, center, border))

    out = g.copy()

    def top_left(box):
        return (box[0] - 1, box[1] - 1)

    # A color value maps to at most one box in generated cases.
    border_to_box = {}
    for box in boxes:
        border_to_box[box[3]] = box

    indeg = {box[1]: 0 for box in boxes}
    for box in boxes:
        nxt = border_to_box.get(box[2])
        if nxt is not None and nxt[1] != box[1]:
            indeg[nxt[1]] += 1

    # Follow valid paths from path heads (indegree == 0).
    assigned = set()
    for box in boxes:
        if indeg[box[1]] != 0:
            continue
        cur = box
        pos = 0
        while cur is not None and cur[1] not in assigned:
            assigned.add(cur[1])
            if pos % 2 == 0:
                tr, tc = top_left(cur)
                nxt = border_to_box.get(cur[2])
                if pos > 0 and nxt is not None and nxt[1] in assigned:
                    # Keep current box, but do not copy from an already processed node.
                    pass
                elif nxt is not None and nxt[1] not in assigned:
                    # Copy the next box's original center into this kept box.
                    out[cur[0], cur[1]] = nxt[2]
                # If there is no next box, leave center unchanged.
            else:
                tr, tc = top_left(cur)
                out[tr:tr + 3, tc:tc + 3] = 0
            cur = border_to_box.get(cur[2])
            pos += 1

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    arr = np.array(grid, dtype=int)
    h, w = arr.shape
    out = arr.copy()

    # Find all "boxes": a center cell whose four orthogonal neighbours
    # are the same non-zero colour.  (Corners are irrelevant; test cases
    # may have 0 corners.)
    boxes = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            b = int(arr[r - 1, c])
            if b == 0:
                continue
            if (int(arr[r + 1, c]) == b and
                int(arr[r, c - 1]) == b and
                int(arr[r, c + 1]) == b):
                ctr = int(arr[r, c])
                if ctr != b:
                    boxes.append((r, c, ctr, b))

    if not boxes:
        return out.tolist()

    # Each border colour identifies at most one box in these puzzles.
    border_to_box = {b[3]: b for b in boxes}

    # Directed chain links:
    # box X -> box Y when center(X) == border(Y).
    succ = {}
    pred = {}
    for b in boxes:
        nxt = border_to_box.get(b[2])
        if nxt is not None and (nxt[0], nxt[1]) != (b[0], b[1]):
            succ[(b[0], b[1])] = nxt
            pred[(nxt[0], nxt[1])] = b

    # Find all chain starts: boxes with no predecessor.
    starts = [b for b in boxes if (b[0], b[1]) not in pred]

    for start in starts:
        # Follow the directed chain.
        chain = []
        cur = start
        while cur is not None:
            chain.append(cur)
            cur = succ.get((cur[0], cur[1]))

        # Rule:
        # - delete boxes at odd positions in the chain (1st, 3rd, ...)
        # - also delete the terminal box
        # - every remaining box copies the centre of the next box
        delete = set()
        if chain:
            delete.add((chain[-1][0], chain[-1][1]))
        for i, b in enumerate(chain):
            if i % 2 == 1:
                delete.add((b[0], b[1]))

        for i, b in enumerate(chain):
            r, c, ctr, bord = b
            if i % 2 == 0 and i != len(chain) - 1:
                # Kept: set center to the next box's original center.
                nxt = succ[(r, c)]
                out[r, c] = nxt[2]
            else:
                # Deleted: clear the whole 3x3 area of this box.
                out[r - 1:r + 2, c - 1:c + 2] = 0

    return out.tolist()

import numpy as np
from collections import Counter, deque

def _as_list(grid):
    return [list(map(int, row)) for row in grid]

def _background(g):
    arr = np.array(g)
    border = np.concatenate((
        arr[0, :].ravel(),
        arr[-1, :].ravel(),
        arr[:, 0].ravel(),
        arr[:, -1].ravel()
    ))
    vals, cnts = np.unique(border, return_counts=True)
    if len(vals) == 1 or cnts.max() >= border.size // 2:
        return int(vals[int(np.argmax(cnts))])
    vals, cnts = np.unique(arr.ravel(), return_counts=True)
    return int(vals[int(np.argmax(cnts))])

def _components8(g):
    h, w = len(g), len(g[0])
    bg = _background(g)
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if seen[r][c] or g[r][c] == bg:
                continue
            color = g[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            pixels = []
            while q:
                x, y = q.popleft()
                pixels.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        if dx == 0 and dy == 0:
                            continue
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and not seen[nx][ny] and g[nx][ny] != bg:
                            seen[nx][ny] = True
                            q.append((nx, ny))
            comps.append((pixels, set(g[p[0]][p[1]] for p in pixels)))
    return comps

def _line_orientations(pts):
    pts = list(pts)
    rows = {p[0] for p in pts}
    cols = {p[1] for p in pts}
    d1 = {p[0] - p[1] for p in pts}
    d2 = {p[0] + p[1] for p in pts}
    if len(rows) == 1:
        return ['H']
    if len(cols) == 1:
        return ['V']
    if len(d1) == 1:
        return ['D1']
    if len(d2) == 1:
        return ['D2']
    if len(pts) == 1:
        return ['H', 'V', 'D1', 'D2']
    return []

def _side(pts, orient, const):
    s = set()
    for r, c in pts:
        if orient == 'H':
            if r < const: s.add('above')
            elif r > const: s.add('below')
        elif orient == 'V':
            if c < const: s.add('left')
            elif c > const: s.add('right')
        elif orient == 'D1':
            if r - c < const: s.add('d1a')
            elif r - c > const: s.add('d1b')
        elif orient == 'D2':
            if r + c < const: s.add('d2a')
            elif r + c > const: s.add('d2b')
    return s

def _score_axis(pts, orient, const):
    side = _side(pts, orient, const)
    if len(side) != 1:
        return None
    dist = []
    for r, c in pts:
        if orient == 'H':
            d = abs(r - const)
        elif orient == 'V':
            d = abs(c - const)
        elif orient == 'D1':
            d = abs(r - c - const)
        elif orient == 'D2':
            d = abs(r + c - const)
        if d == 0:
            return None
        dist.append(d)
    if not dist:
        return None
    mn, mx = min(dist), max(dist)
    # Prefer a clean one-sided pattern, compact in the normal direction.
    return (0, mn, mx, mx - mn)

def _reflect(pt, orient, const):
    r, c = pt
    if orient == 'H':
        return (2 * const - r, c)
    if orient == 'V':
        return (r, 2 * const - c)
    if orient == 'D1':
        # reflect across r - c = const
        return (c + const, r - const)
    if orient == 'D2':
        # reflect across r + c = const
        return (const - c, const - r)
    return pt

