        if len(colors) < 2:
            continue

        by_color = {c: [] for c in colors}
        for r, c in pixels:
            by_color[g[r][c]].append((r, c))

        candidates = []
        for c, pts in by_color.items():
            orients = _line_orientations(pts)
            if not orients:
                continue
            for o in orients:
                if o == 'H':
                    const = pts[0][0]
                elif o == 'V':
                    const = pts[0][1]
                elif o == 'D1':
                    const = pts[0][0] - pts[0][1]
                else:
                    const = pts[0][0] + pts[0][1]

                other = [p for p in pixels if g[p[0]][p[1]] != c]
                sc = _score_axis(other, o, const)
                if sc is not None:
                    # lower count axis preferred; then better score
                    candidates.append((len(pts), sc, c, o, const, other))

        if not candidates:
            continue

        candidates.sort(key=lambda x: (x[0], x[1]))
        _, _, axis_color, orient, const, other = candidates[0]

        for p in other:
            np_ = _reflect(p, orient, const)
            if 0 <= np_[0] < h and 0 <= np_[1] < w and out[np_[0]][np_[1]] == bg:
                out[np_[0]][np_[1]] = g[p[0]][p[1]]

    return out

