        return True

    # Detect full-width horizontal bands.
    # A band has a constant border colour in the first/last columns and
    # a constant fill colour everywhere inside it.
    bands = []
    band_mask = [[False] * w for _ in range(h)]
    r = 0
    while r < h:
        if w >= 2 and grid[r][0] == grid[r][w - 1] and grid[r][0] != bg:
            border = grid[r][0]

            if w > 2:
                fill = grid[r][1]
                if fill != border and interior_uniform(r, fill):
                    r2 = r
                    while (
                        r2 + 1 < h
                        and grid[r2 + 1][0] == border
                        and grid[r2 + 1][w - 1] == border
                        and interior_uniform(r2 + 1, fill)
                    ):
                        r2 += 1
                    bands.append((r, r2, border, fill))
                    for i in range(r, r2 + 1):
                        for j in range(w):
                            band_mask[i][j] = True
                    r = r2 + 1
                    continue
            else:
                r2 = r
                while r2 + 1 < h and grid[r2 + 1][0] == border and grid[r2 + 1][w - 1] == border:
                    r2 += 1
                bands.append((r, r2, border, None))
                for i in range(r, r2 + 1):
                    for j in range(w):
                        band_mask[i][j] = True
                r = r2 + 1
                continue

        r += 1

    # Source pixels are all non-background pixels outside bands.
    source = [[False] * w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if not band_mask[i][j] and grid[i][j] != bg:
                source[i][j] = True

    # Find connected components by colour (4-connectivity).
    seen = [[False] * w for _ in range(h)]
    components = []

    for i in range(h):
        for j in range(w):
            if not source[i][j] or seen[i][j]:
                continue

            colour = grid[i][j]
            q = deque([(i, j)])
            seen[i][j] = True
            cells = []
            min_r = max_r = i
            min_c = max_c = j

            while q:
                y, x = q.popleft()
                cells.append((y, x))
                min_r = min(min_r, y)
                max_r = max(max_r, y)
                min_c = min(min_c, x)
                max_c = max(max_c, x)

                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (
                        0 <= ny < h
                        and 0 <= nx < w
                        and not seen[ny][nx]
                        and source[ny][nx]
                        and grid[ny][nx] == colour
                    ):
                        seen[ny][nx] = True
                        q.append((ny, nx))

            components.append((colour, cells, max_r))

    # For each source colour, keep possible target bands.
    fill_to_bands = {}
    for b in bands:
        if b[3] is not None:
            fill_to_bands.setdefault(b[3], []).append(b)

    def choose_band(colour, comp_bottom):
        candidates = fill_to_bands.get(colour)
        if not candidates:
            return None

        below = [b for b in candidates if b[0] >= comp_bottom]
        if below:
            return min(below, key=lambda b: b[0])

        above = [b for b in candidates if b[1] <= comp_bottom]
        if above:
            return max(above, key=lambda b: b[1])

        return min(
            candidates,
            key=lambda b: min(abs(b[0] - comp_bottom), abs(b[1] - comp_bottom))
        )

    # Start from input and erase all source pixels.
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if source[i][j]:
                out[i][j] = bg

    # Move each component into its matching band, bottom-aligned.
    for colour, cells, max_r in components:
        band = choose_band(colour, max_r)
        if band is None:
            continue

        top, bottom, border, _ = band

        for y, x in cells:
            ny = bottom - (max_r - y)

            # Safety clamp; normal puzzle inputs should already fit.
            if ny < top:
                ny = top
            elif ny > bottom:
                ny = bottom

            out[ny][x] = border

    return out

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    g = [list(row) for row in grid]

    # Find the lookup table:
    # a 4-connected component of non-zero cells that completely fills its
    # bounding box and contains more than one colour.
    visited = [[False] * W for _ in range(H)]
    table_box = None
    best_area = 0

    for r in range(H):
        for c in range(W):
            if g[r][c] != 0 and not visited[r][c]:
                q = deque([(r, c)])
                visited[r][c] = True
                cells = []
                min_r = max_r = r
                min_c = max_c = c
                colours = set()

                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    colours.add(g[y][x])
                    min_r = min(min_r, y)
                    max_r = max(max_r, y)
                    min_c = min(min_c, x)
                    max_c = max(max_c, x)

                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not visited[ny][nx] and g[ny][nx] != 0:
                                visited[ny][nx] = True
                                q.append((ny, nx))

                area = len(cells)
                bbox_area = (max_r - min_r + 1) * (max_c - min_c + 1)

                if area == bbox_area and len(colours) >= 2 and bbox_area >= 4:
                    if area > best_area:
                        best_area = area
                        table_box = (min_r, max_r, min_c, max_c)

    if table_box is None:
        return g

    r0, r1, c0, c1 = table_box
    h = r1 - r0 + 1
    w = c1 - c0 + 1

    # Determine from which side of the table the key colours come.
    # Prefer a side that is flush with the grid border, choosing the longest
    # flush side.  If none is flush, fall back to aspect ratio.
    sides = []
    if r0 == 0:
        sides.append((w, 'top'))
    if r1 == H - 1:
        sides.append((w, 'bottom'))
    if c0 == 0:
        sides.append((h, 'left'))
    if c1 == W - 1:
        sides.append((h, 'right'))

    if sides:
        key_side = max(sides, key=lambda p: (p[0], p[1] == 'left', p[1] == 'top'))[1]
    else:
        if h > w:
            key_side = 'left'
        elif w > h:
            key_side = 'top'
        else:
            key_side = 'left'

    mapping = {}

    if key_side == 'left':
        # Left column keys -> right column values.
        for i in range(h):
            k = g[r0 + i][c0]
            v = g[r0 + i][c1]
            if k in mapping and mapping[k] != v:
                pass
            else:
                mapping[k] = v
    elif key_side == 'right':
        # Right column keys -> left column values.
        for i in range(h):
            k = g[r0 + i][c1]
            v = g[r0 + i][c0]
            if k in mapping and mapping[k] != v:
                pass
            else:
                mapping[k] = v
    elif key_side == 'top':
        # Top row keys -> bottom row values.
        for i in range(w):
            k = g[r0][c0 + i]
            v = g[r1][c0 + i]
            if k in mapping and mapping[k] != v:
                pass
            else:
                mapping[k] = v
    elif key_side == 'bottom':
        # Bottom row keys -> top row values.
        for i in range(w):
            k = g[r1][c0 + i]
            v = g[r0][c0 + i]
            if k in mapping and mapping[k] != v:
                pass
            else:
                mapping[k] = v

    # Remove the table itself from consideration so its cells are not treated
    # as walls/holes.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            g[r][c] = 0

    # Find all zero components that are not connected to the outside.
    seen = [[False] * W for _ in range(H)]
    holes = []

    for r in range(H):
        for c in range(W):
            if g[r][c] == 0 and not seen[r][c]:
                q = deque([(r, c)])
                seen[r][c] = True
                comp = []
                touches_boundary = (r == 0 or r == H - 1 or c == 0 or c == W - 1)

                while q:
                    y, x = q.popleft()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny][nx] == 0 and not seen[ny][nx]:
                                seen[ny][nx] = True
                                q.append((ny, nx))
                                if ny == 0 or ny == H - 1 or nx == 0 or nx == W - 1:
                                    touches_boundary = True

                if not touches_boundary:
                    holes.append(comp)

    # Fill each enclosed zero component using the colour of its surrounding
    # mapped border colour, if there is a unique one.
    for comp in holes:
        border = {}
        for y, x in comp:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W:
                    col = g[ny][nx]
                    if col != 0:
                        border[col] = border.get(col, 0) + 1

        candidates = {c: n for c, n in border.items() if c in mapping}

        if len(candidates) == 1:
            fill_colour = mapping[next(iter(candidates))]
            for y, x in comp:
                g[y][x] = fill_colour
        elif len(candidates) > 1:
            # Safety fallback: choose the most adjacent mapped colour.
            fill_colour = mapping[max(candidates, key=lambda c: candidates[c])]
            for y, x in comp:
                g[y][x] = fill_colour

    return g

from collections import deque, defaultdict


def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    g = [list(row) for row in grid]

    # ------------------------------------------------------------
    # 1. Find solid rectangular "lookup tables".
    #    A table is a 4-connected nonzero component that exactly fills
    #    its bounding box, contains at least two colours, and has
    #    height and width at least 2.
    # ------------------------------------------------------------
    visited = [[False] * W for _ in range(H)]
    candidates = []

    for r in range(H):
        for c in range(W):
            if g[r][c] != 0 and not visited[r][c]:
                q = deque([(r, c)])
                visited[r][c] = True

                cells = []
                min_r = max_r = r
                min_c = max_c = c
                colours = set()

                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    colours.add(g[y][x])

                    min_r = min(min_r, y)
                    max_r = max(max_r, y)
                    min_c = min(min_c, x)
                    max_c = max(max_c, x)

                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if not visited[ny][nx] and g[ny][nx] != 0:
                                visited[ny][nx] = True
                                q.append((ny, nx))

                h = max_r - min_r + 1
                w = max_c - min_c + 1
                area = len(cells)

                if area == h * w and h >= 2 and w >= 2 and len(colours) > 1:
                    flush = (
                        min_r == 0
                        or max_r == H - 1
                        or min_c == 0
                        or max_c == W - 1
                    )
                    candidates.append({
                        "box": (min_r, max_r, min_c, max_c),
                        "h": h,
                        "w": w,
                        "area": area,
                        "long_side": max(h, w),
                        "flush": flush,
                    })

    if not candidates:
        return g

    # ------------------------------------------------------------
    # 2. Find enclosed zero components ("holes").
    # ------------------------------------------------------------
    holes = []
    seen = [[False] * W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if g[r][c] == 0 and not seen[r][c]:
                q = deque([(r, c)])
                seen[r][c] = True
                comp = []
                touches_boundary = False

                while q:
                    y, x = q.popleft()
                    comp.append((y, x))

                    if y == 0 or y == H - 1 or x == 0 or x == W - 1:
                        touches_boundary = True

                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if g[ny][nx] == 0 and not seen[ny][nx]:
                                seen[ny][nx] = True
                                q.append((ny, nx))

                if not touches_boundary:
                    counts = defaultdict(int)
                    for y, x in comp:
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if g[ny][nx] != 0:
                                    counts[g[ny][nx]] += 1

                    cy = sum(y for y, _ in comp) / len(comp)
                    cx = sum(x for _, x in comp) / len(comp)

                    holes.append({
                        "cells": comp,
                        "counts": dict(counts),
                        "size": len(comp),
                        "cy": cy,
                        "cx": cx,
                    })

    # ------------------------------------------------------------
    # Helpers for choosing the table orientation and mapping.
    # ------------------------------------------------------------
    def build_mapping(box, side):
        r0, r1, c0, c1 = box
        pairs = defaultdict(list)

        if side == "top":
            for c in range(c0, c1 + 1):
                pairs[g[r0][c]].append(g[r1][c])
        elif side == "bottom":
            for c in range(c0, c1 + 1):
                pairs[g[r1][c]].append(g[r0][c])
        elif side == "left":
            for r in range(r0, r1 + 1):
                pairs[g[r][c0]].append(g[r][c1])
        elif side == "right":
            for r in range(r0, r1 + 1):
                pairs[g[r][c1]].append(g[r][c0])

        mapping = {}
        for key, values in pairs.items():
            value_counts = defaultdict(int)
            for v in values:
                value_counts[v] += 1
            mapping[key] = max(value_counts.items(), key=lambda it: (it[1], it[0]))[0]

        return mapping

    def hole_fill_color(counts, mapping):
        best_count = 0
        best_values = set()

        for colour, count in counts.items():
            if colour in mapping:
                val = mapping[colour]
                if count > best_count:
                    best_count = count
                    best_values = {val}
                elif count == best_count:
                    best_values.add(val)

        if best_count == 0 or len(best_values) != 1:
            return None
        return next(iter(best_values))

    def side_is_flush(box, side):
        r0, r1, c0, c1 = box
        if side == "top":
            return r0 == 0
        if side == "bottom":
            return r1 == H - 1
        if side == "left":
            return c0 == 0
        if side == "right":
            return c1 == W - 1
        return False

    def side_length(box, side):
        r0, r1, c0, c1 = box
        h = r1 - r0 + 1
        w = c1 - c0 + 1
        if side in ("top", "bottom"):
            return w
        return h

    def spatial_score(box, side):
        r0, r1, c0, c1 = box
        ty = (r0 + r1 + 1) / 2.0
        tx = (c0 + c1 + 1) / 2.0

        score = 0.0
        for hole in holes:
            dy = hole["cy"] - ty
            dx = hole["cx"] - tx

            if side == "top":
                dot = dy
            elif side == "bottom":
                dot = -dy
            elif side == "left":
                dot = dx
            elif side == "right":
                dot = -dx
            else:
                dot = 0.0

            if dot > 0:
                score += dot * hole["size"]

        return score

    def evaluate_candidate(cand):
        box = cand["box"]
        best = None

        for side in ("top", "bottom", "left", "right"):
            mapping = build_mapping(box, side)

            score = 0
            for hole in holes:
                if hole_fill_color(hole["counts"], mapping) is not None:
                    score += 1

            flush = 1 if side_is_flush(box, side) else 0
            length = side_length(box, side)
            spatial = spatial_score(box, side)
            priority = {"top": 4, "left": 3, "bottom": 2, "right": 1}[side]

            side_key = (score, flush, length, spatial, priority)

            if best is None or side_key > best[0]:
                best = (side_key, mapping, side)

        return (cand, best[0], best[1], best[2])

    evaluated = [evaluate_candidate(cand) for cand in candidates]

    def candidate_key(ev):
        cand, side_key, _, _ = ev
        score, flush, length, spatial, priority = side_key
        return (
            score,
            cand["flush"],
            cand["long_side"],
            cand["area"],
            flush,
            length,
            spatial,
            priority,
        )

    best_any = max(evaluated, key=candidate_key)
    flush_evals = [ev for ev in evaluated if ev[0]["flush"]]

    if flush_evals:
        best_flush = max(flush_evals, key=candidate_key)
        if best_flush[1][0] > 0 or best_any[1][0] == 0:
            chosen = best_flush
        else:
            chosen = best_any
    else:
        chosen = best_any

    mapping = chosen[2]

    # ------------------------------------------------------------
    # 3. Fill enclosed holes whose border colour is mapped.
    # ------------------------------------------------------------
    for hole in holes:
        fill = hole_fill_color(hole["counts"], mapping)
        if fill is not None:
            for y, x in hole["cells"]:
                g[y][x] = fill

    return g

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    target = grid[0][0]

    # Start with the target colour removed everywhere, except keep the top-left marker.
    g = [[0] * W for _ in range(H)]
    g[0][0] = target

    # Collect all non-target connected components (4-connected, same colour).
    visited = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if r == 0 and c == 0:
                continue
            col = grid[r][c]
            if col == 0 or col == target or visited[r][c]:
                continue

            stack = [(r, c)]
            visited[r][c] = True
            cells = []
            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not visited[nr][nc] and grid[nr][nc] == col:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

            components.append((col, cells))

    # Place all remaining components.
    for col, cells in components:
        for r, c in cells:
            g[r][c] = col

    # Iteratively apply gravity:
    # each monochromatic 4-connected component may move down as a whole
    # when no cell of it would collide with another occupied cell.
    changed = True
    while changed:
        changed = False
        occupied = [[False] * W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                if g[r][c] != 0:
                    occupied[r][c] = True

        for col, _ in components:
            # Gather current cells of this component.
            comp_cells = set()
            for r in range(H):
                for c in range(W):
                    if g[r][c] == col:
                        comp_cells.add((r, c))
            if not comp_cells:
                continue

            # Check if the whole component can move down by one.
            can_move = True
            for (r, c) in comp_cells:
                nr = r + 1
                if nr >= H:
                    can_move = False
                    break
                # Destination must not be occupied outside this component.
                if occupied[nr][c] and (nr, c) not in comp_cells:
                    can_move = False
                    break

            if can_move:
                # Remove old cells.
                for (r, c) in comp_cells:
                    occupied[r][c] = False
                    g[r][c] = 0
                # Move down.
                for (r, c) in comp_cells:
                    nr = r + 1
                    g[nr][c] = col
                    occupied[nr][c] = True
                changed = True

    # Return as a plain list of ints.
    return [[int(g[r][c]) for c in range(W)] for r in range(H)]

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    marker = grid[0][0]

    # Remove every cell of the marker colour except the top-left marker.
    g = [row[:] for row in grid]
    for r in range(H):
        for c in range(W):
            if g[r][c] == marker and not (r == 0 and c == 0):
                g[r][c] = 0

    # If the marker colour was not present anywhere else, nothing changes.
    if all(g[r][c] != marker for r in range(H) for c in range(W)):
        return g

    def neighbors(r, c):
        if r + 1 < H:
            yield r + 1, c
        if r - 1 >= 0:
            yield r - 1, c
        if c + 1 < W:
            yield r, c + 1
        if c - 1 >= 0:
            yield r, c - 1

    # Connected components of non-zero cells, where connectivity ignores colour.
    seen = [[False] * W for _ in range(H)]
    comps = []
    for r in range(H):
        for c in range(W):
            if g[r][c] == 0 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for nr, nc in neighbors(cr, cc):
                    if not seen[nr][nc] and g[nr][nc] != 0:
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            comps.append(cells)

    # A component may fall down by d if every destination cell is either
    # still occupied by the same component or empty in the original grid.
    def can_move(cells, d):
        if d <= 0:
            return True
        cell_set = set(cells)
        for (r, c) in cells:
            nr = r + d
            if nr >= H:
                return False
            if (nr, c) not in cell_set and g[nr][c] != 0:
                return False
        return True

    def max_drop(cells):
        lo, hi = 0, H
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can_move(cells, mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

    # Move larger / lower components first so that upper components can fall
    # into space made available by lower components.
    comps.sort(key=lambda cells: (-len(cells), -max(cells)[0]))

    for cells in comps:
        d = max_drop(cells)
        if d == 0:
            continue

        new_cells = set((r + d, c) for r, c in cells)
        old_cells = set(cells)
        for (r, c) in old_cells - new_cells:
            g[r][c] = 0
        for (r, c) in new_cells:
            g[r][c] = grid[r][c] if grid[r][c] != 0 else marker  # should not happen

    # The marker itself must remain at (0,0).
    g[0][0] = marker
    return [[int(x) for x in row] for row in g]

import numpy as np
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Prefix sum of zeros to quickly test if a rectangle is completely non-zero.
    z = (g == 0).astype(int)
    ps = np.zeros((H + 1, W + 1), dtype=int)
    ps[1:, 1:] = z
    ps[1:, 1:] += ps[:-1, 1:] + ps[1:, :-1] - ps[:-1, :-1]

    def zero_count(r1, r2, c1, c2):
        # inclusive rectangle
        return int(ps[r2 + 1, c2 + 1] - ps[r1, c2 + 1] - ps[r2 + 1, c1] + ps[r1, c1])

    # Find the palette: largest solid (no zeros) rectangle containing at least two colors.
    best = None  # (area, -1/-0 tie, r1, r2, c1, c2)
    for r1 in range(H):
        for r2 in range(r1, H):
            for c1 in range(W):
                # early stop if current possible area cannot beat best
                if best is not None:
                    max_area = (r2 - r1 + 1) * (W - c1)
                    if max_area <= best[0]:
                        continue
                for c2 in range(c1, W):
                    if zero_count(r1, r2, c1, c2) != 0:
                        continue
                    sub = g[r1:r2 + 1, c1:c2 + 1]
                    if len(np.unique(sub)) < 2:
                        continue
                    area = (r2 - r1 + 1) * (c2 - c1 + 1)
                    cand = (area, -1, r1, r2, c1, c2)
                    if best is None or cand > best:
                        best = cand

    if best is None:
        return [list(map(int, row)) for row in g]

    area, _, pr1, pr2, pc1, pc2 = best
    ph = pr2 - pr1 + 1
    pw = pc2 - pc1 + 1

    # Choose the dimension of size 2 as the pairing dimension.
    # If both are 2, use vertical (top-bottom) as in the 2x2 example.
    if ph == 2 or (ph <= pw and ph == 2):
        vertical = True
    elif pw == 2:
        vertical = False
    else:
        # Fallback: pair along the shorter dimension.
        vertical = ph <= pw

    if vertical:
        # pairing between top and bottom rows
        if pr1 == 0:
            src_r, tgt_r = pr1, pr2
        elif pr2 == H - 1:
            src_r, tgt_r = pr2, pr1
        else:
            src_r, tgt_r = pr1, pr2
        mapping = {}
        for c in range(pc1, pc2 + 1):
            s = int(g[src_r, c])
            t = int(g[tgt_r, c])
            if s != 0 and t != 0 and s not in mapping:
                mapping[s] = t
    else:
        # pairing between left and right columns
        if pc1 == 0:
            src_c, tgt_c = pc1, pc2
        elif pc2 == W - 1:
            src_c, tgt_c = pc2, pc1
        else:
            src_c, tgt_c = pc1, pc2
        mapping = {}
        for r in range(pr1, pr2 + 1):
            s = int(g[r, src_c])
            t = int(g[r, tgt_c])
            if s != 0 and t != 0 and s not in mapping:
                mapping[s] = t

    palette_mask = np.zeros((H, W), dtype=bool)
    palette_mask[pr1:pr2 + 1, pc1:pc2 + 1] = True

    def components_8(color):
        mask = (g == color) & ~palette_mask
        seen = np.zeros((H, W), dtype=bool)
        comps = []
        for i in range(H):
            for j in range(W):
                if mask[i, j] and not seen[i, j]:
                    q = deque([(i, j)])
                    seen[i, j] = True
                    cells = []
                    rmin = rmax = i
                    cmin = cmax = j
                    while q:
                        r, c = q.popleft()
                        cells.append((r, c))
                        rmin = min(rmin, r)
                        rmax = max(rmax, r)
                        cmin = min(cmin, c)
                        cmax = max(cmax, c)
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < H and 0 <= nc < W and mask[nr, nc] and not seen[nr, nc]:
                                    seen[nr, nc] = True
                                    q.append((nr, nc))
                    comps.append((rmin, rmax, cmin, cmax, cells))
        return comps

    out = g.copy()

    for src, tgt in mapping.items():
        if src == tgt:
            continue
        for rmin, rmax, cmin, cmax, cells in components_8(src):
            if rmax - rmin + 1 < 3 or cmax - cmin + 1 < 3:
                continue
            for r in range(rmin + 1, rmax):
                for c in range(cmin + 1, cmax):
                    if out[r, c] == 0:
                        out[r, c] = tgt

    return [list(map(int, row)) for row in out]

import numpy as np
from collections import deque, Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # ------------------------------------------------------------------
    # 1) Find the palette/key.
    #    It is the largest solid (no 0) rectangle of size at least 2x2
    #    with at least two distinct colors and one side of length 2.
    #    Mapping is from the first side to the second side:
    #      height 2 -> top row maps to bottom row
    #      width  2 -> left column maps to right column
    # ------------------------------------------------------------------
    best = None  # (area, ncolors, vertical_priority, -r1, -c1, r1, r2, c1, c2)

    def consider(r1, r2, c1, c2, vertical, ncolors):
        nonlocal best
        h = r2 - r1 + 1
        w = c2 - c1 + 1
        if h < 2 or w < 2 or ncolors < 2:
            return
        area = h * w
        vprio = 1 if vertical else 0
        cand = (area, ncolors, vprio, -r1, -c1, r1, r2, c1, c2)
        if best is None or cand > best:
            best = cand

    # height == 2 strips
    for r1 in range(H - 1):
        r2 = r1 + 1
        c1 = 0
        while c1 < W:
            if g[r1, c1] == 0 or g[r2, c1] == 0:
                c1 += 1
                continue
            colors = set()
            c2 = c1
            while c2 < W and g[r1, c2] != 0 and g[r2, c2] != 0:
                colors.add(int(g[r1, c2]))
                colors.add(int(g[r2, c2]))
                if c2 - c1 + 1 >= 2:
                    consider(r1, r2, c1, c2, True, len(colors))
                c2 += 1
            c1 += 1

    # width == 2 strips
    for c1 in range(W - 1):
        c2 = c1 + 1
        r1 = 0
        while r1 < H:
            if g[r1, c1] == 0 or g[r1, c2] == 0:
                r1 += 1
                continue
            colors = set()
            r2 = r1
            while r2 < H and g[r2, c1] != 0 and g[r2, c2] != 0:
                colors.add(int(g[r2, c1]))
                colors.add(int(g[r2, c2]))
                if r2 - r1 + 1 >= 2:
                    consider(r1, r2, c1, c2, False, len(colors))
                r2 += 1
            r1 += 1

    if best is None:
        return [list(map(int, row)) for row in g]

    _, _, _, _, _, kr1, kr2, kc1, kc2 = best
    kh = kr2 - kr1 + 1
    kw = kc2 - kc1 + 1

    key_mask = np.zeros((H, W), dtype=bool)
    key_mask[kr1:kr2 + 1, kc1:kc2 + 1] = True

    # ------------------------------------------------------------------
    # 2) Build mapping from the key.
    # ------------------------------------------------------------------
    mapping = {}
    bad = set()

    if kh == 2 or (kh == 2 and kw != 2):
        for c in range(kc1, kc2 + 1):
            s = int(g[kr1, c])
            t = int(g[kr2, c])
            if s != 0 and t != 0:
                if s in mapping and mapping[s] != t:
                    bad.add(s)
                else:
                    mapping[s] = t
    elif kw == 2:
        for r in range(kr1, kr2 + 1):
            s = int(g[r, kc1])
            t = int(g[r, kc2])
            if s != 0 and t != 0:
                if s in mapping and mapping[s] != t:
                    bad.add(s)
                else:
                    mapping[s] = t
    else:
        # Fallback, should not be needed for the given rule.
        if kh <= kw:
            for c in range(kc1, kc2 + 1):
                s = int(g[kr1, c])
                t = int(g[kr2, c])
                if s != 0 and t != 0:
                    if s in mapping and mapping[s] != t:
                        bad.add(s)
                    else:
                        mapping[s] = t
        else:
            for r in range(kr1, kr2 + 1):
                s = int(g[r, kc1])
                t = int(g[r, kc2])
                if s != 0 and t != 0:
                    if s in mapping and mapping[s] != t:
                        bad.add(s)
                    else:
                        mapping[s] = t

    for s in bad:
        mapping.pop(s, None)

    if not mapping:
        return [list(map(int, row)) for row in g]

    # ------------------------------------------------------------------
    # 3) Fill enclosed zero regions.
    #    A zero region is enclosed if it is not 4-connected to the border.
    #    If its dominant border color has a mapping, recolor the region
    #    with the mapped color.  Key cells are ignored as borders.
    # ------------------------------------------------------------------
    out = g.astype(int).copy()
    visited = np.zeros((H, W), dtype=bool)

    for i in range(H):
        for j in range(W):
            if g[i, j] != 0 or visited[i, j]:
                continue

            q = deque([(i, j)])
            visited[i, j] = True
            cells = []
            touches_border = False
            border = Counter()

            while q:
                r, c = q.popleft()
                cells.append((r, c))

                if r == 0 or r == H - 1 or c == 0 or c == W - 1:
                    touches_border = True

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < H and 0 <= nc < W):
                        continue

                    val = int(g[nr, nc])
                    if val == 0:
                        if not visited[nr, nc]:
                            visited[nr, nc] = True
                            q.append((nr, nc))
                    else:
                        if not key_mask[nr, nc]:
                            border[val] += 1

            if touches_border or not border:
                continue

            max_cnt = max(border.values())
            max_colors = [col for col, cnt in border.items() if cnt == max_cnt]
            src_colors = [col for col in max_colors if col in mapping]

            src = None
            if len(max_colors) == 1:
                if max_colors[0] in mapping:
                    src = max_colors[0]
            elif len(src_colors) == 1:
                # Only fill if the mapped color is the unique dominant border color.
                # If it ties with a non-mapped color, leave unchanged.
                if all(col in mapping for col in max_colors):
                    src = min(src_colors)
                else:
                    src = None
            elif len(src_colors) > 1 and all(col in mapping for col in max_colors):
                # Multiple mapped colors with same dominant count: choose smallest.
                src = min(src_colors)

            if src is not None:
                fill_val = int(mapping[src])
                for r, c in cells:
                    out[r, c] = fill_val

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    a = np.array(grid, dtype=int)
    if a.size == 0:
        return []
    target = a[0, 0]

    b = a.copy()
    b[b == target] = 0
    b[0, 0] = target

    # Remove top row entirely unless it contains a non-zero cell other than the marker.
    # In all examples, row 0 is either just the marker or marker plus one neutral pixel;
    # both cases become all zeros in the output.
    if not np.any(b[0] != 0) or np.sum(b[0] != 0) <= 2:
        b[0] = 0

    # Find all "U-shaped" cups in the current grid:
    # top row y0, bottom y1, left x0, right x1 with y1-y0 <= 3 and x1-x0 <= 9,
    # non-zero corners/sides and empty interior.
    h, w = b.shape
    u_shapes = []
    for y0 in range(h - 1):
        for x0 in range(w - 1):
            x1 = x0 + 1
            while x1 < min(w, x0 + 10):
                top_ok = True
                for x in range(x0, x1 + 1):
                    if b[y0, x] == 0:
                        top_ok = False
                        break
                if not top_ok:
                    x1 += 1
                    continue

                left_ok = b[y0, x0] != 0
                right_ok = b[y0, x1] != 0

                y1 = y0 + 1
                while y1 < min(h, y0 + 4):
                    if left_ok and b[y1, x0] == 0:
                        left_ok = False
                    if right_ok and b[y1, x1] == 0:
                        right_ok = False
                    if left_ok and right_ok:
                        interior_ok = True
                        for y in range(y0, y1):
                            for x in range(x0 + 1, x1):
                                if b[y, x] != 0:
                                    interior_ok = False
                                    break
                            if not interior_ok:
                                break
                        if interior_ok and left_ok and right_ok:
                            u_shapes.append((y0, x0, y1, x1))
                    y1 += 1
                x1 += 1

    # A cup is processed only if its selected color is absent from one side.
    # For each side present, determine how far down it can fall without
    # crossing another non-zero pixel in the same column(s).
    for (y0, x0, y1, x1) in u_shapes:
        left_color = b[y0, x0]
        right_color = b[y0, x1]

        if left_color == target:
            left_fall = None
        else:
            if not all(b[y, x0] == left_color for y in range(y0, y1 + 1)):
                left_fall = None
            else:
                limit = h - 1
                for y in range(y1 + 1, h):
                    if b[y, x0] != 0:
                        limit = y - 1
                        break
                left_fall = max(0, min(limit - y1, y1 - y0 + 1))

        if right_color == target:
            right_fall = None
        else:
            if not all(b[y, x1] == right_color for y in range(y0, y1 + 1)):
                right_fall = None
            else:
                limit = h - 1
                for y in range(y1 + 1, h):
                    if b[y, x1] != 0:
                        limit = y - 1
                        break
                right_fall = max(0, min(limit - y1, y1 - y0 + 1))

        # Top bar falls until blocked in any of its columns.
        top_fall = None
        if left_fall is not None or right_fall is not None:
            limit = y1
            for x in range(x0 + 1, x1):
                col_limit = h - 1
                for y in range(y0 + 1, h):
                    if b[y, x] != 0:
                        col_limit = y - 1
                        break
                limit = min(limit, col_limit)
            top_fall = max(0, min(limit - y0, y1 - y0))

        # Apply falls, clearing old positions and writing new positions.
        # Sides first, then top, matching the observed outputs.
        if left_fall is not None:
            if left_fall > 0:
                b[y0:y1 + 1, x0] = 0
                b[y0 + left_fall:y1 + 1 + left_fall, x0] = left_color

        if right_fall is not None:
            if right_fall > 0:
                b[y0:y1 + 1, x1] = 0
                b[y0 + right_fall:y1 + 1 + right_fall, x1] = right_color

        if top_fall is not None:
            if top_fall > 0:
                # Do not overwrite side corners that are still present.
                b[y0, x0 + 1:x1] = 0
                new_y = y0 + top_fall
                for x in range(x0 + 1, x1):
                    b[new_y, x] = b[y0, x]
                    if b[y0, x] == 0:
                        b[new_y, x] = 0

    return b.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    a = np.array(grid, dtype=int)
    H, W = a.shape

    def bfs(start, forbidden):
        mask = (a != 0) & (a != forbidden)
        seen = np.zeros((H, W), dtype=bool)
        q = deque([start])
        seen[start] = True
        while q:
            r, c = q.popleft()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not seen[nr, nc] and mask[nr, nc]:
                    seen[nr, nc] = True
                    q.append((nr, nc))
        return seen

    target = a[0, 0]
    if target == 0 or not np.any(a == target):
        return a.tolist()

    # The target colour is removed everywhere except the top-left marker.
    # Only components that were connected to the target colour in the original
    # grid are allowed to move; other components stay fixed as obstacles.
    target_mask = (a == target)
    target_mask[0, 0] = False

    active = np.zeros((H, W), dtype=bool)
    for r in range(H):
        for c in range(W):
            if target_mask[r, c]:
                active |= bfs((r, c), target)

    obstacles = (a != 0) & (a != target) & (~active)
    out = a.copy()
    out[a == target] = 0
    out[0, 0] = target

    # Process the moving parts bottom-up and shift each part down by one at a
    # time while its destination is empty and unobstructed.
    while True:
        moved = False
        for r in range(H - 1, -1, -1):
            for c in range(W):
                if not active[r, c] or out[r, c] == 0:
                    continue
                if out[r + 1, c] == 0 and not obstacles[r + 1, c]:
                    out[r + 1, c] = out[r, c]
                    out[r, c] = 0
                    moved = True
        if not moved:
            break

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    h = len(grid)
    w = len(grid[0])

    # Background is the dominant border colour (all provided grids have a uniform border).
    border = []
    for c in range(w):
        border.append(grid[0][c])
        border.append(grid[-1][c])
    for r in range(1, h - 1):
        border.append(grid[r][0])
        border.append(grid[r][-1])
    bg = Counter(border).most_common(1)[0][0]

    out = [row[:] for row in grid]
    visited = [[False] * w for _ in range(h)]

    # 8-neighbourhood connectivity.
    dirs = [
        (dr, dc)
        for dr in (-1, 0, 1)
        for dc in (-1, 0, 1)
        if dr != 0 or dc != 0
    ]

    for r0 in range(h):
        for c0 in range(w):
            if visited[r0][c0] or grid[r0][c0] == bg:
                continue

            stack = [(r0, c0)]
            visited[r0][c0] = True
            comp = []
            max_r = r0

            while stack:
                r, c = stack.pop()
                comp.append((r, c))
                max_r = max(max_r, r)

                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and not visited[nr][nc]
                        and grid[nr][nc] != bg
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            # Modify only the bottom two rows of each connected object.
            for r, c in comp:
                if r == max_r:
                    out[r][c] = 3 if grid[r][c] == 8 else 8
                elif r == max_r - 1:
                    out[r][c] = 2 if grid[r][c] == 8 else 8

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    h = len(grid)
    w = len(grid[0])

    # Determine the background colour from the border.
    border = []
    for c in range(w):
        border.append(grid[0][c])
        border.append(grid[-1][c])
    for r in range(1, h - 1):
        border.append(grid[r][0])
        border.append(grid[r][-1])
    bg = Counter(border).most_common(1)[0][0]

    out = [row[:] for row in grid]
    visited = [[False] * w for _ in range(h)]

    # 8-connected components of non-background cells.
    dirs = [
        (dr, dc)
        for dr in (-1, 0, 1)
        for dc in (-1, 0, 1)
        if dr != 0 or dc != 0
    ]

    for r0 in range(h):
        for c0 in range(w):
            if visited[r0][c0] or grid[r0][c0] == bg:
                continue

            stack = [(r0, c0)]
            visited[r0][c0] = True
            cells = []

            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < w
                        and not visited[nr][nc]
                        and grid[nr][nc] != bg
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            # Rows of this component that contain colour 1 are safe.
            safe_rows = {r for r, c in cells if grid[r][c] == 1}

            # For every component row without colour 1:
            # - non-8 colours become 8
            # - 8 colours are restored to 2 in the first such row, otherwise 3
            rows = sorted({r for r, _ in cells})
            for r in rows:
                if r in safe_rows:
                    continue

                first_row_without_one = None
                for rr in rows:
                    if rr < r and rr not in safe_rows:
                        continue
                    first_row_without_one = rr
                    break

                for _, c in cells:
                    if (r, c) in [(rr, cc) for rr, cc in cells] and r == r and grid[r][c] == 8:
                        pass

                # simpler: iterate component cells in this row
                for rr, cc in cells:
                    if rr != r:
                        continue
                    if grid[r][cc] == 8:
                        if r == first_row_without_one:
                            out[r][cc] = 2
                        else:
                            out[r][cc] = 3
                    elif grid[r][cc] != bg:
                        out[r][cc] = 8

    return out

