def _connected_components(mask):
    h, w = mask.shape
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for y in range(h):
        for x in range(w):
            if mask[y, x] and not seen[y, x]:
                stack = [(y, x)]
                seen[y, x] = True
                cells = []
                while stack:
                    cy, cx = stack.pop()
                    cells.append((cy, cx))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = cy + dy, cx + dx
                            if 0 <= ny < h and 0 <= nx < w and mask[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                stack.append((ny, nx))
                comps.append(cells)
    return comps


def _orient(cells):
    # return (orientation, canonical 4-cell list) if cells form a T (3-in-line + middle perp)
    ys = {c[0] for c in cells}
    xs = {c[1] for c in cells}
    if len(ys) == 2 and len(xs) == 3:
        line_y = [y for y in ys if sum(1 for c in cells if c[0] == y) == 3][0]
        perp_y = [y for y in ys if y != line_y][0]
        line_xs = sorted(x for c in cells if c[0] == line_y)
        perp_x = [x for c in cells if c[0] == perp_y][0]
        if line_xs[1] == perp_x:
            d = -1 if perp_y < line_y else 1  # -1: stem above (canonical), +1: stem below
            return d, [(0, 0), (0, 1), (0, 2), (d, 1)]
    elif len(ys) == 3 and len(xs) == 2:
        line_x = [x for x in xs if sum(1 for c in cells if c[1] == x) == 3][0]
        perp_x = [x for x in xs if x != line_x][0]
        line_ys = sorted(y for c in cells if c[1] == line_x)
        perp_y = [y for c in cells if c[1] == perp_x][0]
        if line_ys[1] == perp_y:
            d = -1 if perp_x < line_x else 1  # -1: stem left (canonical)
            # canonical cells: stem to the LEFT of the vertical line
            return d, [(0, 0), (1, 0), (2, 0), (1, d)]
    return None, None


def _to_T(cells):
    o, canon = _orient(cells)
    if o is None:
        return None
    pts = np.array(cells, dtype=int)
    ys = {c[0] for c in cells}
    xs = {c[1] for c in cells}
    if len(ys) == 2 and len(xs) == 3:
        line_y = [y for y in ys if sum(1 for c in cells if c[0] == y) == 3][0]
        perp_y = [y for y in ys if y != line_y][0]
        line_xs = sorted(x for c in cells if c[0] == line_y)
        perp_x = [x for c in cells if c[0] == perp_y][0]
        # map: line -> row 0 cols 0,1,2 (left to right); perp -> (o,1)
        mapping = {}
        for i, lx in enumerate(line_xs):
            mapping[(line_y, lx)] = (0, i)
        mapping[(perp_y, perp_x)] = (o, 1)
    else:
        line_x = [x for x in xs if sum(1 for c in cells if c[1] == x) == 3][0]
        perp_x = [x for x in xs if x != line_x][0]
        line_ys = sorted(y for c in cells if c[1] == line_x)
        perp_y = [y for c in cells if c[1] == perp_x][0]
        mapping = {}
        for i, ly in enumerate(line_ys):
            mapping[(ly, line_x)] = (i, 0)
        mapping[(perp_y, perp_x)] = (1, o)
    arr = np.zeros((3, 3), dtype=int)
    for (yy, xx), (ny, nx) in mapping.items():
        arr[ny, nx] = 1
    return arr


def _flipV(arr):
    return arr[::-1, :].copy()


def _norm(arr):
    ys = [i for i in range(arr.shape[0]) for j in range(arr.shape[1]) if arr[i, j]]
    xs = [j for i in range(arr.shape[0]) for j in range(arr.shape[1]) if arr[i, j]]
    top, bottom = min(ys), max(ys)
    left, right = min(xs), max(xs)
    return arr[top:bottom + 1, left:right + 1]


