    cnt = Counter(P.flatten().tolist())
    pbg = cnt.most_common(1)[0][0]
    others = sorted([c for c, _ in cnt.most_common() if c != pbg], key=lambda c: -cnt[c])
    if not others:
        return None
    return (P == others[0])


