def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    center = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                center = (r, c)
                break
        if center is not None:
            break

    out = [row[:] for row in grid]
    if center is None:
        return out

    cr, cc = center

    # The container is the 3x3 block centered at the 2.
    block = []
    for r in range(cr - 1, cr + 2):
        for c in range(cc - 1, cc + 2):
            if 0 <= r < h and 0 <= c < w and grid[r][c] in (2, 3):
                block.append((r, c))

    if not block:
        return out

    # BFS from the center through every non-wall cell (only 6 blocks movement).
    dist = [[-1] * w for _ in range(h)]
    dist[cr][cc] = 0
    q = [(0, cr, cc)]
    heapq.heapify(q)

    while q:
        d, r, c = heapq.heappop(q)
        if d != dist[r][c]:
            continue
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 6 and dist[nr][nc] == -1:
                dist[nr][nc] = d + 1
                heapq.heappush(q, (d + 1, nr, nc))

    # Candidate 9 cells that can reach the center.
    candidates = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 9 and dist[r][c] != -1:
                candidates.append((dist[r][c], r, c))

    candidates.sort()

    n_fill = min(len(candidates), len(block))

    # Fill the 3x3 container in normal reading order, top-left to bottom-right.
    block.sort()
    for i in range(n_fill):
        out[block[i][0]][block[i][1]] = 9
        _, sr, sc = candidates[i]
        out[sr][sc] = 7

    return out

