    import collections
    import numpy as np

    g = [list(row) for row in grid]
    n = len(g)
    if n == 0:
        return []
    m = len(g[0]) if n else 0
    if m == 0:
        return []

    # Locate the unique central 2.
    center = None
    for r in range(n):
        for c in range(m):
            if g[r][c] == 2:
                center = (r, c)
                break
        if center is not None:
            break

    if center is None:
        return [row[:] for row in g]

    cr, cc = center

    # Cells in the central 3x3 block.
    center_cells = []
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            r = cr + dr
            c = cc + dc
            if 0 <= r < n and 0 <= c < m:
                center_cells.append((r, c))

    center_set = set(center_cells)

    # BFS from the whole central 3x3 block.
    # Only 6 blocks movement; 9 cells are traversable.
    dist = {cell: 0 for cell in center_cells}
    q = collections.deque(center_cells)

    while q:
        r, c = q.popleft()
        nd = dist[(r, c)] + 1
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                if (nr, nc) not in dist and g[nr][nc] != 6:
                    dist[(nr, nc)] = nd
                    q.append((nr, nc))

    # Reachable 9 cells outside the central block.
    source9s = [
        cell for cell in dist
        if cell not in center_set and g[cell[0]][cell[1]] == 9
    ]

    # Stable order: distance, then row-major.
    source9s.sort(key=lambda cell: (dist[cell], cell[0], cell[1]))

    # Move at most 9 such 9s into the center block.
    take = min(9, len(source9s))
    selected = source9s[:take]

    out = [row[:] for row in g]

    # Erase selected source 9s.
    for r, c in selected:
        out[r][c] = 7

    # Fill center block row-major with 9s.
    filled = 0
    for r, c in center_cells:
        if filled >= take:
            break
        out[r][c] = 9
        filled += 1

    return out

