def transform(grid: list[list[int]]) -> list[list[int]]:
    out = [row[:] for row in grid]
    h = len(grid)
    if h == 0:
        return out
    w = len(grid[0])

    def inside(r: int, c: int) -> bool:
        return 0 <= r < h and 0 <= c < w

    def is_six(r: int, c: int) -> bool:
        return inside(r, c) and grid[r][c] == 6

    # Identify input 6-pixels and the two cells immediately below each of them.
    # These are used only to find the initial "front" row/columns.
    seeds = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                seeds.append((r, c))
                if r + 1 < h:
                    seeds.append((r + 1, c))

    # Build the initial frontier row: the lowest input-6 row that has 6s,
    # and its horizontal span. In all valid inputs this is the bottom of the
    # vertical 6-stem(s) at the top of the grid.
    frontier_row = -1
    span_cols = []
    if seeds:
        frontier_row = max(r for r, c in seeds)
        span_cols = sorted({c for r, c in seeds if r == frontier_row})

    # If for some reason no stem is found, fall back to every 6 pixel's next row.
    if frontier_row == -1:
        frontier_row = 0
        span_cols = list(range(w))

    # Start with the input 6 pixels already in the output.
    for r, c in seeds:
        out[r][c] = 6

    # Expand the 6-region downward, row by row.
    #
    # For the current frontier row, keep all 6-cells in that row.
    # In the next row, put 6 in every column that is adjacent (including the
    # cell itself) to at least one current frontier 6-cell, but do not paint
    # over existing 2-pixels.  This creates the staircase / wall-following
    # pattern seen in the examples.
    cur = set(span_cols)

    for r in range(frontier_row + 1, h):
        nxt = set()
        for c in cur:
            for nc in (c - 1, c, c + 1):
                if 0 <= nc < w:
                    if grid[r][nc] != 2:
                        nxt.add(nc)
        if not nxt:
            break
        for c in nxt:
            out[r][c] = 6
        cur = nxt

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    if w == 0:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    def mark(r: int, c: int) -> None:
        if 0 <= r < h and 0 <= c < w and grid[r][c] != 2:
            out[r][c] = 6

    def two_segment_in_row(r: int, c: int) -> tuple[int, int]:
        if not (0 <= c < w) or grid[r][c] != 2:
            return c, c
        l = c
        while l > 0 and grid[r][l - 1] == 2:
            l -= 1
        rgt = c
        while rgt + 1 < w and grid[r][rgt + 1] == 2:
            rgt += 1
        return l, rgt

    # Start from the bottom row of each input 6-component that touches the
    # top part of the grid.  In the supplied puzzles these are 1- or 2-cell
    # vertical stems beginning at row 0.
    active_cols = set()
    start_row = 0

    # If there is no 6 on row 0, fall back to the lowest row containing 6.
    if not any(grid[0][c] == 6 for c in range(w)):
        last6 = -1
        for r in range(h):
            if any(grid[r][c] == 6 for c in range(w)):
                last6 = r
        if last6 == -1:
            return out
        start_row = last6
        for c in range(w):
            if grid[start_row][c] == 6:
                active_cols.add(c)
    else:
        # Take the lower endpoint of each contiguous vertical 6-stem starting
        # at row 0.  This avoids double starting from both cells of a stem.
        c = 0
        while c < w:
            if grid[0][c] == 6:
                c2 = c
                r = 0
                while r + 1 < h and grid[r + 1][c2] == 6:
                    r += 1
                active_cols.add(c2)
                c = c2 + 1
            else:
                c += 1

    # Propagate downward.  The active set is the set of 6 columns in the
    # current row.  When a column sees a 2 in the next row, it bypasses the
    # whole horizontal 2-segment in the next row by painting the current row
    # across that segment (plus the immediately free cells outside it).
    # The next-row active columns are those free outside cells.
    for r in range(start_row, h - 1):
        if not active_cols:
            break

        next_active = set()
        paint = set()

        for c in active_cols:
            if grid[r + 1][c] == 2:
                l, rr = two_segment_in_row(r + 1, c)

                # Paint the bypass shelf in the current row.
                left = l - 1
                right = rr + 1
                if left < 0:
                    left = l
                if right >= w:
                    right = rr
                for cc in range(left, right + 1):
                    if grid[r][cc] != 2:
                        paint.add(cc)

                # Continue on the free cells just outside the 2-segment.
                if left >= 0 and grid[r + 1][left] != 2:
                    next_active.add(left)
                if right < w and grid[r + 1][right] != 2:
                    next_active.add(right)
            else:
                # Straight down through a non-2 cell.
                paint.add(c)
                next_active.add(c)

        for c in paint:
            mark(r, c)

        active_cols = next_active

    # Mark the final row positions if the active front reaches the bottom.
    if start_row < h:
        for c in active_cols:
            mark(start_row, c)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return grid

    H = len(grid)
    W = len(grid[0])

    # Find the column of 5s
    C_sep = -1
    for c in range(W):
        if all(grid[r][c] == 5 for r in range(H)):
            C_sep = c
            break

    if C_sep == -1:
        return [row[:] for row in grid]

    # Create a deep copy for the output
    out = [row[:] for row in grid]

    # Process in blocks of height 4
    H_block = 4
    for r in range(0, H, H_block):
        block_h = min(H_block, H - r)

        # Extract the left part of the block
        left = [grid[r+i][0:C_sep] for i in range(block_h)]

        for i in range(block_h):
            row = left[i]
            if not row:
                continue

            # Cyclic right shift of the columns for this row
            shifted_row = [row[-1]] + row[:-1]

            # Place the shifted row into the output
            out[r+i][0:C_sep] = shifted_row

            # Check if the shifted row ends with '60'
            if len(shifted_row) >= 2 and shifted_row[-1] == 0 and shifted_row[-2] == 6:
                # Replace all 6s with 2s in the right part of this row
                for c in range(C_sep, W):
                    if out[r+i][c] == 6:
                        out[r+i][c] = 2

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    h, w = len(grid), len(grid[0])

    # The background is the colour occupying the border of the whole grid.
    bg = int(grid[0][0])

    # Objects are rectangular frames with border colour 2 or 8.
    # border 8 is moved left, border 2 is moved right.
    # Vertical position is preserved.
    # Left movers are packed to the left in increasing original x order.
    # Right movers are packed to the right in decreasing original x order.

    objects = []
    used = [[False] * w for _ in range(h)]

    def is_frame(r0, c0, r1, c1, border):
        if r0 < 0 or c0 < 0 or r0 > r1 or c0 > c1:
            return False
        if r1 >= h or c1 >= w:
            return False

        # Border must be exactly the chosen colour.
        for r in range(r0, r1 + 1):
            for c in (c0, c1):
                if grid[r][c] != border:
                    return False
        for c in range(c0, c1 + 1):
            for r in (r0, r1):
                if grid[r][c] != border:
                    return False

        # Interior must be uniform, non-background, and different from border.
        if r1 - r0 < 1 or c1 - c0 < 1:
            return False

        inner = grid[r0 + 1][c0 + 1]
        if inner == bg or inner == border:
            return False

        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if grid[r][c] != inner:
                    return False
        return True

    # Find all maximal rectangular frames.  In the supplied puzzles these are
    # 5x5, but this also handles the slightly stretched example frame.
    for r in range(h):
        for c in range(w):
            if used[r][c] or grid[r][c] not in (2, 8):
                continue

            # Try possible frames whose top-left corner is at or above/left of this cell.
            found = None
            for hgt in range(max(3, 1), 9):          # enough for all examples/tests
                for wid in range(max(3, 1), 9):
                    r1 = r + hgt - 1
                    c1 = c + wid - 1
                    if r1 >= h or c1 >= w:
                        continue
                    if is_frame(r, c, r1, c1, grid[r][c]):
                        # Prefer the smallest frame that contains the top-left border cell.
                        found = (r, c, r1, c1, grid[r][c])
                        break
                if found:
                    break

            if found:
                r0, c0, r1, c1, border = found
                # Mark the whole frame as used.
                for rr in range(r0, r1 + 1):
                    for cc in range(c0, c1 + 1):
                        used[rr][cc] = True
                objects.append((r0, c0, r1, c1, border))

    # It is possible for nested / adjacent detections to overlap; keep only
    # frames that are not strictly contained in a larger detected frame.
    kept = []
    for i, o in enumerate(objects):
        contained = False
        for j, other in enumerate(objects):
            if i == j:
                continue
            if (other[0] <= o[0] and other[1] <= o[1] and
                other[2] >= o[2] and other[3] >= o[3] and
                (other[0] < o[0] or other[1] < o[1] or
                 other[2] > o[2] or other[3] > o[3])):
                contained = True
                break
        if not contained:
            kept.append(o)
    objects = kept

    out = [[bg] * w for _ in range(h)]

    def stamp(r0, c0, r1, c1, border):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if r == r0 or r == r1 or c == c0 or c == c1:
                    out[r][c] = border
        if r1 - r0 >= 1 and c1 - c0 >= 1:
            inner = grid[r0 + 1][c0 + 1]
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    out[r][c] = inner

    def overlaps(a, b):
        return not (a[2] < b[0] or b[2] < a[0] or a[3] < b[1] or b[3] < a[1])

    left_objs = [o for o in objects if o[4] == 8]
    right_objs = [o for o in objects if o[4] == 2]

    placed = []

    # Left movers: leftmost possible x, preserving original left-to-right order.
    for obj in sorted(left_objs, key=lambda x: x[1]):
        r0, _, r1, _, border = obj
        width = obj[3] - obj[1] + 1
        x = 0
        while True:
            cand = (r0, x, r1, x + width - 1, border)
            ok = True
            for p in placed:
                if overlaps(cand, p):
                    ok = False
                    break
            if ok:
                break
            x += 1
            if x > w - 1:
                x = max(0, w - width)
                break
        placed.append((r0, x, r1, x + width - 1, border))
        stamp(r0, x, r1, x + width - 1, border)

    # Right movers: rightmost possible x, preserving original left-to-right order.
    for obj in sorted(right_objs, key=lambda x: -x[1]):
        r0, _, r1, _, border = obj
        width = obj[3] - obj[1] + 1
        x = w - width
        while True:
            cand = (r0, x, r1, x + width - 1, border)
            ok = True
            for p in placed:
                if overlaps(cand, p):
                    ok = False
                    break
            if ok:
                break
            x -= 1
            if x < 0:
                x = 0
                break
        placed.append((r0, x, r1, x + width - 1, border))
        stamp(r0, x, r1, x + width - 1, border)

    return [list(map(int, row)) for row in out]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    bg = grid[0][0]

    def is_5x5_frame(r, c):
        if r < 0 or c < 0 or r + 4 >= h or c + 4 >= w:
            return False

        b = grid[r][c]
        if b not in (2, 8):
            return False

        # top and bottom rows must be exactly the border color
        for cc in range(c, c + 5):
            if grid[r][cc] != b or grid[r + 4][cc] != b:
                return False

        # interior must be a single non-background color
        inner = grid[r + 1][c + 1]
        if inner == bg or inner == b:
            return False

        for rr in range(r + 1, r + 4):
            for cc in range(c + 1, c + 4):
                if grid[rr][cc] != inner:
                    return False

        # left and right borders
        for rr in range(r, r + 5):
            if grid[rr][c] != b or grid[rr][c + 4] != b:
                return False

        return True

    # Detect normal 5x5 frames.
    detected = set()
    objs = []
    for r in range(h - 4):
        for c in range(w - 4):
            if is_5x5_frame(r, c):
                key = (r, c)
                if key in detected:
                    continue
                detected.add(key)
                objs.append((r, c, grid[r][c], grid[r + 1][c + 1]))

    # Fallback for the one irregular example where a frame has an extra
    # interior row: find a 5-wide top border followed by interior rows.
    for r in range(h - 4):
        for c in range(w - 4):
            if (r, c) in detected:
                continue

            b = grid[r][c]
            if b not in (2, 8):
                continue

            if any(grid[r][cc] != b for cc in range(c, c + 5)):
                continue

            inner = None
            ok = True
            for rr in range(r + 1, min(r + 5, h - 4)):
                if grid[rr][c] != b or grid[rr][c + 4] != b:
                    ok = False
                    break
                if any(grid[rr][cc] == b or grid[rr][cc] == bg
                       for cc in range(c + 1, c + 4)):
                    ok = False
                    break
                if inner is None:
                    inner = grid[rr][c + 1]
                elif grid[rr][c + 1] != inner:
                    ok = False
                    break

            if ok and inner is not None and inner != b and inner != bg:
                objs.append((r, c, b, inner))

    # Remove duplicates and invalid overlaps if any.
    clean = []
    for o in objs:
        r, c, b, inner = o
        dup = False
        for q in clean:
            qr, qc, qb, qi = q
            if abs(r - qr) < 5 and abs(c - qc) < 5:
                dup = True
                break
        if not dup:
            clean.append(o)
    objs = clean

    out = [[bg] * w for _ in range(h)]

    def stamp(o):
        r, c, b, inner = o
        for rr in range(r, r + 5):
            for cc in range(c, c + 5):
                if rr == r or rr == r + 4 or cc == c or cc == c + 4:
                    out[rr][cc] = b
                else:
                    out[rr][cc] = inner

    def overlap(a, b):
        return not (a[0] + 5 <= b[0] or b[0] + 5 <= a[0] or
                    a[1] + 5 <= b[1] or b[1] + 5 <= a[1])

    placed = []

    # Border 8 frames slide left.
    lefts = sorted((o for o in objs if o[2] == 8), key=lambda x: x[1])
    for o in lefts:
        r, c, b, inner = o
        x = 0
        while True:
            cand = (r, x, b, inner)
            if all(not overlap(cand, p) for p in placed):
                break
            x += 1
            if x > w - 5:
                x = 0
                break
        placed.append((r, x, b, inner))
        stamp((r, x, b, inner))

    # Border 2 frames slide right.
    rights = sorted((o for o in objs if o[2] == 2), key=lambda x: -x[1])
    for o in rights:
        r, c, b, inner = o
        x = w - 5
        while True:
            cand = (r, x, b, inner)
            if all(not overlap(cand, p) for p in placed):
                break
            x -= 1
            if x < 0:
                x = 0
                break
        placed.append((r, x, b, inner))
        stamp((r, x, b, inner))

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    sys.setrecursionlimit(1000000)

    H = len(grid)
    W = len(grid[0]) if H else 0

    # Most common colour is treated as the background.
    from collections import Counter
    cnt = Counter(c for row in grid for c in row)
    bg = cnt.most_common(1)[0][0]

    # Find connected components of non-background pixels.
    seen = [[False] * W for _ in range(H)]
    components = []

    for r in range(H):
        for c in range(W):
            if not seen[r][c] and grid[r][c] != bg:
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for ny, nx in ((y - 1, x), (y + 1, x), (y, y + 1, x), (y, y + 1, x)):
                        if 0 <= ny < H and 0 <= nx < W and not seen[ny][nx] and grid[ny][nx] != bg:
                            seen[ny][nx] = True
                            stack.append((ny, nx))
                components.append(cells)

    boxes = []

    for cells in components:
        if len(cells) < 9:
            continue

        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)

        h = rmax - rmin + 1
        w = cmax - cmin + 1

        # The visible component may be a union of one or more 5x5 frames.
        # Estimate the number of frames from area and extract 5x5 squares
        # from it, left-to-right, top-to-bottom.
        area = len(cells)
        k = max(1, min(area // 15, h, w))

        comp_set = set(cells)
        used = set()
        extracted = []

        for r0 in range(rmin, rmax - 4 + 1):
            for c0 in range(cmin, cmax - 4 + 1):
                if len(extracted) >= k:
                    break
                sq = [(r0 + dr, c0 + dc)
                      for dr in range(5)
                      for dc in range(5)]
                if all(p in comp_set and p not in used for p in sq):
                    used.update(sq)
                    extracted.append((r0, c0, sq))
            if len(extracted) >= k:
                break

        # Fallback: if not enough clean 5x5 squares were found, take the
        # leftmost/topmost 5x5 window containing component pixels.
        if not extracted:
            extracted = [(rmin, cmin, None)]

        for r0, c0, sq in extracted:
            if sq is None:
                pixels = [grid[r][c] for r, c in cells]
            else:
                pixels = [grid[r][c] for r, c in sq]

            pc = Counter(pixels)
            border = pc.most_common(1)[0][0]
            rest = pc - Counter({border: 1})
            fill = rest.most_common(1)[0][0] if rest else bg

            boxes.append({
                "r": r0,
                "c": c0,
                "border": border,
                "fill": fill,
                "h": 5,
                "w": 5,
            })

    # Keep only plausible frames with two non-background colours.
    boxes = [
        b for b in boxes
        if b["border"] != bg and b["fill"] != bg and b["border"] != b["fill"]
    ]

    # Move 8-bordered boxes left, 2-bordered boxes right.
    def overlaps(a, b):
        return not (
            a["r"] + a["h"] <= b["r"] or
            b["r"] + b["h"] <= a["r"] or
            a["c"] + a["w"] <= b["c"] or
            b["c"] + b["w"] <= a["c"]
        )

    for _ in range(H + W + 1):
        moved = False
        for b in boxes:
            if b["border"] == 8:
                if b["c"] > 0:
                    nb = dict(b)
                    nb["c"] -= 1
                    if not any(overlaps(nb, o) for o in boxes if o is not b):
                        b["c"] -= 1
                        moved = True
            elif b["border"] == 2:
                if b["c"] < W - 5:
                    nb = dict(b)
                    nb["c"] += 1
                    if not any(overlaps(nb, o) for o in boxes if o is not b):
                        b["c"] += 1
                        moved = True
        if not moved:
            break

    # Draw the resulting 5x5 frames on a fresh background grid.
    out = [[bg] * W for _ in range(H)]

    for b in boxes:
        r0, c0 = b["r"], b["c"]
        border, fill = b["border"], b["fill"]
        for r in range(r0, r0 + 5):
            for c in range(c0, c0 + 5):
                if r < 0 or r >= H or c < 0 or c >= W:
                    continue
                if r == r0 or r == r0 + 4 or c == c0 or c == c0 + 4:
                    out[r][c] = border
                else:
                    out[r][c] = fill

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import Counter

    H = len(grid)
    W = len(grid[0]) if H else 0
    if H == 0 or W == 0:
        return []

    # Background is the most frequent colour.
    bg = Counter(c for row in grid for c in row).most_common(1)[0][0]

    # Detect all 5x5 square frames:
    #   - outer ring is one colour (not background)
    #   - inner 3x3 is uniform and different from the border colour
    frames = []
    seen = set()

    for r in range(H - 4):
        for c in range(W - 4):
            if (r, c) in seen:
                continue

            b = grid[r][c]
            if b == bg:
                continue

            ok = True
            # Top and bottom border
            for x in range(c, c + 5):
                if grid[r][x] != b or grid[r + 4][x] != b:
                    ok = False
                    break
            if not ok:
                continue

            # Left and right border
            for y in range(r + 1, r + 4):
                if grid[y][c] != b or grid[y][c + 4] != b:
                    ok = False
                    break
            if not ok:
                continue

            # Interior
            f = grid[r + 1][c + 1]
            if f == b:
                continue
            for y in range(r + 1, r + 4):
                for x in range(c + 1, c + 4):
                    if grid[y][x] != f:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue

            seen.add((r, c))
            frames.append({
                "r": r,
                "c0": c,
                "x": c,
                "w": 5,
                "h": 5,
                "border": b,
                "fill": f,
            })

    def rows_overlap(a, b):
        return a["r"] < b["r"] + 5 and b["r"] < a["r"] + 5

    # 8-bordered frames move left, 2-bordered frames move right.
    # They only block frames of the same border colour.
    for border, direction in ((8, "left"), (2, "right")):
        group = [fr for fr in frames if fr["border"] == border]

        if direction == "left":
            # Preserve left-to-right order.
            group.sort(key=lambda fr: (fr["c0"], fr["r"]))
            for fr in group:
                left_limit = 0
                for other in group:
                    if other is fr or not rows_overlap(fr, other):
                        continue
                    # Frames processed so far are to the left.
                    left_limit = max(left_limit, other["x"] + other["w"])
                fr["x"] = min(fr["c0"], max(0, left_limit))
        else:
            # Preserve right-to-left order.
            group.sort(key=lambda fr: (-fr["c0"], fr["r"]))
            for fr in group:
                right_limit = W - 5
                for other in group:
                    if other is fr or not rows_overlap(fr, other):
                        continue
                    # Frames processed so far are to the right.
                    right_limit = min(right_limit, other["x"] - other["w"])
                fr["x"] = max(0, min(fr["c0"], right_limit))

    # Draw final frames on a fresh background grid.
    out = [[bg] * W for _ in range(H)]

    for fr in frames:
        r0 = fr["r"]
        c0 = fr["x"]
        b = fr["border"]
        f = fr["fill"]

        for r in range(r0, r0 + 5):
            for c in range(c0, c0 + 5):
                if 0 <= r < H and 0 <= c < W:
                    if r == r0 or r == r0 + 4 or c == c0 or c == c0 + 4:
                        out[r][c] = b
                    else:
                        out[r][c] = f

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    if a.size == 0:
        return []

    h, w = a.shape
    vals, counts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(counts)])

    mask = (a != bg)
    if not mask.any():
        return a.tolist()

    fill_color = 2 if (2 == bg) is False else 1

    out = a.copy()
    out[mask] = fill_color
    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    def color_counts(sub):
        vals, cnts = np.unique(sub, return_counts=True)
        if len(vals) == 0:
            return None
        order = np.argsort(-cnts)
        return vals[order].tolist(), cnts[order].tolist()

    # candidate vertical split: one side has exactly two colors (frame + hole)
    best = None
    for k in range(1, W):
        left = g[:, :k]
        right = g[:, k:]
        lc = color_counts(left)
        rc = color_counts(right)
        if lc is None or rc is None:
            continue
        if len(lc[0]) == 2 and len(rc[0]) > 2:
            # prefer split where frame is the minority color of the two-color side
            frame = lc[0][1] if lc[1][1] <= lc[1][0] else lc[0][0]
            score = abs(lc[1][0] - lc[1][1])  # distinctness
            if best is None or score > best[0]:
                best = (score, "V", k, frame, right)

    # candidate horizontal split: one side has exactly two colors
    for k in range(1, H):
        top = g[:k, :]
        bottom = g[k:, :]
        tc = color_counts(top)
        bc = color_counts(bottom)
        if tc is None or bc is None:
            continue
        if len(bc[0]) == 2 and len(tc[0]) > 2:
            frame = bc[0][1] if bc[1][1] <= bc[1][0] else bc[0][0]
            score = abs(bc[1][0] - bc[1][1])
            if best is None or score > best[0]:
                best = (score, "H", k, frame, top)
        elif len(tc[0]) == 2 and len(bc[0]) > 2:
            frame = tc[0][1] if tc[1][1] <= tc[1][0] else tc[0][0]
            score = abs(tc[1][0] - tc[1][1])
            if best is None or score > best[0]:
                best = (score, "H2", k, frame, bottom)

    if best is None:
        return [list(map(int, row)) for row in g]

    _, kind, split, frame, source = best

    # Build output mask: the side with exactly two colors
    if kind == "V":
        out = g[:, :split].copy()
        out[out != frame] = 0
    elif kind == "H":
        out = g[split:, :].copy()
        out[out != frame] = 0
    else:  # H2
        out = g[:split, :].copy()
        out[out != frame] = 0

    hole_mask = (out == 0)
    out[out == 0] = frame

    # Connected components of holes (4-neighbourhood)
    h_out, w_out = out.shape
    visited = np.zeros_like(hole_mask, dtype=bool)
    comps = []

    for r in range(h_out):
        for c in range(w_out):
            if hole_mask[r, c] and not visited[r, c]:
                stack = [(r, c)]
                visited[r, c] = True
                cells = []
                while stack:
                    y, x = stack.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h_out and 0 <= nx < w_out:
                            if hole_mask[ny, nx] and not visited[ny, nx]:
                                visited[ny, nx] = True
                                stack.append((ny, nx))
                ys = [p[0] for p in cells]
                xs = [p[1] for p in cells]
                bbox = (min(ys), max(ys), min(xs), max(xs))
                comps.append((bbox, cells))

    # Source object rectangles: maximal solid rectangles of non-background colors
    s_vals, s_cnts = np.unique(source, return_counts=True)
    if len(s_vals) == 0:
        return [list(map(int, row)) for row in out]
    s_bg = int(s_vals[np.argmax(s_cnts)])

    h_src, w_src = source.shape
    rectangles = []
    for r in range(h_src):
        for c in range(w_src):
            if source[r, c] == s_bg:
                continue
            color = int(source[r, c])
            # grow rectangle greedily to the right and down
            max_c = c
            while max_c + 1 < w_src and source[r, max_c + 1] == color:
                max_c += 1
            max_r = r
            ok = True
            while max_r + 1 < h_src and ok:
                ok = True
                for cc in range(c, max_c + 1):
                    if source[max_r + 1, cc] != color:
                        ok = False
                        break
                if ok:
                    max_r += 1

            # accept only if solid and not contained in a larger already-added rectangle
            cells = [(rr, cc) for rr in range(r, max_r + 1) for cc in range(c, max_c + 1)]
            solid = all(int(source[rr, cc]) == color for rr, cc in cells)
            if not solid:
                continue

            contained = False
            for (r2, r3, c2, c3, col2) in rectangles:
                if col2 == color and r2 <= r and r3 >= max_r and c2 <= c and c3 >= max_c:
                    contained = True
                    break
            if contained:
                continue
            rectangles.append((r, max_r, c, max_c, color))

    # For each hole component, fill using any rectangle that covers all its cells.
    # If several fit, choose the one with minimum area, then color.
    for bbox, cells in comps:
        r1, r2, c1, c2 = bbox
        fitting = []
        for rr1, rr2, cc1, cc2, col in rectangles:
            if rr1 <= r1 and rr2 >= r2 and cc1 <= c1 and cc2 >= c2:
                area = (rr2 - rr1 + 1) * (cc2 - cc1 + 1)
                fitting.append((area, col))
        if fitting:
            fill = min(fitting, key=lambda x: (x[0], x[1]))[1]
        else:
            # fallback: majority source non-bg color among nearest cells
            fill = s_bg
            counts = {}
            for y, x in cells:
                for rr, cc in ((y, x), (y + 1, x), (y - 1, x), (y, x + 1), (y, x - 1)):
                    if 0 <= rr < h_src and 0 <= cc < w_src:
                        val = int(source[rr, cc])
                        if val != s_bg:
                            counts[val] = counts.get(val, 0) + 1
            if counts:
                fill = max(counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]
        for y, x in cells:
            out[y, x] = fill

    return [list(map(int, row)) for row in out]

import sys
from itertools import product

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    def connected_components(mask):
        comp = [[-1] * W for _ in range(H)]
        comps = []
        for r in range(H):
            for c in range(W):
                if mask[r][c] and comp[r][c] == -1:
                    cid = len(comps)
                    stack = [(r, c)]
                    comp[r][c] = cid
                    cells = []
                    while stack:
                        y, x = stack.pop()
                        cells.append((y, x))
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < H and 0 <= nx < W:
                                if mask[ny][nx] and comp[ny][nx] == -1:
                                    comp[ny][nx] = cid
                                    stack.append((ny, nx))
                    comps.append(cells)
        return comps

    def is_rectangle(cells):
        if not cells:
            return False
        rmin = min(r for r, _ in cells)
        rmax = max(r for r, _ in cells)
        cmin = min(c for _, c in cells)
        cmax = max(c for _, c in cells)
        return (rmax - rmin + 1) * (cmax - cmin + 1) == len(cells)

    def extract_pieces(mask_rect, bg_color, forbidden):
        # mask_rect: (r0, r1, c0, c1) inclusive? use [r0, r1), [c0, c1)
        r0, r1, c0, c1 = mask_rect
        mask = [[False] * W for _ in range(H)]
        for r in range(r0, r1):
            for c in range(c0, c1):
                if grid[r][c] != bg_color and grid[r][c] != forbidden:
                    mask[r][c] = True

        pieces = []
        for cells in connected_components(mask):
            if not is_rectangle(cells):
                continue
            rmin = min(r for r, _ in cells)
            rmax = max(r for r, _ in cells)
            cmin = min(c for _, c in cells)
            cmax = max(c for _, c in cells)
            ph = rmax - rmin + 1
            pw = cmax - cmin + 1
            pattern = [[grid[r][c] for c in range(cmin, cmax + 1)] for r in range(rmin, rmax + 1)]
            # ensure it is a full rectangle of non-background pieces
            ok = all(grid[r][c] != bg_color and grid[r][c] != forbidden
                     for r in range(rmin, rmax + 1)
                     for c in range(cmin, cmax + 1))
            if ok:
                pieces.append((ph, pw, pattern, rmin, cmin))
        return pieces

    def solve_tiling(th, tw, hole, pieces):
        total_hole = sum(row.count(True) for row in hole)
        if sum(ph * pw for ph, pw, _, _, _ in pieces) != total_hole:
            return None

        # Precompute all possible placements for each piece identity.
        placements_by_piece = []
        for ph, pw, pattern, _, _ in pieces:
            pos = []
            for r in range(th - ph + 1):
                for c in range(tw - pw + 1):
                    ok = True
                    for i in range(ph):
                        for j in range(pw):
                            if not hole[r + i][c + j]:
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        pos.append((r, c))
            placements_by_piece.append(pos)

        # If any piece has no placement, fail.
        if any(len(p) == 0 for p in placements_by_piece):
            return None

        # Cell -> list of (piece_idx, placement_idx)
        cell_options = {}
        for r in range(th):
            for c in range(tw):
                if hole[r][c]:
                    cell_options[(r, c)] = []
        for pi, pos in enumerate(placements_by_piece):
            ph, pw, _, _, _ = pieces[pi]
            for k, (r, c) in enumerate(pos):
                for i in range(ph):
                    for j in range(pw):
                        cell_options[(r + i, c + j)].append((pi, k))

        # Exact cover backtracking.
        used_piece = [False] * len(pieces)
        used_placement = [[False] * len(pos) for pos in placements_by_piece]
        assignment = [None] * len(pieces)

        def covered_count(r, c):
            # not needed directly
            pass

        def choose_cell():
            best = None
            best_count = 10**9
            for cell, opts in cell_options.items():
                # count viable options: piece unused and placement unused, and all its cells currently uncovered.
                cnt = 0
                for pi, k in opts:
                    if used_piece[pi] or used_placement[pi][k]:
                        continue
                    ph, pw, _, _, _ = pieces[pi]
                    r, c = placements_by_piece[pi][k]
                    ok = True
                    for i in range(ph):
                        for j in range(pw):
                            # Need to know if cell is covered. We'll maintain a covered boolean grid.
                            if covered[r + i][c + j]:
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        cnt += 1
                if cnt < best_count:
                    best_count = cnt
                    best = cell
                    if best_count <= 1:
                        break
            return best, best_count

        covered = [[False] * tw for _ in range(th)]

        sys.setrecursionlimit(10000)

        def dfs():
            cell, cnt = choose_cell()
            if cnt == 0:
                return False
            r, c = cell
            for pi, k in cell_options[(r, c)]:
                if used_piece[pi] or used_placement[pi][k]:
                    continue
                ph, pw, _, _, _ = pieces[pi]
                rr, cc = placements_by_piece[pi][k]
                ok = True
                for i in range(ph):
                    for j in range(pw):
                        if covered[rr + i][cc + j]:
                            ok = False
                            break
                    if not ok:
                        break
                if not ok:
                    continue

                used_piece[pi] = True
                used_placement[pi][k] = True
                assignment[pi] = (rr, cc)
                for i in range(ph):
                    for j in range(pw):
                        covered[rr + i][cc + j] = True

                if dfs():
                    return True

                for i in range(ph):
                    for j in range(pw):
                        covered[rr + i][cc + j] = False
                assignment[pi] = None
                used_placement[pi][k] = False
                used_piece[pi] = False

            return False

        if not dfs():
            return None
        return assignment

    def try_candidate(r0, r1, c0, c1, template_colors, F, Hcol):
        th = r1 - r0
        tw = c1 - c0
        hole = [[False] * tw for _ in range(th)]
        for r in range(th):
            for c in range(tw):
                if grid[r0 + r][c0 + c] == Hcol:
                    hole[r][c] = True

        # outside rectangle(s): union of complement. Since candidate is full-width or full-height strip,
        # outside is rectangular on one side, but handle general by scanning all outside cells.
        outside_mask = [[False] * W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                if not (r0 <= r < r1 and c0 <= c < c1):
                    outside_mask[r][c] = True

        # Extract pieces from outside. Use a bounding rectangle that covers all outside cells.
        outside_cols = [c for c in range(W) if any(outside_mask[r][c] for r in range(H))]
        outside_rows = [r for r in range(H) if any(outside_mask[r][c] for c in range(W))]
        if not outside_rows or not outside_cols:
            return None

        # For piece extraction, we need a rectangular mask. Since our candidates are full strips,
        # outside is a rectangle. But to be safe, use full grid and exclude template by forbidden? 
        # We'll create a mask over full grid where outside cells are eligible.
        piece_mask = [[False] * W for _ in range(H)]
        for r in range(H):
            for c in range(W):
                if outside_mask[r][c] and grid[r][c] != Hcol and grid[r][c] != F:
                    piece_mask[r][c] = True

        pieces = []
        for cells in connected_components(piece_mask):
            if not is_rectangle(cells):
                continue
            rmin = min(r for r, _ in cells)
            rmax = max(r for r, _ in cells)
            cmin = min(c for _, c in cells)
            cmax = max(c for _, c in cells)
            ph = rmax - rmin + 1
            pw = cmax - cmin + 1
            ok = all(piece_mask[r][c] for r in range(rmin, rmax + 1) for c in range(cmin, cmax + 1))
            if ok:
                pattern = [[grid[r][c] for c in range(cmin, cmax + 1)] for r in range(rmin, rmax + 1)]
                pieces.append((ph, pw, pattern, rmin, cmin))

        assignment = solve_tiling(th, tw, hole, pieces)
        if assignment is None:
            return None

        out = [[0] * tw for _ in range(th)]
        for r in range(th):
            for c in range(tw):
                out[r][c] = grid[r0 + r][c0 + c]

        for pi, (rr, cc) in enumerate(assignment):
            ph, pw, pattern, _, _ = pieces[pi]
            for i in range(ph):
                for j in range(pw):
                    out[rr + i][cc + j] = pattern[i][j]

        return out

    candidates = []

    # Full-height vertical strips
    for c0 in range(W):
        for c1 in range(c0, W):
            vals = set()
            ok = True
            for r in range(H):
                for c in range(c0, c1 + 1):
                    vals.add(grid[r][c])
                    if len(vals) > 2:
                        ok = False
                        break
                if not ok:
                    break
            if ok and len(vals) == 2:
                candidates.append((0, H, c0, c1 + 1))

    # Full-width horizontal strips
    for r0 in range(H):
        for r1 in range(r0, H):
            vals = set()
            ok = True
            for r in range(r0, r1 + 1):
                for c in range(W):
                    vals.add(grid[r][c])
                    if len(vals) > 2:
                        ok = False
                        break
                if not ok:
                    break
            if ok and len(vals) == 2:
                candidates.append((r0, r1 + 1, 0, W))

    # Prefer larger templates first, but validate all.
    candidates = sorted(set(candidates), key=lambda x: -((x[1] - x[0]) * (x[3] - x[2])))

    # Try both possible frame/hole assignments for each candidate.
    tried = set()
    for cand in candidates:
        r0, r1, c0, c1 = cand
        vals = set()
        for r in range(r0, r1):
            for c in range(c0, c1):
                vals.add(grid[r][c])
        if len(vals) != 2:
            continue
        a, b = tuple(vals)
        # choose hole color: the one more frequent outside, if possible
        for F, Hcol in ((a, b), (b, a)):
            key = (r0, r1, c0, c1, F, Hcol)
            if key in tried:
                continue
            tried.add(key)
            res = try_candidate(r0, r1, c0, c1, {a, b}, F, Hcol)
            if res is not None:
                return [[int(x) for x in row] for row in res]

    # Fallback: return unchanged grid (should not happen for valid ARC inputs)
    return [list(map(int, row)) for row in grid]

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0]) if h else 0

    # Step 1: keep only 1-cells that have at least two orthogonal 1-neighbours.
    clean = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            cnt = 0
            if r > 0 and grid[r - 1][c] == 1:
                cnt += 1
            if r + 1 < h and grid[r + 1][c] == 1:
                cnt += 1
            if c > 0 and grid[r][c - 1] == 1:
                cnt += 1
            if c + 1 < w and grid[r][c + 1] == 1:
                cnt += 1
            if cnt >= 2:
                clean[r][c] = 1

    # Step 2: find 0-cells that have 1-neighbours in at least two cardinal directions.
    out = [row[:] for row in clean]
    for r in range(h):
        for c in range(w):
            if clean[r][c] != 0:
                continue

            dirs = 0
            if r > 0 and clean[r - 1][c] == 1:
                dirs += 1
            if r + 1 < h and clean[r + 1][c] == 1:
                dirs += 1
            if c > 0 and clean[r][c - 1] == 1:
                dirs += 1
            if c + 1 < w and clean[r][c + 1] == 1:
                dirs += 1

            if dirs >= 2:
                # Step 3: paint the 8-neighbourhood of this special 0-cell with 7.
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr = r + dr
                        nc = c + dc
                        if 0 <= nr < h and 0 <= nc < w and (dr != 0 or dc != 0):
                            out[nr][nc] = 7

    return out

import numpy as np

def _connected_components(mask):
    h, w = mask.shape
    labels = np.zeros((h, w), dtype=int)
    comps = []
    lab = 0
    for r in range(h):
        for c in range(w):
            if mask[r, c] and labels[r, c] == 0:
                lab += 1
                q = [(r, c)]
                labels[r, c] = lab
                cells = []
                while q:
                    y, x = q.pop()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w:
                            if mask[ny, nx] and labels[ny, nx] == 0:
                                labels[ny, nx] = lab
                                q.append((ny, nx))
                comps.append(cells)
    return comps

def _component_shape(cells):
    if not cells:
        return None
    ys = [r for r, c in cells]
    xs = [c for r, c in cells]
    y0, y1 = min(ys), max(ys)
    x0, x1 = min(xs), max(xs)
    rel = frozenset((r - y0, c - x0) for r, c in cells)
    return (y1 - y0 + 1, x1 - x0 + 1, rel)

def _components_by_shape(cells_list):
    d = {}
    for cells in cells_list:
        shp = _component_shape(cells)
        if shp is None:
            continue
        d.setdefault(shp, []).append(cells)
    return d

def _fill_component(target, tcells, src_cells):
    # Fill the selected target cells with the source component cells,
    # ordered by their relative bounding-box coordinates.
    ys = [r for r, c in src_cells]
    xs = [c for r, c in src_cells]
    y0, x0 = min(ys), min(xs)
    order = sorted(src_cells, key=lambda rc: (rc[0] - y0, rc[1] - x0))
    t_order = sorted(tcells, key=lambda rc: (rc[0] - y0, rc[1] - x0))
    # In practice both cells sets have the same shape, so len is equal.
    for tc, sc in zip(t_order, order):
        target[tc] = sc

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape

    # Find a straight cut into two panels.
    # A valid cut line is a full row/col whose color is the background color
    # of one panel and empty color of the other.
    best = None

    # Try horizontal cuts: top/bottom panels.
    for r in range(h - 1):
        if len(np.unique(a[r])) == 1 and len(np.unique(a[r + 1])) == 1:
            top = a[:r + 1, :]
            bot = a[r + 2:, :] if r + 2 < h else a[r + 1:, :]
            # The separator is row r or r+1; try both adjacent splits.
            for sep in (r, r + 1):
                if sep == 0 or sep == h - 1:
                    continue
                top = a[:sep, :]
                bot = a[sep + 1:, :]
                if top.size == 0 or bot.size == 0:
                    continue
                # candidate target/source pairs
                for target, source in ((top, bot), (bot, top)):
                    # determine shared empty/background color:
                    # the most frequent color in source that also appears in target
                    vals, counts = np.unique(source, return_counts=True)
                    shared = None
                    for v, cnt in zip(vals, counts):
                        if np.any(target == v):
                            shared = int(v)
                            break
                    if shared is None:
                        continue
                    tmask = (target == shared)
                    smask = (source != shared)
                    if tmask.sum() == smask.sum() and tmask.sum() > 0:
                        tcomps = _connected_components(tmask)
                        scomps = _connected_components(smask)
                        # Check whether source components can be matched by shape
                        # to disjoint groups of target cells.
                        # For these puzzles, a simple global shape multiset match
                        # works; otherwise use row-major fallback later.
                        shape_ok = True
                        tshapes = _components_by_shape(tcomps)
                        sshapes = _components_by_shape(scomps)
                        if len(tcomps) == len(scomps):
                            for shp, slist in sshapes.items():
                                if len(tshapes.get(shp, [])) < len(slist):
                                    shape_ok = False
                                    break
                        # Prefer valid shape matches.
                        if shape_ok:
                            score = 1000000 + tmask.sum()
                        else:
                            score = tmask.sum()
                        if best is None or score > best[0]:
                            best = (score, "h", sep, target.copy(), source.copy(), shared)
                break
    # Try vertical cuts.
    for c in range(w - 1):
        if len(np.unique(a[:, c])) == 1 and len(np.unique(a[:, c + 1])) == 1:
            for sep in (c, c + 1):
                if sep == 0 or sep == w - 1:
                    continue
                left = a[:, :sep]
                right = a[:, sep + 1:]
                if left.size == 0 or right.size == 0:
                    continue
                for target, source in ((left, right), (right, left)):
                    vals, counts = np.unique(source, return_counts=True)
                    shared = None
                    for v, cnt in zip(vals, counts):
                        if np.any(target == v):
                            shared = int(v)
                            break
                    if shared is None:
                        continue
                    tmask = (target == shared)
                    smask = (source != shared)
                    if tmask.sum() == smask.sum() and tmask.sum() > 0:
                        tcomps = _connected_components(tmask)
                        scomps = _connected_components(smask)
                        shape_ok = True
                        if len(tcomps) == len(scomps):
                            tshapes = _components_by_shape(tcomps)
                            sshapes = _components_by_shape(scomps)
                            for shp, slist in sshapes.items():
                                if len(tshapes.get(shp, [])) < len(slist):
                                    shape_ok = False
                                    break
                        if shape_ok:
                            score = 1000000 + tmask.sum()
                        else:
                            score = tmask.sum()
                        if best is None or score > best[0]:
                            best = (score, "v", sep, target.copy(), source.copy(), shared)
                break

    if best is None:
        # Robust fallback: choose the smaller panel as target, the other as source,
        # and use the most common shared color.
        if h >= w:
            mid = h // 2
            target = a[:mid, :]
            source = a[mid:, :]
        else:
            mid = w // 2
            target = a[:, :mid]
            source = a[:, mid:]
        vals, counts = np.unique(source, return_counts=True)
        shared = None
        for v, cnt in zip(vals, counts):
            if np.any(target == v):
                shared = int(v)
                break
        if shared is None:
            shared = int(np.unique(target)[0])

        score, _, _, target, source, shared = best = (0, None, None, target.copy(), source.copy(), shared)

    _, _, _, target, source, shared = best

    # Exact matching by connected component shape when possible.
    tmask = (target == shared)
    smask = (source != shared)

    tcomps = _connected_components(tmask)
    scomps = _connected_components(smask)

    out = target.copy()
    used_target_cells = np.zeros(tmask.shape, dtype=bool)
    used_source = np.zeros(smask.shape, dtype=bool)

    # Build source shape buckets.
    src_buckets = {}
    for cells in scomps:
        shp = _component_shape(cells)
        src_buckets.setdefault(shp, []).append(cells)

    # First pass: exact shape matches, largest first.
    for tcells in sorted(tcomps, key=lambda cs: -len(cs)):
        shp = _component_shape(tcells)
        if shp in src_buckets:
            # choose a source component of same size not used
            cand = None
            for scells in src_buckets[shp]:
                if not any(used_source[r, c] for r, c in scells):
                    cand = scells
                    break
            if cand is not None:
                # choose target cells: if this target component is unused, use all;
                # if partially used, skip here (handled by fallback)
                if not any(used_target_cells[r, c] for r, c in tcells):
                    _fill_component(out, tcells, cand)
                    for r, c in tcells:
                        used_target_cells[r, c] = True
                    for r, c in cand:
                        used_source[r, c] = True

    # Fallback: fill any remaining target empty cells with remaining source cells
    # in row-major order.  This preserves total counts and handles merged holes.
    remaining_t = []
    for r in range(tmask.shape[0]):
        for c in range(tmask.shape[1]):
            if tmask[r, c] and not used_target_cells[r, c]:
                remaining_t.append((r, c))
    remaining_s = []
    for r in range(smask.shape[0]):
        for c in range(smask.shape[1]):
            if smask[r, c] and not used_source[r, c]:
                remaining_s.append((r, c))

    # For the remaining cells, try to preserve component shapes by scanning
    # both in row-major but grouped by connected components of the remaining sets.
    rem_t_mask = np.zeros(tmask.shape, dtype=bool)
    for r, c in remaining_t:
        rem_t_mask[r, c] = True
    rem_s_mask = np.zeros(smask.shape, dtype=bool)
    for r, c in remaining_s:
        rem_s_mask[r, c] = True

    rem_t_comps = _connected_components(rem_t_mask)
    rem_s_comps = _connected_components(rem_s_mask)

    rem_s_buckets = {}
    for cells in rem_s_comps:
        shp = _component_shape(cells)
        rem_s_buckets.setdefault(shp, []).append(cells)

    for tcells in sorted(rem_t_comps, key=lambda cs: -len(cs)):
        shp = _component_shape(tcells)
        # Try exact remaining shape match.
        cand = None
        if shp in rem_s_buckets:
            for scells in rem_s_buckets[shp]:
                cand = scells
                break
        if cand is not None:
            # Use only the needed number of cells if sizes differ slightly.
            if len(cand) >= len(tcells):
                _fill_component(out, tcells, cand[:len(tcells)])
                for r, c in tcells:
                    used_target_cells[r, c] = True
                for r, c in cand[:len(tcells)]:
                    used_source[r, c] = True
            # If sizes do not match, fall through to global fill below.
        # else global fill below

    # Final global row-major fill for anything still unfilled.
    remaining_t = []
    for r in range(tmask.shape[0]):
        for c in range(tmask.shape[1]):
            if tmask[r, c] and not used_target_cells[r, c]:
                remaining_t.append((r, c))
    remaining_s = []
    for r in range(smask.shape[0]):
        for c in range(smask.shape[1]):
            if smask[r, c] and not used_source[r, c]:
                remaining_s.append((r, c))

    for tc, sc in zip(remaining_t, remaining_s):
        out[tc] = source[sc]
        used_target_cells[tc] = True
        used_source[sc] = True

    return out.astype(int).tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import deque

    g = np.asarray(grid, dtype=int)
    h, w = g.shape

    def neighbors8(y, x):
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w:
                    yield ny, nx

    # Small 0-components (size <= 3) become "targets": their 8-neighbours get 7.
    target0 = np.zeros((h, w), dtype=bool)
    seen = np.zeros((h, w), dtype=bool)

    for y in range(h):
        for x in range(w):
            if g[y, x] == 0 and not seen[y, x]:
                comp = [(y, x)]
                q = deque([(y, x)])
                seen[y, x] = True
                while q:
                    cy, cx = q.popleft()
                    for ny, nx in neighbors8(cy, cx):
                        if not seen[ny, nx] and g[ny, nx] == 0:
                            seen[ny, nx] = True
                            comp.append((ny, nx))
                            q.append((ny, nx))
                if len(comp) <= 3:
                    for cy, cx in comp:
                        target0[cy, cx] = True

    # Small 1-components (size <= 3) are removed.
    remove1 = np.zeros((h, w), dtype=bool)
    seen = np.zeros((h, w), dtype=bool)

    for y in range(h):
        for x in range(w):
            if g[y, x] == 1 and not seen[y, x]:
                comp = [(y, x)]
                q = deque([(y, x)])
                seen[y, x] = True
                while q:
                    cy, cx = q.popleft()
                    for ny, nx in neighbors8(cy, cx):
                        if not seen[ny, nx] and g[ny, nx] == 1:
                            seen[ny, nx] = True
                            comp.append((ny, nx))
                            q.append((ny, nx))
                if len(comp) <= 3:
                    for cy, cx in comp:
                        remove1[cy, cx] = True

    out = g.copy()

    # Remove small 1-components.
    out[remove1] = 0

    # Draw 7 rings around selected 0 cells, preserving the selected 0 cells.
    paint7 = np.zeros((h, w), dtype=bool)
    for y in range(h):
        for x in range(w):
            if target0[y, x]:
                for ny, nx in neighbors8(y, x):
                    paint7[ny, nx] = True

    paint7 &= ~target0
    out[paint7] = 7

    return out.astype(int).tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    from collections import deque
    import numpy as np

    g = np.asarray(grid, dtype=int)
    H, W = g.shape

    # A cell is "solid" for a colour if it belongs to at least one 2x2 block
    # of that same colour.
    solid = np.zeros((H, W), dtype=bool)
    for y in range(H - 1):
        for x in range(W - 1):
            c = g[y, x]
            if (g[y, x] == c and g[y, x + 1] == c and
                    g[y + 1, x] == c and g[y + 1, x + 1] == c):
                solid[y, x] = True
                solid[y, x + 1] = True
                solid[y + 1, x] = True
                solid[y + 1, x + 1] = True

    out = g.copy()

    # Remove 1-cells that are not solid.
    out[(g == 1) & (~solid)] = 0

    # Find small connected groups of non-solid 0-cells (4-connected, size <= 3).
    # For each such group, paint its 8-neighbourhood with 7, except the group cells.
    target0 = np.zeros((H, W), dtype=bool)
    visited = np.zeros((H, W), dtype=bool)
    nonsolid_zero = (g == 0) & (~solid)

    for y in range(H):
        for x in range(W):
            if nonsolid_zero[y, x] and not visited[y, x]:
                comp = [(y, x)]
                q = deque([(y, x)])
                visited[y, x] = True
                while q:
                    cy, cx = q.popleft()
                    for ny, nx in ((cy - 1, cx), (cy + 1, cx),
                                   (cy, cx - 1), (cy, cx + 1)):
                        if 0 <= ny < H and 0 <= nx < W:
                            if nonsolid_zero[ny, nx] and not visited[ny, nx]:
                                visited[ny, nx] = True
                                comp.append((ny, nx))
                                q.append((ny, nx))
                if len(comp) <= 3:
                    for cy, cx in comp:
                        target0[cy, cx] = True

    # Paint 7 around selected 0-groups.
    for y in range(H):
        for x in range(W):
            if target0[y, x]:
                for ny in range(max(0, y - 1), min(H, y + 2)):
                    for nx in range(max(0, x - 1), min(W, x + 2)):
                        if not target0[ny, nx]:
                            out[ny, nx] = 7

    return out.astype(int).tolist()

import numpy as np
from typing import List

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return grid
    g = np.array(grid, dtype=int)
    H, W = g.shape
    bg = int(g[0][0])
    S = 5  # square size

    # Detect all bordered SxS squares
    objs = []
    for r in range(H - S + 1):
        for c in range(W - S + 1):
            b = int(g[r][c])
            if b == bg:
                continue
            # Check all four borders
            if (np.all(g[r, c:c+S] == b) and
                np.all(g[r+S-1, c:c+S] == b) and
                np.all(g[r:r+S, c] == b) and
                np.all(g[r:r+S, c+S-1] == b)):
                inner_region = g[r+1:r+S-1, c+1:c+S-1]
                if not np.any(inner_region == b):
                    inner = int(np.bincount(inner_region.flatten()).argmax())
                    objs.append((r, c, b, inner))

    # Group by border color: 8 moves left, 2 moves right
    groups = {8: [], 2: []}
    for r, c, b, inner in objs:
        if b in groups:
            groups[b].append((r, c, inner))

    placed = {}  # border -> list of (r, c)

    for border, direction in [(8, -1), (2, 1)]:
        squares = groups[border]
        if not squares:
            continue
        edge = 0 if direction == -1 else W - S
        # Sort by distance to target edge (closest first), then by row
        squares.sort(key=lambda s: (abs(s[1] - edge), s[0]))
        placed[border] = []
        for r, c, inner in squares:
            pos = edge
            while True:
                # Check validity
                valid = True
                for dr in range(S):
                    for dc in range(S):
                        nr, nc = r + dr, pos + dc
                        if nr < 0 or nr >= H or nc < 0 or nc >= W:
                            valid = False
                            break
                        if g[nr][nc] != bg:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    for pr, pc in placed[border]:
                        # Check overlap with already placed squares
                        for dr in range(S):
                            for dc in range(S):
                                nr, nc = r + dr, pos + dc
                                if pr <= nr < pr + S and pc <= nc < pc + S:
                                    valid = False
                                    break
                            if not valid:
                                break
                        if not valid:
                            break
                if valid:
                    break
                pos += direction
            if pos < 0 or pos >= W - S + 1:
                continue  # couldn't place, skip
            placed[border].append((r, pos))

    # Build output
    out = np.full((H, W), bg, dtype=int)
    for border in [8, 2]:
        for (r, c) in placed.get(border, []):
            # Find inner color
            inner = 0
            for (rr, cc, ii) in groups[border]:
                if rr == r and cc == c:
                    inner = ii
                    break
            # Draw square
            out[r, c:c+S] = border
            out[r+S-1, c:c+S] = border
            out[r:r+S, c] = border
            out[r:r+S, c+S-1] = border
            out[r+1:r+S-1, c+1:c+S-1] = inner

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Determine the non-background colour.
    vals, counts = np.unique(g, return_counts=True)
    if len(vals) <= 1:
        return g.tolist()

    background = int(vals[np.argmax(counts)])
    foreground = [int(v) for v in vals if v != background]

    def fill_runs(mask, axis, min_run=2, gap_max=3):
        """
        For a binary mask, merge runs of length at least `min_run` in the
        given axis if they are separated by gaps of length at most `gap_max`.
        """
        filled = mask.copy()
        if not np.any(filled):
            return filled

        if axis == 0:  # columns
            for c in range(w):
                col = filled[:, c]
                in_run = False
                start = 0
                prev_end = None
                runs = []

                for r in range(h + 1):
                    cur = r < h and col[r]
                    if cur and not in_run:
                        in_run = True
                        start = r
                    elif not cur and in_run:
                        in_run = False
                        length = r - start
                        if length >= min_run:
                            runs.append((start, r - 1))
                            if prev_end is not None:
                                gap = start - prev_end - 1
                                if 0 < gap <= gap_max:
                                    filled[prev_end + 1:start, c] = True
                            prev_end = r - 1

        else:  # rows
            for r in range(h):
                row = filled[r, :]
                in_run = False
                start = 0
                prev_end = None
                runs = []

                for c in range(w + 1):
                    cur = c < w and row[c]
                    if cur and not in_run:
                        in_run = True
                        start = c
                    elif not cur and in_run:
                        in_run = False
                        length = c - start
                        if length >= min_run:
                            runs.append((start, c - 1))
                            if prev_end is not None:
                                gap = start - prev_end - 1
                                if 0 < gap <= gap_max:
                                    filled[r, prev_end + 1:start] = True
                            prev_end = c - 1

        return filled

    def keep_long_runs(mask, min_run=2):
        """
        Keep only pixels that belong to a horizontal or vertical run
        of length at least `min_run`.
        """
        if not np.any(mask):
            return mask

        keep = np.zeros_like(mask)

        # Vertical runs
        for c in range(w):
            col = mask[:, c]
            in_run = False
            start = 0
            for r in range(h + 1):
                cur = r < h and col[r]
                if cur and not in_run:
                    in_run = True
                    start = r
                elif not cur and in_run:
                    in_run = False
                    if r - start >= min_run:
                        keep[start:r, c] = True

        # Horizontal runs
        for r in range(h):
            row = mask[r, :]
            in_run = False
            start = 0
            for c in range(w + 1):
                cur = c < w and row[c]
                if cur and not in_run:
                    in_run = True
                    start = c
                elif not cur and in_run:
                    in_run = False
                    if c - start >= min_run:
                        keep[r, start:c] = True

        return keep

    for fg in foreground:
        mask = (g == fg)

        # Iteratively complete nearby horizontal and vertical runs.
        for _ in range(4):
            new = fill_runs(mask, axis=1, min_run=2, gap_max=3)
            new = fill_runs(new, axis=0, min_run=2, gap_max=3)
            if np.array_equal(new, mask):
                mask = new
                break
            mask = new

        # Remove isolated/diagonal pixels that are not on a straight line.
        mask = keep_long_runs(mask, min_run=2)
        g = np.where(mask, fg, g)

    # Ensure background cells remain background where not explicitly recoloured.
    return g.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape
    if H == 0 or W == 0:
        return g.tolist()

    vals, counts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(counts)])
    colors = [int(v) for v in vals if v != bg]

    # Fill axis-aligned gaps of length at most 3 if the gap is supported by
    # nearby pixels in the orthogonal direction (within 2 cells).
    for color in colors:
        mask = (g == color)
        for _ in range(4):
            old = mask.copy()

            # Fill horizontal gaps.
            for r in range(H):
                c = 0
                while c < W:
                    if not mask[r, c]:
                        c += 1
                        continue

                    start = c
                    while c < W and mask[r, c]:
                        c += 1
                    end = c - 1

                    if c < W:
                        gap = c - end - 1
                        if 1 <= gap <= 3:
                            r0, r1 = max(0, r - 2), min(H - 1, r + 2)
                            supp = mask[r0:r1 + 1, end + 1:c].any()
                            if supp:
                                mask[r, end + 1:c] = True
                                c = end + 1
                                continue

            # Fill vertical gaps.
            for c in range(W):
                r = 0
                while r < H:
                    if not mask[r, c]:
                        r += 1
                        continue

                    start = r
                    while r < H and mask[r, c]:
                        r += 1
                    end = r - 1

                    if r < H:
                        gap = r - end - 1
                        if 1 <= gap <= 3:
                            c0, c1 = max(0, c - 2), min(W - 1, c + 2)
                            supp = mask[end + 1:r, c0:c1 + 1].any()
                            if supp:
                                mask[end + 1:r, c] = True
                                r = end + 1
                                continue

            if np.array_equal(old, mask):
                break
        g = np.where(mask, color, g)

    out = np.zeros((H, W), dtype=int)

    for color in colors:
        mask = (g == color)

        # Keep complete horizontal runs of length at least 3.
        keep = np.zeros_like(mask)
        for r in range(H):
            c = 0
            while c < W:
                if not mask[r, c]:
                    c += 1
                    continue
                start = c
                while c < W and mask[r, c]:
                    c += 1
                end = c - 1
                if end - start + 1 >= 3:
                    keep[r, start:end + 1] = True

        # Also keep any cell in a column that contains at least three pixels.
        col_counts = mask.sum(axis=0)
        good_cols = np.where(col_counts >= 3)[0]
        if len(good_cols):
            keep[:, good_cols] = mask[:, good_cols]

        out = np.where(keep, color, out)

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Background is the most frequent colour.
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    out = [[bg] * W for _ in range(H)]

    def shape_cells(top, center):
        return [
            (top, center - 1),
            (top, center),
            (top, center + 1),
            (top + 1, center - 2),
            (top + 1, center - 1),
            (top + 1, center),
            (top + 1, center + 1),
            (top + 1, center + 2),
            (top + 2, center - 1),
            (top + 2, center),
            (top + 2, center + 1),
        ]

    def is_shape(top, center, color):
        if color == bg:
            return False
        cells = shape_cells(top, center)
        if any(0 > r or r >= H or 0 > c or c >= W for r, c in cells):
            return False

        req = set(cells)
        for r, c in cells:
            if grid[r][c] != color:
                return False

        # The exact 3x5 bounding box must contain only this shape.
        for dr in range(3):
            for dc in range(-2, 3):
                r, c = top + dr, center + dc
                v = grid[r][c]
                if v != bg and ((r, c) not in req or v != color):
                    return False
        return True

    # Detect all full 3x5 "diamond" objects.
    objects = []  # (top_row, center_col, colour)
    object_cells = set()
    for r in range(max(0, H - 3)):          # do not use the bottom instruction row
        for c in range(2, W - 2):
            col = grid[r][c]
            if col == bg:
                continue
            if is_shape(r, c, col):
                objects.append((r, c, col))
                for cell in shape_cells(r, c):
                    object_cells.add(cell)

    # Detect bottom-row instruction bars.
    markers = {}       # centre_col -> colour
    marker_cells = set()
    r = H - 1
    c = 0
    while c < W:
        if grid[r][c] != bg:
            start = c
            col = grid[r][c]
            while c < W and grid[r][c] == col:
                c += 1
            end = c - 1
            length = end - start + 1
            if length == 5 and col in (2, 3):
                center = start + 2
                markers[center] = col
                for cc in range(start, end + 1):
                    marker_cells.add((r, cc))
        else:
            c += 1

    source_centers = {c for c, v in markers.items() if v == 2}
    target_centers = {c for c, v in markers.items() if v == 3}

    by_center = {}
    for top, center, col in objects:
        by_center.setdefault(center, []).append((top, col))

    # Number of generated copies = number of objects in all source lanes.
    copy_count = sum(len(by_center.get(c, [])) for c in source_centers)

    # Place all original objects; source lanes become colour 5.
    for top, center, col in objects:
        out_col = 5 if center in source_centers else col
        for rr, cc in shape_cells(top, center):
            out[rr][cc] = out_col

    # Extend each target lane upward by `copy_count` copies, spacing 4 rows.
    for tc in target_centers:
        lane = by_center.get(tc)
        if not lane:
            continue

        lane.sort(key=lambda x: x[0])
        topmost, target_col = lane[0]

        added = 0
        k = 1
        while added < copy_count:
            new_top = topmost - 4 * k
            if new_top < 0:
                break
            for rr, cc in shape_cells(new_top, tc):
                out[rr][cc] = target_col
            added += 1
            k += 1

    # Preserve any non-background cells that were not part of a detected
    # object or a bottom instruction bar.
    ignored = object_cells | marker_cells
    for r in range(H):
        for c in range(W):
            if (r, c) not in ignored and grid[r][c] != bg:
                out[r][c] = grid[r][c]

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    # Identify the separator color.  In all given cases it is 6, but we
    # detect it rather than assuming it blindly.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1

    background = max(counts, key=lambda c: counts[c])

    def full_lines_of(color: int):
        rows = [
            i for i in range(H)
            if all(grid[i][j] == color for j in range(W))
        ]
        cols = [
            j for j in range(W)
            if all(grid[i][j] == color for i in range(H))
        ]
        return rows, cols

    # Prefer 6 when it clearly forms separator lines.
    sep_rows, sep_cols = full_lines_of(6)
    if sep_rows or sep_cols:
        sep_color = 6
    else:
        sep_color = None
        best = 0
        for color in counts:
            if color == background:
                continue
            rows, cols = full_lines_of(color)
            score = len(rows) + len(cols)
            if score > best:
                best = score
                sep_color = color
                sep_rows = rows
                sep_cols = cols

    # No separators: nothing to rearrange.
    if sep_color is None:
        return [row[:] for row in grid]

    def intervals(lines, length):
        lines = sorted(lines)
        res = []
        start = 0
        for line in lines:
            if line > start:
                res.append((start, line - 1))
            start = line + 1
        if start < length:
            res.append((start, length - 1))
        return res

    row_blocks = intervals(sep_rows, H)
    col_blocks = intervals(sep_cols, W)

    if not row_blocks or not col_blocks:
        return [row[:] for row in grid]

    panels = {}
    panel_width = None

    for ri, (r0, r1) in enumerate(row_blocks):
        for ci, (c0, c1) in enumerate(col_blocks):
            panel = [
                [int(grid[r][c]) for c in range(c0, c1 + 1)]
                for r in range(r0, r1 + 1)
            ]
            panels[(ri, ci)] = panel
            if panel_width is None:
                panel_width = len(panel[0]) if panel else 0

    # Panel ordering:
    # - 1D rows: left-to-right
    # - 1D columns: top-to-bottom
    # - 2x2 (and general square-like cases): panels on the main diagonal first,
    #   then the next diagonal, etc.
    order = sorted(
        ((ri, ci) for ri in range(len(row_blocks)) for ci in range(len(col_blocks))),
        key=lambda rc: (abs(rc[0] - rc[1]), rc[0], rc[1])
    )

    out = []
    for idx, key in enumerate(order):
        if idx > 0:
            out.append([sep_color] * panel_width)
        for row in panels[key]:
            out.append(row)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h, w = len(grid), len(grid[0])

    # Find the vertical 5 line.
    five_counts = [sum(1 for r in range(h) if grid[r][c] == 5) for c in range(w)]
    if max(five_counts) == 0:
        return [row[:] for row in grid]
    five_col = max(range(w), key=lambda c: five_counts[c])
    target_col = five_col - 1

    # Output starts as the background colour, preserving all 5s.
    out = [[6] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                out[r][c] = 5

    marked_rows = set()

    if target_col >= 0:
        visited = [[False] * w for _ in range(h)]

        # Work on each connected component of 0s to the left of the 5 line.
        for sr in range(h):
            for sc in range(target_col + 1):
                if grid[sr][sc] != 0 or visited[sr][sc]:
                    continue

                # BFS over 4-connected 0 pixels.
                stack = [(sr, sc)]
                visited[sr][sc] = True
                cells = []
                min_row, max_row = h, -1
                min_col, max_col = w, -1

                while stack:
                    r, c = stack.pop()
                    cells.append((r, c))
                    min_row = min(min_row, r)
                    max_row = max(max_row, r)
                    min_col = min(min_col, c)
                    max_col = max(max_col, c)

                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc <= target_col:
                            if not visited[nr][nc] and grid[nr][nc] == 0:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                # Shift the whole component right until its right edge touches 5.
                shift = target_col - max_col
                for r, c in cells:
                    out[r][c + shift] = 0

                # Mark rows that have 0s at both outer columns of the component
                # and have at least one non-0 gap between them.
                cell_set = set(cells)
                band_width = max_col - min_col + 1
                for r in range(min_row, max_row + 1):
                    if (r, min_col) not in cell_set or (r, max_col) not in cell_set:
                        continue
                    if any(grid[r][c] != 0 for c in range(min_col, max_col)):
                        marked_rows.add(r)

    # Fill the area to the right of the 5 line with 2 in marked rows.
    for r in marked_rows:
        for c in range(five_col + 1, w):
            if out[r][c] != 5:
                out[r][c] = 2

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    h, w = len(grid), len(grid[0])

    # Find the vertical line of 5s.
    five_counts = [0] * w
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 5:
                five_counts[c] += 1

    if max(five_counts) == 0:
        return [row[:] for row in grid]

    five_col = max(range(w), key=lambda c: five_counts[c])
    target_col = five_col - 1

    # Background is the most frequent non-zero, non-5 colour (normally 6).
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0 and v != 5:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get) if counts else 6

    # Start from the input, then clear zero pixels to the left of the 5 line.
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(five_col):
            if out[r][c] == 0:
                out[r][c] = bg

    # Move each connected component of 0s (4-connected) right until its
    # rightmost column touches the column just left of the 5 line.
    visited = [[False] * w for _ in range(h)]
    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for sr in range(h):
        for sc in range(five_col):
            if grid[sr][sc] != 0 or visited[sr][sc]:
                continue

            stack = [(sr, sc)]
            visited[sr][sc] = True
            cells = []
            max_col = -1

            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                max_col = max(max_col, c)

                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if (
                        0 <= nr < h
                        and 0 <= nc < five_col
                        and not visited[nr][nc]
                        and grid[nr][nc] == 0
                    ):
                        visited[nr][nc] = True
                        stack.append((nr, nc))

            shift = max(0, target_col - max_col)
            for r, c in cells:
                out[r][c + shift] = 0

    # For rows where the shifted 0-shape has a right-edge cavity,
    # paint the area to the right of the 5 line with 2s.
    if target_col >= 1:
        for r in range(h):
            if out[r][target_col] == 0 and out[r][target_col - 1] != 0:
                for c in range(five_col + 1, w):
                    if out[r][c] == bg:
                        out[r][c] = 2

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    H = len(grid)
    W = len(grid[0])
    SEP = 6

    # Full rows/columns made of the separator colour 6.
    row_is_sep = [all(grid[r][c] == SEP for c in range(W)) for r in range(H)]
    col_is_sep = [all(grid[r][c] == SEP for r in range(H)) for c in range(W)]

    def make_strips(flags, n):
        """Group consecutive same flags into (start, end, length, is_sep)."""
        strips = []
        i = 0
        while i < n:
            j = i
            while j < n and flags[j] == flags[i]:
                j += 1
            strips.append((i, j - 1, j - i, flags[i]))
            i = j
        return strips

    row_strips = make_strips(row_is_sep, H)
    col_strips = make_strips(col_is_sep, W)

    # If there are no separator lines, nothing changes.
    if not any(s[3] for s in row_strips) and not any(s[3] for s in col_strips):
        return [row[:] for row in grid]

    row_content = [s for s in row_strips if not s[3]]
    col_content = [s for s in col_strips if not s[3]]

    R = len(row_content)
    C = len(col_content)

    # Degenerate case: no actual blocks.
    if R == 0 or C == 0:
        return [row[:] for row in grid]

    # Extract the blocks.
    blocks = []
    for r0, r1, _, _ in row_content:
        row_blocks = []
        for c0, c1, _, _ in col_content:
            row_blocks.append([grid[r][c0:c1 + 1] for r in range(r0, r1 + 1)])
        blocks.append(row_blocks)

    # Rotate the block matrix 90 degrees clockwise, keeping blocks themselves fixed.
    new_blocks = [[None] * R for _ in range(C)]
    for i in range(R):
        for j in range(C):
            new_blocks[j][R - 1 - i] = blocks[i][j]

    # The whole layout is transposed in size.
    out_H = W
    out_W = H
    out = [[0] * out_W for _ in range(out_H)]

    def fill_separator_strips(strips, reverse, fill_rows):
        pos = 0
        indices = range(len(strips) - 1, -1, -1) if reverse else range(len(strips))
        for idx in indices:
            _, _, length, is_sep = strips[idx]
            if is_sep:
                if fill_rows:
                    for r in range(pos, pos + length):
                        if 0 <= r < out_H:
                            for c in range(out_W):
                                out[r][c] = SEP
                else:
                    for c in range(pos, pos + length):
                        if 0 <= c < out_W:
                            for r in range(out_H):
                                out[r][c] = SEP
            pos += length

    # Old vertical separator strips become output horizontal separator strips.
    fill_separator_strips(col_strips, reverse=False, fill_rows=True)

    # Old horizontal separator strips become output vertical separator strips, reversed.
    fill_separator_strips(row_strips, reverse=True, fill_rows=False)

    def content_offsets(strips, reverse):
        """
        Return, in output order, (original_content_index, offset, strip_length)
        for content strips only.
        """
        content_index = [None] * len(strips)
        idx = 0
        for i, s in enumerate(strips):
            if not s[3]:
                content_index[i] = idx
                idx += 1

        res = []
        pos = 0
        indices = range(len(strips) - 1, -1, -1) if reverse else range(len(strips))
        for i in indices:
            s = strips[i]
            if not s[3]:
                res.append((content_index[i], pos, s[2]))
            pos += s[2]
        return res

    out_rows = content_offsets(col_strips, reverse=False)  # output row order
    out_cols = content_offsets(row_strips, reverse=True)   # output column order

    # Place the unrotated blocks into their new positions.
    for i in range(C):
        if i >= len(out_rows):
            break
        _, row_off, cell_h = out_rows[i]
        for j in range(R):
            if j >= len(out_cols):
                break
            _, col_off, cell_w = out_cols[j]

            block = new_blocks[i][j]
            if not block:
                continue

            bh = len(block)
            bw = len(block[0]) if block else 0

            # Normal cases have exact-fit square blocks; this keeps the code safe.
            max_r = min(bh, cell_h)
            max_c = min(bw, cell_w)

            for r in range(max_r):
                rr = row_off + r
                if rr < 0 or rr >= out_H:
                    continue
                for c in range(max_c):
                    cc = col_off + c
                    if 0 <= cc < out_W:
                        out[rr][cc] = block[r][c]

    return out

