    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Background is the colour that appears in the border.
    border = [g[0, :], g[-1, :], g[:, 0], g[:, -1]]
    border = np.concatenate([border.reshape(-1) for b in border])
    bg, _ = np.unique(border, return_inverse=False)
    bg = int(bg[0])

    ans = g.copy()

    # Work on both diagonal orientations.
    for sign in (1, -1):
        s_vals, d_vals = [], []

        for r in range(h):
            for c in range(w):
                if g[r, c] != bg:
                    s = r + c
                    d = r - sign * c
                    if s not in s_vals:
                        s_vals.append(s)
                    if d not in d_vals:
                        d_vals.append(d)

        s_vals.sort()
        d_vals.sort()

        # Fill every diagonal-grid cell whose (s, d) coordinates lie strictly
        # between two existing diagonal line values in both orientations.
        for i in range(len(s_vals) - 1):
            s_lo, s_hi = s_vals[i], s_vals[i + 1]
            for j in range(len(d_vals) - 1):
                d_lo, d_hi = d_vals[j], d_vals[j + 1]

                for s in range(s_lo + 1, s_hi):
                    for d in range(d_lo + 1, d_hi):
                        if (s - d) % 2 != 0:
                            continue
                        r = (s + d) // 2
                        c = (s - d) // 2 if sign == 1 else (s + d) // 2
                        if 0 <= r < h and 0 <= c < w and ans[r, c] == bg:
                            ans[r, c] = 2

    return ans.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Background is the border color.
    border = np.concatenate([g[0, :].ravel(), g[-1, :].ravel(),
                             g[:, 0].ravel(), g[:, -1].ravel()])
    bg = int(np.unique(border)[0])

    fg = g != bg
    if not fg.any():
        return out.tolist()

    def add_fill(u1, u2, v1, v2):
        """Fill all empty cells strictly between two diagonal lines.
        u = r + c, v = r - c.
        """
        if abs(u1 - u2) <= 1:
            return
        lo_u, hi_u = min(u1, u2) + 1, max(u1, u2) - 1
        lo_v, hi_v = min(v1, v2), max(v1, v2)

        for u in range(lo_u, hi_u + 1):
            for v in range(lo_v, hi_v + 1):
                if (u - v) % 2 != 0:
                    continue
                r = (u + v) // 2
                c = (u - v) // 2
                if 0 <= r < h and 0 <= c < w and out[r, c] == bg:
                    out[r, c] = 2

    def process_lines(coordinate, other):
        # coordinate: 'u' (anti-diagonal) or 'v' (main diagonal)
        lines = {}

        for r in range(h):
            for c in range(w):
                if not fg[r, c]:
                    continue
                u = r + c
                v = r - c
                key = u if coordinate == 'u' else v
                val = v if coordinate == 'u' else u
                lines.setdefault(key, []).append(val)

        # Split each diagonal into contiguous segments.
        segments = []
        for key, vals in lines.items():
            vals = sorted(set(vals))
            start = prev = vals[0]
            for x in vals[1:]:
                if x == prev + 2:
                    prev = x
                else:
                    segments.append((key, start, prev))
                    start = prev = x
            segments.append((key, start, prev))

        # For each segment, fill against the nearest compatible segment
        # on each side whose projection overlaps.
        for i, (k, a, b) in enumerate(segments):
            for direction in (1, -1):
                j = i + direction
                while 0 <= j < len(segments):
                    k2, a2, b2 = segments[j]
                    lo = max(a, a2)
                    hi = min(b, b2)
                    if lo <= hi:
                        if coordinate == 'u':
                            add_fill(k, k2, lo, hi)
                        else:
                            # Lines of constant v: use v as line coordinate,
                            # u as projection.
                            add_fill(a2, b2, k, k2) if False else add_fill(a, b, k, k2)
                        break
                    j += direction

    process_lines('u', 'v')
    process_lines('v', 'u')

    return out.tolist()

