def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    fours = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 4]
    if not fours:
        return out.tolist()

    # Remove the original 4s; all other colors are treated as obstacles.
    base = g.copy()
    base[base == 4] = 0

    def clear_run(r, c, dr, dc):
        nr, nc = r, c
        steps = 0
        while True:
            nr += dr
            nc += dc
            if 0 <= nr < h and 0 <= nc < w and base[nr, nc] == 0:
                steps += 1
            else:
                break
        return nr - dr, nc - dc, steps

    def wall_len_at(r, c, dr, dc):
        """Length of the wall segment passing through (r, c) perpendicular to the
        slide direction.  If sliding vertically, count the horizontal run;
        if sliding horizontally, count the vertical run."""
        if dr != 0:
            # horizontal wall segment
            if not (0 <= r < h and 0 <= c < w) or base[r, c] == 0:
                return 0
            color = base[r, c]
            length = 1
            nc = c - 1
            while 0 <= nc < w and base[r, nc] == color:
                length += 1
                nc -= 1
            nc = c + 1
            while 0 <= nc < w and base[r, nc] == color:
                length += 1
                nc += 1
            return length
        else:
            # vertical wall segment
            if not (0 <= r < h and 0 <= c < w) or base[r, c] == 0:
                return 0
            color = base[r, c]
            length = 1
            nr = r - 1
            while 0 <= nr < h and base[nr, c] == color:
                length += 1
                nr -= 1
            nr = r + 1
            while 0 <= nr < h and base[nr, c] == color:
                length += 1
                nr += 1
            return length

    # Score each possible slide direction for each 4.
    # The rule inferred from the examples:
    # 1) Prefer directions whose stopping wall segment is longer.
    # 2) Break ties by preferring the longer clear run.
    # 3) Break remaining ties in a fixed cardinal order.
    direction_priority = [(1, 0), (0, 1), (-1, 0), (0, -1)]  # down, right, up, left

    moves = []
    for r, c in fours:
        best = None
        for dr, dc in direction_priority:
            er, ec, dist = clear_run(r, c, dr, dc)
            if dist <= 0:
                continue
            # The wall immediately beyond the stopping cell.
            wr, wc = er + dr, ec + dc
            seg = wall_len_at(wr, wc, dr, dc)
            score = (seg, dist)
            if best is None or score > best[0]:
                best = (score, (er, ec))
        if best is not None:
            moves.append((r, c, best[1][0], best[1][1]))

    # Clear original 4s, then place final positions.
    for r, c, _, _ in moves:
        out[r, c] = 0

    for _, _, nr, nc in moves:
        out[nr, nc] = 4

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Treat 4s as the only moving objects.  All non-zero cells other than 4
    # are static obstacles.
    obs = (g != 0) & (g != 4)

    # If several 4s can move, the intended behaviour is to move them all the
    # way to the farther end of the straight corridor they are in.  We choose
    # the corridor by testing the two axes.  For an axis, a corridor is valid
    # only if the 4 is not immediately blocked in either direction and the
    # cells it would cross remain open when the other 4s are treated as
    # obstacles.
    fours = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 4]
    if not fours:
        return out.tolist()

    # Remove original 4s from the occupancy map for collision testing.
    blocked = obs.copy()

    def clear_in_direction(r, c, dr, dc, extra_blocked):
        """Return the farthest free cell reached in direction (dr, dc)."""
        rr, cc = r, c
        while True:
            nr = rr + dr
            nc = cc + dc
            if 0 <= nr < h and 0 <= nc < w and not blocked[nr, nc] and not extra_blocked[nr, nc]:
                rr, cc = nr, nc
            else:
                break
        return rr, cc

    # For each 4, choose horizontal if it gives a longer maximal slide than
    # vertical; otherwise vertical.  Ties prefer horizontal.
    moves = []
    for r, c in fours:
        # Temporarily block all other 4s.
        others = np.zeros_like(blocked)
        for rr, cc in fours:
            if (rr, cc) != (r, c):
                others[rr, cc] = True

        def axis_score(dr, dc):
            # Two opposite directions.
            er1, ec1 = clear_in_direction(r, c, dr, dc, others)
            d1 = abs(er1 - r) + abs(ec1 - c)
            if d1 == 0:
                return -1, (r, c)
            er2, ec2 = clear_in_direction(r, c, -dr, -dc, others)
            d2 = abs(er2 - r) + abs(ec2 - c)
            if d2 == 0:
                return -1, (r, c)
            if d1 >= d2:
                return max(d1, d2), (er1, ec1)
            else:
                return max(d1, d2), (er2, ec2)

        h_score, h_target = axis_score(0, 1)
        v_score, v_target = axis_score(1, 0)

        if h_score >= v_score and h_score > 0:
            moves.append(((r, c), h_target))
        elif v_score > 0:
            moves.append(((r, c), v_target))
        else:
            # Should not happen for valid puzzle pieces; leave in place.
            moves.append(((r, c), (r, c)))

    # Clear old 4 positions, then write final positions.
    for (r, c), _ in moves:
        out[r, c] = 0
    for _, (nr, nc) in moves:
        out[nr, nc] = 4

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [list(row) for row in grid]

    H = len(grid)
    W = len(grid[0])

    # Start points are existing 6s. In all cases they are short vertical 2-cells.
    starts = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == 6]
    if not starts:
        return [list(row) for row in grid]

    # Horizontal runs of 2.
    runs = []
    for r in range(H):
        c = 0
        while c < W:
            if grid[r][c] == 2:
                c2 = c
                while c2 + 1 < W and grid[r][c2 + 1] == 2:
                    c2 += 1
                runs.append((r, c, c2))
                c = c2 + 1
            else:
                c += 1

    result = [list(row) for row in grid]

    def can_pass(r, c):
        return 0 <= r < H and 0 <= c < W and grid[r][c] == 7

    def clear_path(r1, c1, r2, c2):
        # Only straight horizontal/vertical paths through 7 are used.
        if r1 == r2:
            a, b = min(c1, c2), max(c1, c2)
            for cc in range(a, b + 1):
                if not can_pass(r1, cc):
                    return False
            return True
        if c1 == c2:
            a, b = min(r1, r2), max(r1, r2)
            for rr in range(a, b + 1):
                if not can_pass(rr, c1):
                    return False
            return True
        return False

    def paint_path(r1, c1, r2, c2):
        if r1 == r2:
            a, b = min(c1, c2), max(c1, c2)
            for cc in range(a, b + 1):
                result[r1][cc] = 6
            return
        if c1 == c2:
            a, b = min(r1, r2), max(r1, r2)
            for rr in range(a, b + 1):
                result[rr][c1] = 6
            return

    def paint_elbow(a, b, c):
        # L-shape through an empty corner.
        if clear_path(a[0], a[1], a[0], c) and clear_path(a[0], c, b[0], b[1]):
            paint_path(a[0], a[1], a[0], c)
            paint_path(a[0], c, b[0], b[1])
            return True
        if clear_path(a[0], a[1], c, a[1]) and clear_path(c, a[1], b[0], b[1]):
            paint_path(a[0], a[1], c, a[1])
            paint_path(c, a[1], b[0], b[1])
            return True
        return False

    # For each starting 6, grow a small network to nearby 2-runs.
    # This mirrors the examples: a run is reached only when it is vertically
    # adjacent to the current row and its interval overlaps the current column,
    # then a horizontal bridge is drawn just outside the run and the vertical
    # spine moves to one of its outer edges.
    for (sr, sc) in starts:
        row = sr
        col = sc

        # Go downward from the start.
        while row + 1 < H:
            nr = row + 1
            if grid[nr][col] != 7:
                break
            result[nr][col] = 6
            row = nr

            # Look for a 2-run on this new row that contains or touches the column.
            matched = None
            for (rr, c1, c2) in runs:
                if rr == row and c1 - 1 <= col <= c2 + 1:
                    matched = (rr, c1, c2)
                    break
            if matched is None:
                continue

            _, c1, c2 = matched
            left = c1 - 1
            right = c2 + 1

            # Draw the horizontal bridge across the row above the run
            # from the current column to the chosen side.
            if left >= 0:
                # Prefer the side that stays inside the grid and is reachable.
                if clear_path(row - 1, col, row - 1, left):
                    paint_path(row - 1, col, row - 1, left)
                    col = left
                elif right < W and clear_path(row - 1, col, row - 1, right):
                    paint_path(row - 1, col, row - 1, right)
                    col = right
            elif right < W and clear_path(row - 1, col, row - 1, right):
                paint_path(row - 1, col, row - 1, right)
                col = right

            # Draw the side of the run itself as a vertical segment if possible.
            if col >= 0 and col < W:
                r_a = row - 1
                r_b = row + 1
                a, b = min(r_a, r_b), max(r_a, r_b)
                for rr in range(a, b + 1):
                    if can_pass(rr, col):
                        result[rr][col] = 6

        # If the start is a two-cell vertical seed, the cell above is also part
        # of the given seed and should remain 6 (already true from input).
        if sr > 0 and grid[sr][sc] == 6 and grid[sr - 1][sc] == 7:
            result[sr - 1][sc] = 6

    return result

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    out = [row[:] for row in grid]

    # Particles start from every pre-existing 6 cell.
    particles = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 6:
                particles.add((r, c))

    def run_left_right(row, col):
        l = col
        while l - 1 >= 0 and grid[row][l - 1] == 2:
            l -= 1
        r = col
        while r + 1 < W and grid[row][r + 1] == 2:
            r += 1
        return l, r

    # Simulate deterministic top-to-bottom falling/bouncing particles.
    for r in range(H - 1):
        new_particles = set()
        current = [p for p in particles if p[0] == r]

        for (rr, c) in current:
            if rr != r:
                continue

            below_val = grid[r + 1][c]

            if below_val == 2:
                # Bounce: paint the available horizontal sides of this 2-run
                # on the current row, and spawn particles on those side columns.
                l, rr_run = run_left_right(r + 1, c)

                if l > 0:
                    left_side = l - 1
                    for cc in range(left_side, rr_run + 1):
                        if grid[rr][cc] == 7:
                            out[rr][cc] = 6
                    new_particles.add((r + 1, left_side))

                if rr_run + 1 < W:
                    right_side = rr_run + 1
                    for cc in range(l, right_side + 1):
                        if grid[rr][cc] == 7:
                            out[rr][cc] = 6
                    new_particles.add((r + 1, right_side))

            else:
                # Fall straight down through 7 or existing 6.
                nc = c
                if grid[r + 1][nc] == 7:
                    out[r + 1][nc] = 6
                new_particles.add((r + 1, nc))

        particles = new_particles

    return out

