    if not grid or not grid[0]:
        return []

    h = len(grid)
    w = len(grid[0])

    out = [row[:] for row in grid]

    queue = []
    in_queue = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if out[r][c] == 6:
                queue.append((r, c))
                in_queue[r][c] = True

