                    queue.append((r + 1, c))
        else:
            a = c
            while a > 0 and out[r + 1][a - 1] == 2:
                a -= 1

            b = c
            while b + 1 < w and out[r + 1][b + 1] == 2:
                b += 1

            left = max(0, a - 1)
            right = min(w - 1, b + 1)

            for x in range(left, right + 1):
                if out[r][x] != 6 and out[r][x] != 2:
                    out[r][x] = 6
                    if not in_queue[r][x]:
                        in_queue[r][x] = True
                        queue.append((r, x))

    return out

