from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    if a.size == 0:
        return []
    h, w = a.shape

    # background is the most common colour; if several, prefer 0
    vals, counts = np.unique(a, return_counts=True)
    bg = int(vals[np.argmax(counts + (vals == 0).astype(int))])

    fg = a != bg
    if not fg.any():
        return a.tolist()

    out = fg.copy()
    changed = True

    # Iteratively repair almost-complete horizontal and vertical lines.
    while changed:
        changed = False

        # Horizontal lines
        for r in range(h):
            cols = np.nonzero(out[r])[0]
            if len(cols) < 2:
                continue
            cols = list(cols)
            i = 0
            while i < len(cols):
                j = i
                while j + 1 < len(cols) and cols[j + 1] == cols[j] + 1:
                    j += 1
                # run from cols[i] to cols[j]
                run_len = cols[j] - cols[i] + 1

                # try to extend left if there is a nearby run/point separated by a small gap
                while i > 0:
                    gap = cols[i] - cols[i - 1] - 1
                    if gap <= 3 and (gap <= 2 or run_len >= 3):
                        for c in range(cols[i - 1], cols[i]):
                            if not out[r, c]:
                                out[r, c] = True
                                changed = True
                        run_len += gap + 1
                        i -= 1
                    else:
                        break

                # try to extend right
                while j + 1 < len(cols):
                    gap = cols[j + 1] - cols[j] - 1
                    if gap <= 3 and (gap <= 2 or run_len >= 3):
                        for c in range(cols[j] + 1, cols[j + 1] + 1):
                            if not out[r, c]:
                                out[r, c] = True
                                changed = True
                        run_len += gap + 1
                        j += 1
                    else:
                        break

                i = j + 1

        # Vertical lines
        for c in range(w):
            rows = np.nonzero(out[:, c])[0]
            if len(rows) < 2:
                continue
            rows = list(rows)
            i = 0
            while i < len(rows):
                j = i
                while j + 1 < len(rows) and rows[j + 1] == rows[j] + 1:
                    j += 1
                run_len = rows[j] - rows[i] + 1

                while i > 0:
                    gap = rows[i] - rows[i - 1] - 1
                    if gap <= 3 and (gap <= 2 or run_len >= 3):
                        for r in range(rows[i - 1], rows[i]):
                            if not out[r, c]:
                                out[r, c] = True
                                changed = True
                        run_len += gap + 1
                        i -= 1
                    else:
                        break

                while j + 1 < len(rows):
                    gap = rows[j + 1] - rows[j] - 1
                    if gap <= 3 and (gap <= 2 or run_len >= 3):
                        for r in range(rows[j] + 1, rows[j + 1] + 1):
                            if not out[r, c]:
                                out[r, c] = True
                                changed = True
                        run_len += gap + 1
                        j += 1
                    else:
                        break

                i = j + 1

    # Remove isolated foreground pixels, except single-cell components that
    # are not merely noise next to a larger completed structure.
    fg_out = out
    keep = np.zeros_like(fg_out)

    # 4-connected components
    seen = np.zeros_like(fg_out, dtype=bool)
    comps = []
    for r in range(h):
        for c in range(w):
            if fg_out[r, c] and not seen[r, c]:
                stack = [(r, c)]
                seen[r, c] = True
                comp = []
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and fg_out[ny, nx] and not seen[ny, nx]:
                            seen[ny, nx] = True
                            stack.append((ny, nx))
                comps.append(comp)

    for comp in comps:
        if len(comp) == 1:
            y, x = comp[0]
            # keep single pixels only if they are not adjacent (8-neighbour) to another component
            isolated = True
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and fg_out[ny, nx] and not seen[ny, nx]:
                        isolated = False
            if isolated:
                keep[y, x] = True
        else:
            for y, x in comp:
                keep[y, x] = True

    final = fg_out & keep
    res = np.where(final, 1, 0) * int(a[final][0]) if final.any() else np.zeros_like(a)
    # preserve original foreground colour if there is exactly one non-background colour
    non_bg = a[fg]
    if len(np.unique(non_bg)) == 1:
        col = int(np.unique(non_bg)[0])
        res = np.where(final, col, bg)
    else:
        res = np.where(final, 1, bg)

    return res.tolist()

