from typing import List

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    arr = np.array(grid, dtype=int)
    h, w = arr.shape

    # Find the background colour: prefer 0 if tied, otherwise the most common colour.
    vals, cnts = np.unique(arr, return_counts=True)
    max_cnt = np.max(cnts)
    candidates = vals[cnts == max_cnt]
    bg = 0 if 0 in candidates else int(candidates[0])

    # There should be exactly one non-background colour in the examples/tests.
    nonbg_vals = np.unique(arr[arr != bg])
    if len(nonbg_vals) == 0:
        return [[bg] * w for _ in range(h)]
    fg_color = int(nonbg_vals[0])

    # Work with a boolean foreground mask.
    mask = arr == fg_color

    def runs_in_axis(mask, axis):
        """Return list of (start, end) inclusive runs of True along `axis`."""
        line = mask if axis == 0 else mask.T
        length = line.shape[0]
        runs = []
        i = 0
        while i < length:
            if line[i].any():
                j = i
                # contiguous run of rows/cols that contain at least one foreground pixel?
                # We need runs per single line; this function should be called per line.
                j = i
                while j + 1 < length and line[j + 1].any():
                    j += 1
                runs.append((i, j))
                i = j + 1
            else:
                i += 1
        return runs

    def row_runs(mask, r):
        row = mask[r]
        out = []
        c = 0
        while c < w:
            if row[c]:
                d = c
                while d + 1 < w and row[d + 1]:
                    d += 1
                out.append((c, d))
                c = d + 1
            else:
                c += 1
        return out

    def col_runs(mask, c):
        col = mask[:, c]
        out = []
        r = 0
        while r < h:
            if col[r]:
                d = r
                while d + 1 < h and col[d + 1]:
                    d += 1
                out.append((r, d))
                c_idx = c
                # no side effects
                out[-1] = (r, d)
                r = d + 1
            else:
                r += 1
        return out

    changed = True
    while changed:
        changed = False

        # Forward horizontal completion:
        # Left-to-right, only from a run that does not touch the left border,
        # and only if both adjacent runs have length at least 3.
        for r in range(h):
            rr = row_runs(mask, r)
            for i in range(len(rr) - 1):
                l0, l1 = rr[i]
                r0, r1 = rr[i + 1]
                len_l = l1 - l0 + 1
                len_r = r1 - r0 + 1
                if l0 > 0 and len_l >= 3 and len_r >= 3:
                    # fill gap between l1+1 and r0-1
                    if r0 - l1 > 1:
                        for c in range(l1 + 1, r0):
                            if not mask[r, c]:
                                mask[r, c] = True
                                changed = True

        # Forward vertical completion:
        # Top-to-bottom, only from a run that does not touch the top border,
        # and only if both adjacent runs have length at least 3.
        for c in range(w):
            cc = col_runs(mask, c)
            for i in range(len(cc) - 1):
                u0, u1 = cc[i]
                d0, d1 = cc[i + 1]
                len_u = u1 - u0 + 1
                len_d = d1 - d0 + 1
                if u0 > 0 and len_u >= 3 and len_d >= 3:
                    if d0 - u1 > 1:
                        for r in range(u1 + 1, d0):
                            if not mask[r, c]:
                                mask[r, c] = True
                                changed = True

    # Now remove pixels that are not supported by a collinear group.
    # A pixel is supported if there exists at least 3 foreground pixels in the same row
    # or same column such that consecutive pixels in sorted coordinate order have gap <= 3.
    keep = np.zeros_like(mask, dtype=bool)

    # Row support
    for r in range(h):
        cols = np.nonzero(mask[r])[0].tolist()
        if not cols:
            continue
        i = 0
        n = len(cols)
        while i < n:
            j = i
            while j + 1 < n and cols[j + 1] - cols[j] <= 3:
                j += 1
            if j - i + 1 >= 3:
                for k in range(i, j + 1):
                    keep[r, cols[k]] = True
            i = j + 1

    # Column support
    for c in range(w):
        rows = np.nonzero(mask[:, c])[0].tolist()
        if not rows:
            continue
        i = 0
        n = len(rows)
        while i < n:
            j = i
            while j + 1 < n and rows[j + 1] - rows[j] <= 3:
                j += 1
            if j - i + 1 >= 3:
                for k in range(i, j + 1):
                    keep[rows[k], c] = True
            i = j + 1

    final_mask = mask & keep

    # Reconstruct output grid: keep foreground colour on supported pixels,
    # background elsewhere.
    out = np.full((h, w), bg, dtype=int)
    out[final_mask] = fg_color

    return out.tolist()

