                if arr[r][c] == val and visited[r][c] is None:
                    stack = [(r,c)]
                    visited[r][c] = cid
                    while stack:
                        cr, cc = stack.pop()
                        for nr, nc in neighbors4(cr, cc):
                            if arr[nr][nc] == val and visited[nr][nc] is None:
                                visited[nr][nc] = cid
                                stack.append((nr, nc))
                    cid += 1
        return visited

    # Identify the wall: the largest connected component that spans the grid
    # horizontally or vertically.
    visited = [[None]*w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if a[r][c] != 0 and visited[r][c] is None:
                val = a[r][c]
                cells = []
                stack = [(r,c)]
                visited[r][c] = len(comps)
