                    cells.append((cr,cc))
                    for nr, nc in neighbors4(cr, cc):
                        if a[nr][nc] == val and visited[nr][nc] is None:
                            visited[nr][nc] = len(comps)
                            stack.append((nr, nc))
                rows = [x[0] for x in cells]
                cols = [x[1] for x in cells]
                comps.append({
                    'color': val,
                    'cells': cells,
                    'min_r': min(rows), 'max_r': max(rows),
                    'min_c': min(cols), 'max_c': max(cols),
                    'size': len(cells)
                })

    wall = None
    best = -1
    for comp in comps:
        span_h = (comp['max_r'] - comp['min_r'] + 1) == h
        span_w = (comp['max_c'] - comp['min_c'] + 1) == w
        if span_h or span_w:
            score = comp['size'] * 1000000 + (comp['max_r']-comp['min_r']) + (comp['max_c']-comp['min_c'])
            if score > best:
                best = score
                wall = comp

