def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])
    if W == 0:
        return []

    # Find the 0 corner of the border.
    fr = fc = None
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0:
                fr, fc = r, c
                break
        if fr is not None:
            break

    if fr is None:
        return [row[:] for row in grid]

    # Directions along the two border arms from the 0 corner.
    if fc == 0:
        hdir = 1
    elif fc == W - 1:
        hdir = -1
    else:
        hdir = 1 if fc <= W - 1 - fc else -1

    if fr == 0:
        vdir = 1
    elif fr == H - 1:
        vdir = -1
    else:
        vdir = 1 if fr <= H - 1 - fr else -1

    # The border arm colored 2 is the primary sorting axis.
    hcol = None
    if hdir == 1 and fc + 1 < W:
        hcol = grid[fr][fc + 1]
    elif hdir == -1 and fc - 1 >= 0:
        hcol = grid[fr][fc - 1]

    primary_horizontal = (hcol == 2)

    # Extract connected non-8 components inside the frame.
    visited = [[False] * W for _ in range(H)]
    comps = []

    for r in range(H):
        for c in range(W):
            if r == fr or c == fc:
                continue
            if grid[r][c] == 8 or grid[r][c] == 0:
                continue
            if visited[r][c]:
                continue

            stack = [(r, c)]
            visited[r][c] = True
            cells = []

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if nr == fr or nc == fc:
                            continue
                        if not visited[nr][nc] and grid[nr][nc] != 8 and grid[nr][nc] != 0:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

            rmin = min(cell[0] for cell in cells)
            rmax = max(cell[0] for cell in cells)
            cmin = min(cell[1] for cell in cells)
            cmax = max(cell[1] for cell in cells)
            comps.append((rmin, rmax, cmin, cmax))

    def v_key(rmin, rmax):
        if vdir == 1:
            return rmin - fr
        return fr - rmax

    def h_key(cmin, cmax):
        if hdir == 1:
            return cmin - fc
        return fc - cmax

    # Sort by primary axis (color 2), then secondary axis (color 1).
    if primary_horizontal:
        comps.sort(key=lambda x: (h_key(x[2], x[3]), v_key(x[0], x[1]), x[0], x[2]))
    else:
        comps.sort(key=lambda x: (v_key(x[0], x[1]), h_key(x[2], x[3]), x[0], x[2]))

    def rotate_ccw(m):
        mh = len(m)
        if mh == 0:
            return []
        mw = len(m[0])
        return [[m[c][mw - 1 - r] for c in range(mh)] for r in range(mw)]

    blocks = []
    for rmin, rmax, cmin, cmax in comps:
        sub = [[grid[r][c] for c in range(cmin, cmax + 1)] for r in range(rmin, rmax + 1)]

        # Vertical objects are stored rotated 90 degrees clockwise.
        if len(sub) > 2:
            sub = rotate_ccw(sub)

        # Fallbacks for unexpected one-row shapes.
        if len(sub) == 1:
            sub = [sub[0], [8] * len(sub[0])]
        elif len(sub) > 2:
            if len(sub[0]) == 2:
                sub = rotate_ccw(sub)
            if len(sub) < 2:
                sub = sub + [[8] * len(sub[0])]
            elif len(sub) > 2:
                sub = sub[:2]

        blocks.append(sub)

    if not blocks:
        return []

    maxw = max(len(row) for b in blocks for row in b)
    out = []

    for b in blocks:
        for row in b:
            w = len(row)
            left = (maxw - w) // 2
            right = maxw - w - left
            out.append([8] * left + list(row) + [8] * right)

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    g = np.array(grid, dtype=int)
    h, w = g.shape
    out = g.copy()

    # Identify all non-background colors/components
    bg = int(np.bincount(g.ravel()).argmax())
    colors = set(int(c) for c in np.unique(g) if c != bg)

    from collections import deque

    def components(mask):
        comp = np.zeros_like(mask, dtype=int)
        res = []
        idx = 0
        for i in range(h):
            for j in range(w):
                if mask[i, j] and comp[i, j] == 0:
                    idx += 1
                    q = deque([(i, j)])
                    comp[i, j] = idx
                    cells = [(i, j)]
                    while q:
                        r, c = q.popleft()
                        for dr in (-1, 0, 1):
                            for dc in (-1, 0, 1):
                                if dr == 0 and dc == 0:
                                    continue
                                nr, nc = r + dr, c + dc
                                if 0 <= nr < h and 0 <= nc < w and mask[nr, nc] and comp[nr, nc] == 0:
                                    comp[nr, nc] = idx
                                    q.append((nr, nc))
                                    cells.append((nr, nc))
                    res.append(cells)
        return res

    # Build components by color
    comps = {}
    for c in colors:
        mask = (g == c)
        comps[c] = components(mask)

    # Helper: endpoints of a path-like component (cells with degree 1 in 8-neighborhood)
    def endpoints(cells):
        pts = set(cells)
        ends = []
        for r, c in cells:
            deg = sum(1 for dr in (-1,0,1) for dc in (-1,0,1)
                      if (dr, dc) != (0,0) and (r+dr, c+dc) in pts)
            if deg == 1:
                ends.append((r,c))
        return ends

    # Helper: cells adjacent to a component (8-neighbor), excluding cells of that component
    def neighbor_cells(cells, exclude_colors):
        pts = set(cells)
        neigh = set()
        for r,c in pts:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr,nc] != bg:
                        if g[nr,nc] not in exclude_colors and (nr,nc) not in pts:
                            neigh.add((nr,nc))
        return neigh

    # Chebyshev distance
    def dist(a,b):
        return max(abs(a[0]-b[0]), abs(a[1]-b[1]))

    # Choose a monotone shortest 8-neighbor path from start to end.
    # Preference: keep row changes early, then col changes, then alternate diagonally.
    def shortest_path(start, end):
        r0,c0 = start
        r1,c1 = end
        path = []
        r,c = r0,c0
        while (r,c) != (r1,c1):
            dr = 0 if r == r1 else (1 if r1 > r else -1)
            dc = 0 if c == c1 else (1 if c1 > c else -1)
            # Try diagonal first if both remain, otherwise single-step
            if dr != 0 and dc != 0:
                nr, nc = r+dr, c+dc
                # If diagonal step makes future impossible due to parity? Chebyshev always possible.
                path.append((nr,nc))
                r,c = nr,nc
            elif dr != 0:
                path.append((r+dr,c))
                r += dr
            else:
                path.append((r,c+dc))
                c += dc
        return [(r0,c0)] + path

    # Decide if a component looks like a "path" (not a straight line)
    def is_path(cells):
        if len(cells) < 3:
            return False
        rows = [r for r,c in cells]
        cols = [c for r,c in cells]
        # A straight horizontal/vertical line
        if len(set(rows)) == 1 or len(set(cols)) == 1:
            return False
        # Endpoint test: at least two 1-degree cells
        return len(endpoints(cells)) >= 2

    # Identify candidate moving path components and their anchors
    candidates = []
    for c, comps_c in comps.items():
        for cells in comps_c:
            if not is_path(cells):
                continue
            ends = endpoints(cells)
            if len(ends) < 2:
                continue
            # Adjacent non-path colors: line-like anchors
            adj_colors = set()
            for cell in cells:
                r,c0 = cell
                for dr in (-1,0,1):
                    for dc in (-1,0,1):
                        if dr == 0 and dc == 0:
                            continue
                        nr,nc = r+dr,c0+dc
                        if 0 <= nr < h and 0 <= nc < w and g[nr,nc] != bg:
                            other = int(g[nr,nc])
                            # Only treat single-cell or straight-line components as anchors
                            for other_cells in comps.get(other, []):
                                rr = [x for x,y in other_cells]
                                cc = [y for x,y in other_cells]
                                if len(other_cells) == 1 or len(set(rr)) == 1 or len(set(cc)) == 1:
                                    adj_colors.add(other)
            if adj_colors:
                candidates.append((c, cells, ends, adj_colors))

    # For each moving path, reroute it.
    # Heuristic consistent with ARC examples:
    # - Keep one endpoint that is adjacent to an anchor line.
    # - Move the other endpoint to the opposite side of the nearest anchor/obstacle.
    # - Draw a shortest path between new endpoints.
    for c, cells, ends, adj_colors in candidates:
        pts = set(cells)
        # Choose fixed end: endpoint adjacent to a line-like anchor
        fixed = None
        for e in ends:
            r0,c0 = e
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    if dr == 0 and dc == 0:
                        continue
                    nr,nc = r0+dr,c0+dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr,nc] in adj_colors:
                        fixed = e
                        break
                if fixed:
                    break
            if fixed:
                break
        if fixed is None:
            fixed = ends[0]
        free = ends[1] if ends[1] != fixed else ends[0]

        # Determine target direction: away from the nearest anchor component.
        anchor_cells = []
        for ac in adj_colors:
            for comp_c in comps.get(ac, []):
                if any(dist(cell, comp_cell) <= 1 for cell in cells for comp_cell in comp_c):
                    anchor_cells.extend(comp_c)
        if not anchor_cells:
            continue

        ar = sum(r for r,c in anchor_cells)/len(anchor_cells)
        ac = sum(c for r,c in anchor_cells)/len(anchor_cells)

        # New free endpoint: project from fixed through anchor and extend to grid edge
        # if possible; otherwise reflect free endpoint around fixed point.
        # Try a few candidate targets and choose one that yields a valid in-bounds path.
        candidates_target = []

        # 1. Opposite side of anchor, distance = original free distance + 1
        dr = fixed[0] - ar
        dc = fixed[1] - ac
        norm = max(abs(dr), abs(dc))
        if norm > 0:
            d_orig = max(abs(free[0]-fixed[0]), abs(free[1]-fixed[1]))
            scale = (d_orig + 1) / norm
            tr = int(round(fixed[0] + dr*scale))
            tc = int(round(fixed[1] + dc*scale))
            candidates_target.append((tr, tc))

        # 2. Reflect free endpoint around fixed endpoint
        candidates_target.append((2*fixed[0]-free[0], 2*fixed[1]-free[1]))

        # 3. Top/bottom/left/right edge in the direction away from anchor
        if fixed[0] < ar:  # away upward
            candidates_target.append((0, fixed[1]))
        elif fixed[0] > ar:
            candidates_target.append((h-1, fixed[1]))
        if fixed[1] < ac:
            candidates_target.append((fixed[0], 0))
        elif fixed[1] > ac:
            candidates_target.append((fixed[0], w-1))

        chosen = None
        for target in candidates_target:
            r,c = target
            if 0 <= r < h and 0 <= c < w:
                chosen = (r,c)
                break

        if chosen is None:
            continue

        path = shortest_path(fixed, chosen)
        # Remove old moving cells
        for r,c in cells:
            out[r,c] = bg
        # Add new path, but do not overwrite non-background cells
        for r,c in path:
            if 0 <= r < h and 0 <= c < w and out[r,c] == bg:
                out[r,c] = c
            # If cell is occupied by another color, keep other color (hidden overlap)

    return out.tolist()

import sys

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    if H == 0:
        return []
    W = len(grid[0])

    def neighbors(r, c, diag=True):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    yield nr, nc

    def is_line(cells):
        if len(cells) < 2:
            return False
        rs = {r for r, c in cells}
        cs = {c for r, c in cells}
        if len(rs) == 1 or len(cs) == 1:
            return True
        # Treat a tight 2x2 block as a short line segment too.
        if len(rs) == 2 and len(cs) == 2:
            if all((r, c) in cells for r in rs for c in cs):
                return True
        return False

    def component_of(start, color):
        seen = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if grid[nr][nc] == color and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    stack.append((nr, nc))
        return seen

    def endpoints(cells):
        pts = set(cells)
        ep = []
        for r, c in pts:
            deg = sum(1 for nr, nc in neighbors(r, c) if (nr, nc) in pts)
            if deg == 1:
                ep.append((r, c))
        if not ep:
            return sorted(pts)
        return ep

    # All background colors: choose the one that makes non-background components simple.
    # In these grids, background is usually the color with the largest component.
    from collections import defaultdict
    by_color = defaultdict(set)
    for r in range(H):
        for c in range(W):
            by_color[grid[r][c]].add((r, c))

    bg = None
    best = -1
    for color, cells in by_color.items():
        # estimate component size via quick BFS from one cell
        start = next(iter(cells))
        comp = component_of(start, color)
        if len(comp) > best:
            best = len(comp)
            bg = color

    if bg is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    nonbg_colors = [c for c in by_color if c != bg]

    # Identify line/anchor components and path components.
    line_components = []
    path_components = []
    for color in nonbg_colors:
        # find all components of this color
        seen = set()
        for r in range(H):
            for c in range(W):
                if grid[r][c] == color and (r, c) not in seen:
                    comp = component_of((r, c), color)
                    seen |= comp
                    if is_line(comp):
                        line_components.append((color, comp))
                    elif len(comp) >= 2:
                        path_components.append((color, comp))

    # For each path component, try to move it to the opposite side of an adjacent line.
    for pcolor, pcells in path_components:
        cells = set(pcells)
        eps = endpoints(cells)
        if len(eps) < 2:
            continue

        # Find an endpoint adjacent to a line component.
        anchor = None
        anchor_line = None
        other_eps = []
        for e in eps:
            er, ec = e
            for line_color, line_cells in line_components:
                if line_color == pcolor:
                    continue
                # Check 8-adjacency to line
                for lr, lc in line_cells:
                    if max(abs(lr - er), abs(lc - ec)) <= 1:
                        anchor = e
                        anchor_line = (line_color, line_cells)
                        other_eps = [x for x in eps if x != e]
                        break
                if anchor:
                    break
            if anchor:
                break

        if anchor is None or not other_eps:
            continue

        # Determine the side of the anchor line on which the free endpoint lies.
        # Use the line's orientation.
        line_color, line_cells = anchor_line
        if anchor_line is None:
            continue
        lrs = [r for r, c in line_cells]
        lcs = [c for r, c in line_cells]

        vertical = (max(lrs) - min(lrs)) > (max(lcs) - min(lcs))
        free = other_eps[0]

        if vertical:
            # side: left or right of the line
            line_col = sum(lcs) // len(lcs)
            side = 1 if free[1] >= line_col else -1
            # direction: up or down, opposite to free endpoint relative to anchor row
            dr = -1 if free[0] >= anchor[0] else 1
        else:
            # horizontal line: side is above/below
            line_row = sum(lrs) // len(lrs)
            side = 1 if free[0] >= line_row else -1
            dr = 1 if free[1] >= anchor[1] else -1

        # The path length is the number of cells in the original component.
        L = len(cells)

        # Determine how far to go: one step per row until boundary or L cells.
        ar, ac = anchor
        max_steps = L - 1
        if dr < 0:
            max_steps = min(max_steps, ar)
        else:
            max_steps = min(max_steps, H - 1 - ar)

        # Obstacles: all non-background cells except the path being moved.
        blocked = set()
        for r in range(H):
            for c in range(W):
                if grid[r][c] != bg and grid[r][c] != pcolor:
                    blocked.add((r, c))
        # Anchor may be adjacent to line, but anchor cell itself is path color; keep it free.
        # Do not block other path colors? They are also non-background; treat as obstacles.
        # But if another path is also transformed, process independently on original grid.

        # Build a row-monotone path: each step changes row by dr, col by -1,0,1.
        # Choose the path that first moves in the side direction as much as possible,
        # while remaining feasible to return to the anchor column by the boundary
        # when it will not be truncated. If truncated, prefer staying closer to
        # the side-limited target column.
        #
        # We implement by dynamic programming feasible columns for the full run
        # to the boundary, then greedily choose:
        # - if the run reaches the boundary: the closest-to-side feasible column
        #   that can still reach the anchor column at the boundary.
        # - if truncated: the closest-to-side feasible column that can continue
        #   for the remaining truncated length.

        target_row = ar + dr * max_steps

        # Feasibility backward for full boundary run (to row boundary).
        # But if truncated before boundary, use target_row.
        # We'll compute feasibility to target_row for the actual length, and also
        # compute a full-boundary feasibility if possible for side choice.
        def feasible_columns(up_to_row, start_col, stop_col=None):
            # rows from up_to_row down/up to start row? We only need from current row to target.
            return None

        # Simpler greedy with lookahead:
        path = [(ar, ac)]
        r, c = ar, ac
        steps_done = 0
        # Determine if we will reach boundary:
        reach_boundary = (max_steps == (ar if dr < 0 else H - 1 - ar))

        # We want to prefer columns that are on the side:
        # side = -1 means left/above; side = 1 means right/below.
        # For vertical lines, side is horizontal; for horizontal, side is vertical.
        # Here the movement is always along dr (row). For horizontal anchor, side is row,
        # but movement is column; adapt below by using side as the direction of column movement.
        if vertical:
            move_pref = side  # -1 left, +1 right
        else:
            # For horizontal anchor, the "side" is above/below, but the monotone path moves columns.
            # In the supplied examples with horizontal lines, choose side based on free endpoint column.
            move_pref = 1 if free[1] >= ac else -1

        # If the line is attached to the target boundary on the preferred side,
        # the path may be forced to a column next to it. We approximate by dynamic feasibility.
        # Compute DP of feasible columns for rows from r to target_row that can reach
        # a final column equal to anchor column (if reaching boundary) or any column
        # (if truncated) with at most 1 column change per row.
        def dp_feasible(final_col_constraint):
            # rows from r to target_row inclusive, step dr.
            rows = list(range(r, target_row, dr)) if dr > 0 else list(range(r, target_row - 1, -1))
            # feasible at last row
            if final_col_constraint is not None:
                feasible = {final_col_constraint} if 0 <= final_col_constraint < W else set()
            else:
                feasible = set(range(W))
            # iterate backward
            for rr in reversed(rows[:-1]):
                nf = set()
                for col in feasible:
                    for nc in (col - 1, col, col + 1):
                        if 0 <= nc < W and (rr, nc) not in blocked:
                            nf.add(nc)
                feasible = nf
                if not feasible:
                    break
            return feasible

        # Greedily step.
        for _ in range(max_steps):
            nr = r + dr
            # Candidate columns around current c.
            cands = [c + move_pref, c, c - move_pref]
            # Ensure uniqueness and in bounds, not blocked.
            valid_cands = []
            for nc in cands:
                if 0 <= nc < W and (nr, nc) not in blocked and nc not in valid_cands:
                    valid_cands.append(nc)
            # If none, allow any in-bounds adjacent not blocked.
            if not valid_cands:
                valid_cands = [nc for nc in (c - 1, c, c + 1)
                               if 0 <= nc < W and (nr, nc) not in blocked]
            # Choose the first candidate that allows completion.
            chosen = None
            remaining_steps = max_steps - 1
            # target for completion: if we will reach boundary and not truncated, anchor column;
            # otherwise no strict final column.
            strict_final = ac if reach_boundary else None
            for nc in valid_cands:
                # quick DP feasibility from (nr, nc) for remaining_steps
                # small grids, DP is fine.
                last_row = nr + dr * remaining_steps
                if strict_final is not None:
                    rows = list(range(nr, last_row, dr)) if dr > 0 else list(range(nr, last_row - 1, -1))
                    feasible = {strict_final} if 0 <= strict_final < W else set()
                    for rr in reversed(rows[:-1]):
                        nf = set()
                        for col in feasible:
                            for mcol in (col - 1, col, col + 1):
                                if 0 <= mcol < W and (rr, mcol) not in blocked:
                                    nf.add(mcol)
                        feasible = nf
                        if not feasible:
                            break
                    if (nr, nc) not in blocked and nc in feasible:
                        chosen = nc
                        break
                else:
                    # just require no immediate dead-end: at least one continuation
                    ok = True
                    # simulate one more step? For truncated path, we don't care final,
                    # but avoid entering a dead end if possible.
                    # Prefer candidate that has at least one valid next column, unless last step.
                    if remaining_steps > 0:
                        nnr = nr + dr
                        has_next = any(
                            0 <= mcol < W and (nnr, mcol) not in blocked
                            for mcol in (nc - 1, nc, nc + 1)
                        )
                        if not has_next:
                            ok = False
                    if ok:
                        chosen = nc
                        break
            if chosen is None:
                chosen = valid_cands[0]
            r, c = nr, chosen
            path.append((r, c))

        # Clear old path cells.
        for rr, cc in cells:
            out[rr][cc] = bg
        # Draw new path, only over background to avoid overwriting other objects.
        for rr, cc in path:
            if out[rr][cc] == bg:
                out[rr][cc] = pcolor
            else:
                # If the anchor cell is already another color (shouldn't), keep it.
                pass

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    from collections import deque

    grid = [[int(x) for x in row] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0

    # The instruction block is the first six rows; the actual canvas is below it.
    if h <= 6:
        return [row[:] for row in grid]

    top = grid[:6]
    canvas = [row[:] for row in grid[6:]]
    H = len(canvas)
    W = len(canvas[0]) if H else 0

    def parse_targets(top):
        """Extract the four target colour values from the 4x24 instruction strip."""
        targets = []
        if len(top) < 5:
            return targets
        # Chambers are columns 1-4, 7-10, 13-16, 19-22 of the instruction rows.
        for start in (1, 7, 13, 19):
            for r in range(1, 5):
                row = top[r]
                if start + 1 < len(row):
                    v = row[start]
                    if 1 <= v <= 9:
                        targets.append(int(v))
                        break
        return targets

    def find_rects(color):
        """Return the bounding box of all cells of the given color."""
        cells = []
        for r in range(H):
            row = canvas[r]
            for c, v in enumerate(row):
                if v == color:
                    cells.append((r, c))
        if not cells:
            return None
        rmin = min(r for r, c in cells)
        rmax = max(r for r, c in cells)
        cmin = min(c for r, c in cells)
        cmax = max(c for r, c in cells)
        return (rmin, cmin, rmax, cmax)

    targets = parse_targets(top)
    boxes = []

    # Seed box: the initial 8 square.
    seed = find_rects(8)
    if seed is not None:
        boxes.append((8, seed))

    # Target boxes in the order given by the instruction strip.
    seen = set()
    for t in targets:
        if t == 8 or t in seen:
            continue
        b = find_rects(t)
        if b is not None:
            boxes.append((t, b))
            seen.add(t)

    if not boxes:
        return canvas

    # If no 8 seed was found, use the first parsed target as the seed.
    if len(boxes) == 1 and boxes[0][0] != 8:
        boxes = [(8, boxes[0][1])]

    # Path width is the side length of the 8 square.
    seed = find_rects(8) or boxes[0][1]
    r0, c0, r1, c1 = seed
    path_h = r1 - r0 + 1
    path_w = c1 - c0 + 1
    th = min(path_h, H)
    tw = min(path_w, W)

    out = [row[:] for row in canvas]

    def paint_segment(r, c, hgt, wid):
        for rr in range(r, r + hgt):
            if rr < 0 or rr >= H:
                continue
            for cc in range(c, c + wid):
                if 0 <= cc < W:
                    out[rr][cc] = 8

    # Initial 8 square.
    if find_rects(8) is not None:
        r0, c0, r1, c1 = find_rects(8)
        paint_segment(r0, c0, r1 - r0 + 1, c1 - c0 + 1)

    def connected_component(box):
        """BFS through current 8 cells to the cells adjacent to this box."""
        rmin, cmin, rmax, cmax = box
        q = deque()
        visited = set()

        # Cells in the thickness band outside the box that are already 8.
        for r in range(max(0, rmin - th), min(H, rmax + th + 1)):
            for c in range(max(0, cmin - tw), min(W, cmax + tw + 1)):
                if out[r][c] == 8:
                    # Do not start inside terminal rectangles of other colors;
                    # the band is just outside, but this is a safe guard.
                    q.append((r, c))
                    visited.add((r, c))

        seen_boxes = set()
        while q:
            r, c = q.popleft()
            # If this 8 cell touches the target box, the component is connected.
            if rmin - 1 <= r <= rmax + 1 and cmin - 1 <= c <= cmax + 1:
                seen_boxes.add(box)
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and out[nr][nc] == 8 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))
        return seen_boxes

    def box_distance(box):
        rmin, cmin, rmax, cmax = box
        best = None
        best_d = None
        for idx, (col, b) in enumerate(boxes):
            if b == box:
                continue
            comp = connected_component(b)
            if box in comp:
                d = 0
            else:
                # Chebyshev distance between boxes, using the path width for thickness.
                dr = 0
                if b[0] < box[2]:
                    dr = box[0] - (b[2] + 1) + 1
                elif b[2] > box[0]:
                    dr = b[0] - (box[2] + 1) + 1
                else:
                    dr = 0
                dc = 0
                if b[1] < box[3]:
                    dc = box[1] - (b[3] + 1) + 1
                elif b[3] > box[1]:
                    dc = b[1] - (box[3] + 1) + 1
                else:
                    dc = 0
                d = max(abs(dr), abs(dc))
            key = (d, idx)
            if best_d is None or key < best_d:
                best_d = key
                best = b
        return best

    # Grow a connected 8-network by always connecting the nearest unconnected box.
    boxes_sorted = list(boxes)
    # Keep the 8 seed first.
    boxes_sorted.sort(key=lambda x: 0 if x[0] == 8 else 1)

    connected = set()
    for col, b in boxes_sorted:
        connected.add(b)

    for _ in range(len(boxes_sorted) + 5):
        unconn = [b for col, b in boxes_sorted if b not in connected]
        if not unconn:
            break

        best_box = None
        best_anchor = None
        best_key = None
        for b in unconn:
            anchor = box_distance(b)
            if anchor is None:
                continue
            key = (
                max(abs(b[0] - anchor[0]), abs(b[2] - anchor[2]),
                    abs(b[1] - anchor[1]), abs(b[3] - anchor[3])),
                boxes_sorted.index((0, b)) if False else 0,
            )
            # Use simple deterministic preference: nearest anchor, then top-leftmost box.
            dr = 0
            if anchor[0] < b[2]:
                dr = b[0] - (anchor[2] + 1) + 1
            elif anchor[2] > b[0]:
                dr = anchor[0] - (b[2] + 1) + 1
            dc = 0
            if anchor[1] < b[3]:
                dc = b[1] - (anchor[3] + 1) + 1
            elif anchor[3] > b[1]:
                dc = anchor[1] - (b[3] + 1) + 1
            dist = max(abs(dr), abs(dc))
            key = (dist, b[0], b[1], anchor[0], anchor[1])
            if best_key is None or key < best_key:
                best_key = key
                best_box = b
                best_anchor = anchor

        if best_box is None:
            break

        # Draw a thick L-shaped corridor between best_box and best_anchor.
        r0b, c0b, r1b, c1b = best_box
        r0a, c0a, r1a, c1a = best_anchor

        # Determine the two endpoints of the corridor (just outside each box).
        # Vertical-first if boxes are separated more in y than x, otherwise horizontal-first.
        dy = 0
        if r0a < r1b:
            dy = r0b - (r1a + 1) + 1
        elif r1a > r0b:
            dy = r0a - (r1b + 1) + 1
        dx = 0
        if c0a < c1b:
            dx = c0b - (c1a + 1) + 1
        elif c1a > c0b:
            dx = c0a - (c1b + 1) + 1

        # Anchor points on the boxes' borders.
        if abs(dy) >= abs(dx):
            # Vertical first.
            if r0a <= r1b and r1a >= r0b:
                # Overlapping y: use a vertical line at the horizontal midpoint.
                mid_c = (c0b + c1a) // 2 if c1a < c0b else (c0a + c1b) // 2
                paint_segment(r0a, mid_c - tw // 2, max(r1a - r0a + 1, th), tw)
            else:
                if r0a < r0b:
                    v_top = r1a
                    v_bot = r0b
                else:
                    v_top = r1b
                    v_bot = r0a
                h_row = r0a if r0a < r0b else r0b
                # Vertical segment
                if v_bot < v_top:
                    v_top, v_bot = v_bot, v_top
                if r0b <= r1b:
                    vc = c0b - tw // 2
                else:
                    vc = c0a - tw // 2
                paint_segment(v_top, vc, v_bot - v_top + 1, tw)
                # Horizontal connector
                if c0a < c1b:
                    hc = c1a + 1
                    hw = c0b - c1a - 1
                elif c1a > c0b:
                    hc = c1b + 1
                    hw = c0a - c1b - 1
                else:
                    hc = max(c0a, c0b)
                    hw = 1
                paint_segment(h_row - th // 2, hc, th, max(hw, 1))
        else:
            # Horizontal first.
            if c0a <= c1b and c1a >= c0b:
                mid_r = (r0b + r1a) // 2 if r1a < r0b else (r0a + r1b) // 2
                paint_segment(mid_r - th // 2, min(c0a, c0b), th, abs(c1a - c0b) + 1)
            else:
                if c0a < c0b:
                    h_left = c1a
                    h_right = c0b
                else:
                    h_left = c1b
                    h_right = c0a
                v_col = c0a if c0a < c0b else c0b
                if h_right < h_left:
                    h_left, h_right = h_right, h_left
                paint_segment(r0b - th // 2, h_left, th, h_right - h_left + 1)
                # Vertical connector
                if r0a < r1b:
                    vc = r1a + 1
                    vh = r0b - r1a - 1
                elif r1a > r0b:
                    vc = r1b + 1
                    vh = r0a - r1b - 1
                else:
                    vc = max(r0a, r0b)
                    vh = 1
                paint_segment(vc, v_col - tw // 2, max(vh, 1), tw)

        # Mark this box connected; if the anchor was not connected, mark it too.
        connected.add(best_box)
        connected.add(best_anchor)

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import sys
    sys.setrecursionlimit(1000000)

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    visited = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if visited[r][c] or grid[r][c] == 7:
                continue

            # Collect one 4-connected component of non-7 cells.
            stack = [(r, c)]
            visited[r][c] = True
            cells = []
            min_r = max_r = r
            min_c = max_c = c

            while stack:
                cr, cc = stack.pop()
                cells.append((cr, cc))
                min_r = min(min_r, cr)
                max_r = max(max_r, cr)
                min_c = min(min_c, cc)
                max_c = max(max_c, cc)

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if not visited[nr][nc] and grid[nr][nc] != 7:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

            rect_h = max_r - min_r + 1
            rect_w = max_c - min_c + 1

            # Only remove landscape rectangular holes:
            # wider than tall, exactly filling their bounding box,
            # and enclosed by 7s (or the grid border).
            if rect_w <= rect_h:
                continue

            # The bounding box must be completely non-7.
            full = True
            for rr in range(min_r, max_r + 1):
                for cc in range(min_c, max_c + 1):
                    if grid[rr][cc] == 7:
                        full = False
                        break
                if not full:
                    break
            if not full:
                continue

            # Check the border just outside the bounding box.
            ok = True

            if min_r > 0:
                for cc in range(min_c, max_c + 1):
                    if grid[min_r - 1][cc] != 7:
                        ok = False
                        break

            if ok and max_r + 1 < h:
                for cc in range(min_c, max_c + 1):
                    if grid[max_r + 1][cc] != 7:
                        ok = False
                        break

            if ok and min_c > 0:
                for rr in range(min_r, max_r + 1):
                    if grid[rr][min_c - 1] != 7:
                        ok = False
                        break

            if ok and max_c + 1 < w:
                for rr in range(min_r, max_r + 1):
                    if grid[rr][max_c + 1] != 7:
                        ok = False
                        break

            if ok:
                for rr in range(min_r, max_r + 1):
                    for cc in range(min_c, max_c + 1):
                        out[rr][cc] = 7

    return out

