                cur += 1
                band_r_start = r
                band_r_end = r
            else:
                band_r_end = r
            band[r] = cur
        else:
            band[r] = -1
    # The above needs band_r_start/end defined; redo cleanly.
    bands = []
    in_band = False
    for r in range(h):
        if np.any(g[r] != 0):
            if not in_band:
                bands.append([r, r])
                in_band = True
            else:
                bands[-1][1] = r
        else:
            in_band = False

    def row_band(r):
        for i, (a, b) in enumerate(bands):
            if a <= r <= b:
                return i
        return -1

    groups = {}
    for border, col, s, e, length in candidates:
        # Use the band of the run itself.
        b = row_band(s)
        key = (border, b)
        groups.setdefault(key, []).append((border, col, s, e, length))

    # For each group, select the candidate whose column is farthest from the
    # average column of the candidates in that group.  Ties go rightmost.
    for key, items in groups.items():
        if not items:
