    return ans.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])
    g = np.array(grid, dtype=int)

    # Background is the most frequent colour.
    vals, cnts = np.unique(g, return_counts=True)
    bg = int(vals[np.argmax(cnts)])

    # Detect cross shapes: top row length 3, middle row length 5, bottom row length 3.
    def is_run(row, start, length, color):
        if start < 0 or start + length > w:
            return False
        return bool(np.all(row[start:start + length] == color))

    crosses = []
    lines = []

    for r in range(h - 2):
        row0 = g[r]
        for c in range(w):
            col = row0[c]
            if col == bg:
                continue
            # top row of cross
            if not is_run(row0, c, 3, col):
                continue
            # find exact run length for top row
            end = c
            while end + 1 < w and g[r][end + 1] == col:
                end += 1
            if end - c + 1 != 3:
                continue
            mc = c + 1
            # middle row
            if not (r + 1 < h and is_run(g[r + 1], mc - 2, 5, col)):
                continue
            # bottom row
            if not (r + 2 < h and is_run(g[r + 2], mc - 1, 3, col)):
                continue
            crosses.append((r, r + 2, c, end, col))

    # Detect bottom horizontal lines of length 5.
    for r in range(h):
        row = g[r]
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            col = row[c]
            e = c
            while e + 1 < w and row[e + 1] == col:
                e += 1
            if e - c + 1 == 5:
                # Ensure it is a standalone run, not part of a cross.
                above = (r - 1 >= 0 and g[r - 1][c:e + 1].any())
                below = (r + 1 < h and g[r + 1][c:e + 1].any())
                if not above and not below:
                    lines.append((r, c, e, col))
            c = e + 1

    out = g.copy()

    # Remove all standalone bottom lines.
    for r, c, e, col in lines:
        out[r, c:e + 1] = bg

    # Helper: draw a 3x5 cross centered at (mr, mc).
    def draw_cross(out_grid, mr, mc, color):
        if mr - 1 < 0 or mr + 1 >= h or mc - 2 < 0 or mc + 2 >= w:
            return
        out_grid[mr - 1, mc - 1:mc + 2] = color
        out_grid[mr, mc - 2:mc + 3] = color
        out_grid[mr + 1, mc - 1:mc + 2] = color

    # Group cross shapes by centre column.
    from collections import defaultdict
    by_col = defaultdict(list)
    for r0, r1, c0, c1, col in crosses:
        mc = (c0 + c1) // 2
        mr = (r0 + r1) // 2
        by_col[mc].append((mr, col))

    for mc, items in by_col.items():
        items.sort()
        # The puzzle instances use one colour per column.
        col = items[0][1]
        centers = [mr for mr, _ in items]

        # Look for a bottom marker under this column.
        marker = None
        for r, c, e, mcol in lines:
            if (c + e) // 2 == mc:
                marker = mcol
                break

        if marker == 2:
            # Recolor every cross in this column to 5.
            for mr, _ in items:
                # Clear old cross cells first (background), then redraw as 5.
                if mr - 1 >= 0 and mr + 1 < h and mc - 2 >= 0 and mc + 2 < w:
                    out[mr - 1, mc - 1:mc + 2] = bg
                    out[mr, mc - 2:mc + 3] = bg
                    out[mr + 1, mc - 1:mc + 2] = bg
                    draw_cross(out, mr, mc, 5)

        elif marker == 3:
            # Extend/fill this column upward.
            # Determine existing vertical slots from all crosses.
            all_centers = sorted({mr for lst in by_col.values() for mr, _ in lst})
            if not all_centers:
                continue

            # Canonical spacing is 4 rows in all supplied cases.
            spacing = 4
            if len(all_centers) >= 2:
                diffs = sorted({all_centers[i + 1] - all_centers[i] for i in range(len(all_centers) - 1)})
                if diffs:
                    spacing = diffs[0]

            existing = set(centers)

            # Fill missing slots between the lowest and highest globally present slot.
            for rc in all_centers:
                if rc not in existing:
                    draw_cross(out, rc, mc, col)
                    existing.add(rc)

            # If the column already occupied the topmost global slot, add one above it.
            if all_centers[0] in existing:
                new_top = all_centers[0] - spacing
                if new_top not in existing and new_top - 1 >= 0:
                    draw_cross(out, new_top, mc, col)
                    existing.add(new_top)

    # Return as a plain nested list of ints.
    return out.astype(int).tolist()

import numpy as np
from collections import defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    g0 = np.array(grid, dtype=int)
    H, W = g0.shape

    # Background is the most frequent color.
    vals, cnts = np.unique(g0, return_counts=True)
    bg = int(vals[np.argmax(cnts)])

    def is_cross_top(r, c, color):
        """True if a cross of given color has its top row starting at (r, c)."""
        if r + 2 >= H or c + 4 >= W:
            return False
        # top row: 3 cells
        if not np.all(g0[r, c:c+3] == color):
            return False
        # middle row: 5 cells
        if not np.all(g0[r+1, c-1:c+4] == color):
            return False
        # bottom row: 3 cells
        if not np.all(g0[r+2, c:c+3] == color):
            return False
        # Ensure the runs are exactly the cross, not wider.
        if c > 0 and g0[r][c-1] == color:
            return False
        if c + 3 < W and g0[r][c+3] == color:
            return False
        if c > 0 and g0[r+1][c-2] == color:
            return False
        if c + 4 < W and g0[r+1][c+4] == color:
            return False
        if c > 0 and g0[r+2][c-1] == color:
            return False
        if c + 3 < W and g0[r+2][c+3] == color:
            return False
        return True

    # Detect all cross shapes. Store center column = c+1, top row r, color.
    crosses = []
    for r in range(H - 2):
        for c in range(W - 4):
            color = int(g0[r, c])
            if color == bg:
                continue
            if is_cross_top(r, c, color):
                crosses.append((r, c + 1, color))

    # Group crosses by center column.
    col_map = defaultdict(list)
    for top, col, color in crosses:
        col_map[col].append((top, color))

    # Detect bottom-row instruction bars: exact length-5 runs.
    instructions = {}
    r = H - 1
    c = 0
    while c < W:
        if g0[r, c] == bg:
            c += 1
            continue
        color = int(g0[r, c])
        start = c
        while c < W and g0[r, c] == color:
            c += 1
        end = c - 1
        if end - start + 1 == 5:
            mid = (start + end) // 2
            instructions[mid] = color

    out = g0.copy()

    # Draw helper for output grid.
    def draw_cross(outg, top, col, color):
        if top < 0 or top + 2 >= H or col - 2 < 0 or col + 2 >= W:
            return
        outg[top, col-1:col+2] = color
        outg[top+1, col-2:col+3] = color
        outg[top+2, col-1:col+2] = color

    # For each column with an instruction, apply it.
    for col, instr in instructions.items():
        if col not in col_map:
            continue

        items = col_map[col]
        # All crosses in the same column are expected to share the same color.
        color = items[0][1]
        tops = sorted(top for top, _ in items)

        if instr == 2:
            # Recolor all crosses in this column to 5.
            for top, _ in items:
                draw_cross(out, top, col, 5)

        elif instr == 3:
            # Determine the vertical slot grid from all crosses.
            all_tops = sorted({top for top, _ in crosses})
            if not all_tops:
                continue

            # Spacing between slots is consistently 4 rows in these puzzles.
            spacing = 4
            if len(all_tops) >= 2:
                diffs = sorted({all_tops[i+1] - all_tops[i] for i in range(len(all_tops)-1)})
                if diffs:
                    spacing = diffs[0]

            # The full vertical extent is from the highest cross to the lowest cross,
            # extended upward by one extra slot only if this column already contains
            # the highest slot and is the leftmost instructed column.
            highest = all_tops[0]
            lowest = all_tops[-1]

            # Candidate slots within the main extent.
            slots = set()
            t = lowest
            while t >= highest:
                slots.add(t)
                t -= spacing

            # Special case observed in Example 1:
            # if the marker-3 column is the leftmost column and it already occupies
            # the topmost main slot, add one additional slot above it.
            if tops and min(tops) == highest:
                # leftmost column among all cross columns
                if col == min(col_map.keys()):
                    slots.add(highest - spacing)

            # Fill all slots in this column with the column's color.
            for top in slots:
                draw_cross(out, top, col, color)

    return out.astype(int).tolist()

