        # Interior must be non-fill-color
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if a[r][c] == fill_color:
                    return False

        # At least a non-trivial rectangular area
        if (r2 - r1 + 1) * (c2 - c1 + 1) <= 1:
            return False

        # The full perimeter around the rectangle must be 7 or outside the grid.
        # This includes the four corners.
        for r in range(r1 - 1, r2 + 2):
            for c in range(c1 - 1, c2 + 2):
                if r < 0 or r >= h or c < 0 or c >= w:
                    continue
                if r1 <= r <= r2 and c1 <= c <= c2:
                    continue
                if a[r][c] != fill_color:
                    return False

        return True

    # Enumerate all possible rectangles. Grids are small (16x16 in the prompt).
    for r1 in range(h):
        for r2 in range(r1, h):
            for c1 in range(w):
                for c2 in range(c1, w):
                    if is_valid(r1, r2, c1, c2):
                        for r in range(r1, r2 + 1):
                            for c in range(c1, c2 + 1):
                                a[r][c] = fill_color

    return a

