from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    n = len(grid)
    m = len(grid[0])
    out = [list(row) for row in grid]

    # The examples show a 2-pixel top and left border.
    # All cells except that border are symmetric:
    #   horizontal: (r, c) <-> (r, m + 1 - c) for c >= 2
    #   vertical:   (r, c) <-> (n + 1 - r, c) for r >= 2
    # Fill zeros by propagating known non-zero colors through these equivalences.

    # Build undirected equivalence graph only for cells involved in symmetries.
    adj = {}
    cells = []

    def node(r, c):
        key = (r, c)
        if key not in adj:
            adj[key] = []
            cells.append(key)
        return key

    def link(a, b):
        u = node(*a)
        v = node(*b)
        if u != v:
            adj[u].append(v)
            adj[v].append(u)

    for r in range(n):
        for c in range(m):
            if r < 2 and c < 2:
                continue
            link((r, c), (r, m + 1 - c)) if c >= 2 else None
            link((r, c), (n + 1 - r, c)) if r >= 2 else None

    # For each component, if any non-zero exists, fill all zeros in it.
    seen = set()
    for start in cells:
        if start in seen:
            continue
        stack = [start]
        comp = []
        seen.add(start)
        value = 0
        while stack:
            cur = stack.pop()
            comp.append(cur)
            if out[cur[0]][cur[1]] != 0:
                if value == 0:
                    value = out[cur[0]][cur[1]]
                # Inputs are consistent; if multiple non-zero values appear,
                # the first one is kept.
            for nxt in adj[cur]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)

        if value != 0:
            for r, c in comp:
                if out[r][c] == 0:
                    out[r][c] = value

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
