    h = len(grid)
    w = len(grid[0])

    # Full separator lines are made of 6s in the visible examples.
    sep_rows = [r for r in range(h) if all(grid[r][c] == 6 for c in range(w))]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 6 for r in range(h))]

    def segments(seps, total):
        cuts = sorted(set([0] + [x + 1 for x in seps if x + 1 < total] + [total]))
        return [(a, b) for a, b in zip(cuts[:-1], cuts[1:]) if b - a > 0]

    row_segs = segments(sep_rows, h)
    col_segs = segments(sep_cols, w)

    m = len(row_segs)
    n = len(col_segs)

