from collections import Counter, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.asarray(grid, dtype=int)
    H, W = a.shape
    ans = a.tolist()

    # If there is only one colour, nothing to do.
    vals, cnts = np.unique(a, return_counts=True)
    if len(vals) <= 1:
        return ans

    # Background is the most frequent colour.
    # Separator is the most frequent non-background colour.
    bg_color = int(vals[np.argmax(cnts)])
    non_bg_counts = Counter()
    for v, c in zip(vals, cnts):
        iv = int(v)
        if iv != bg_color:
            non_bg_counts[iv] = int(c)

    if not non_bg_counts:
        return ans

    sep_color = max(non_bg_counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]

    # Identify 4-connected components of non-separator cells.
    comp_id = -np.ones((H, W), dtype=int)
    comps = []

    for r in range(H):
        for c in range(W):
            if a[r, c] == sep_color or comp_id[r, c] != -1:
                continue

            cid = len(comps)
            q = deque([(r, c)])
            comp_id[r, c] = cid
            cells = []

            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W:
                        if comp_id[ny, nx] == -1 and a[ny, nx] != sep_color:
                            comp_id[ny, nx] = cid
                            q.append((ny, nx))

            comps.append(cells)

    # Distance of every non-separator cell to the boundary of its component.
    # Distance 1 means the cell is Chebyshev-adjacent to a separator,
    # another component, or the outside of the grid.
    dist = -np.ones((H, W), dtype=int)

    for cid, cells in enumerate(comps):
        q = deque()

        # Boundary cells of this component get distance 1.
        for r, c in cells:
            boundary = False
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < H and 0 <= nc < W):
                        boundary = True
                        break
                    if comp_id[nr, nc] != cid:
                        boundary = True
                        break
                if boundary:
                    break

            if boundary:
                dist[r, c] = 1
                q.append((r, c))

        # Propagate inward using 8-neighbourhood, making square/Chebyshev rings.
        while q:
            r, c = q.popleft()
            nd = dist[r, c] + 1
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if comp_id[nr, nc] == cid and dist[nr, nc] == -1:
                            dist[nr, nc] = nd
                            q.append((nr, nc))

    # Fill each component.
    for cells in comps:
        if not cells:
            continue

        # Local background is the most frequent colour inside this component.
        local_counts = Counter()
        for r, c in cells:
            local_counts[int(a[r, c])] += 1

        local_bg = max(local_counts.items(), key=lambda kv: (kv[1], -kv[0]))[0]

        # Marker colours: non-background, non-separator colours in this component.
        marker_info = {}
        for r, c in cells:
            col = int(a[r, c])
            if col == local_bg or col == sep_color:
                continue
            d = int(dist[r, c])
            if d <= 0:
                d = 1

            if col not in marker_info:
                marker_info[col] = (d, r, c)
            else:
                old_d, old_r, old_c = marker_info[col]
                if (d, r, c) < (old_d, old_r, old_c):
                    marker_info[col] = (d, r, c)

        if not marker_info:
            continue

        # Order markers from outer layer to inner layer.
        cycle = [col for col, _ in sorted(marker_info.items(),
                                          key=lambda kv: (kv[1][0], kv[1][1], kv[1][2], kv[0]))]
        L = len(cycle)

        # Paint the component with the repeating layer colours.
        for r, c in cells:
            d = int(dist[r, c])
            if d <= 0:
                d = 1
            ans[r][c] = int(cycle[(d - 1) % L])

    return ans

