from collections import defaultdict, deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])
    g = [list(row) for row in grid]

    # Count colours.
    freq = defaultdict(int)
    for r in range(H):
        for c in range(W):
            freq[g[r][c]] += 1

    # Background: most frequent colour (tie: lower colour id).
    bg = min(freq.keys(), key=lambda x: (-freq[x], x))

    # Wall colour: prefer a non-background colour with long straight runs,
    # since the separator is drawn as line segments.  Fallback: second most frequent.
    def max_run(color):
        best = 0
        for r in range(H):
            cnt = 0
            for c in range(W):
                if g[r][c] == color:
                    cnt += 1
                    best = max(best, cnt)
                else:
                    cnt = 0
        for c in range(W):
            cnt = 0
            for r in range(H):
                if g[r][c] == color:
                    cnt += 1
                    best = max(best, cnt)
                else:
                    cnt = 0
        return best

    wall = None
    threshold = max(3, min(H, W) // 5)
    candidates = [c for c in freq if c != bg]
    line_candidates = [c for c in candidates if max_run(c) >= threshold]
    if line_candidates:
        wall = max(line_candidates, key=lambda c: (max_run(c), freq[c], -c))
    else:
        if candidates:
            wall = max(candidates, key=lambda c: (freq[c], -c))
        else:
            wall = bg  # no wall: return copy

    # If wall is indistinguishable, nothing to transform.
    if wall is None or wall == bg:
        return [row[:] for row in g]

    # Connected components of non-wall cells.
    comp_id = [[-1] * W for _ in range(H)]
    components = []
    for sr in range(H):
        for sc in range(W):
            if comp_id[sr][sc] != -1 or g[sr][sc] == wall:
                continue
            cid = len(components)
            q = deque([(sr, sc)])
            comp_id[sr][sc] = cid
            cells = []
            minr = maxr = sr
            minc = maxc = sc
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                minr = min(minr, r)
                maxr = max(maxr, r)
                minc = min(minc, c)
                maxc = max(maxc, c)
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if comp_id[nr][nc] == -1 and g[nr][nc] != wall:
                            comp_id[nr][nc] = cid
                            q.append((nr, nc))
            components.append({
                "cells": cells,
                "minr": minr,
                "maxr": maxr,
                "minc": minc,
                "maxc": maxc,
            })

    # For each component, find the best corner diagonal colour sequence.
    # A sequence is the prefix along a corner diagonal until the first
    # background/wall cell after any non-background colour.  If the corner
    # itself is background but the next diagonal cell is a seed, the leading
    # background is kept as the first ring colour.
    def corner_sequence(r0, c0, dr, dc, minr, maxr, minc, maxc):
        seq = []
        saw_bg_start = False
        r, c = r0, c0
        h = maxr - minr + 1
        w = maxc - minc + 1
        for _ in range(min(h, w)):
            if not (minr <= r <= maxr and minc <= c <= maxc):
                break
            val = g[r][c]
            if val == wall:
                break

            if not seq:
                if val == bg:
                    saw_bg_start = True
                else:
                    seq.append(val)
            else:
                if val == bg:
                    break
                seq.append(val)

            r += dr
            c += dc

        if not seq:
            seq = [bg]
        elif saw_bg_start:
            seq = [bg] + seq
        return seq

    out = [row[:] for row in g]

    for comp in components:
        minr, maxr = comp["minr"], comp["maxr"]
        minc, maxc = comp["minc"], comp["maxc"]

        corners = [
            (minr, minc, 1, 1),   # top-left
            (minr, maxc, 1, -1),  # top-right
            (maxr, minc, -1, 1),  # bottom-left
            (maxr, maxc, -1, -1), # bottom-right
        ]

        best_seq = [bg]
        best_score = -1
        for idx, (r0, c0, dr, dc) in enumerate(corners):
            seq = corner_sequence(r0, c0, dr, dc, minr, maxr, minc, maxc)
            # Score: number of non-background colours in the prefix.
            score = sum(1 for x in seq if x != bg)
            # Deterministic tie-break: prefer longer sequence, then listed corner order.
            if score > best_score or (score == best_score and len(seq) > len(best_seq)):
                best_score = score
                best_seq = seq

        # Fill only cells belonging to this component, using its bounding box.
        for r, c in comp["cells"]:
            level = min(r - minr, maxr - r, c - minc, maxc - c)
            out[r][c] = best_seq[level % len(best_seq)]

    return out

