        line_cands = [c for c in non_bg if max_run(c) >= threshold]
        if line_cands:
            wall = max(line_cands, key=lambda c: (max_run(c), freq[c], -c))
        else:
            wall = max(non_bg, key=lambda c: (freq[c], -c))

    # If no usable wall was found, return a copy.
    if wall is None or wall == bg:
        return [row[:] for row in g]

    # ---------------- components ----------------
    comp_id = [[-1] * W for _ in range(H)]
    components = []

    for sr in range(H):
        for sc in range(W):
            if comp_id[sr][sc] != -1 or g[sr][sc] == wall:
                continue

            cid = len(components)
            q = deque([(sr, sc)])
            comp_id[sr][sc] = cid
            cells = []
            minr = maxr = sr
            minc = maxc = sc

            while q:
                r, c = q.popleft()
                cells.append((r, c))
                minr = min(minr, r)
                maxr = max(maxr, r)
                minc = min(minc, c)
                maxc = max(maxc, c)

                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if comp_id[nr][nc] == -1 and g[nr][nc] != wall:
