            if not (minr <= r0 <= maxr and minc <= c0 <= maxc):
                break

            val = g[r0][c0]

            if val == wall:
                break

            if val == bg:
                if seen_non_bg:
                    break
                seq.append(bg)
            else:
                seq.append(val)
                seen_non_bg = True

            r0 += dr
            c0 += dc

        if not seq:
            return [bg], 0, 10**9

        non_bg_count = sum(1 for x in seq if x != bg)
        if non_bg_count == 0:
            return [bg], 0, 10**9

        leading_bg = 0
        for x in seq:
            if x == bg and leading_bg < len(seq) - non_bg_count:
                leading_bg += 1
            else:
                break

