    for comp in components:
        minr, maxr = comp["minr"], comp["maxr"]
        minc, maxc = comp["minc"], comp["maxc"]

        corners = [
            (0, minr, minc, 1, 1),    # top-left
            (1, minr, maxc, 1, -1),   # top-right
            (2, maxr, minc, -1, 1),   # bottom-left
            (3, maxr, maxc, -1, -1),  # bottom-right
        ]

