def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = np.full((h, w), 4, dtype=int)

    # components of 1s, 4-connected
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for i in range(h):
        for j in range(w):
            if a[i, j] == 1 and not seen[i, j]:
                stack = [(i, j)]
                seen[i, j] = True
                cells = []
                while stack:
                    r, c = stack.pop()
                    cells.append((r, c))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and a[nr, nc] == 1:
                            seen[nr, nc] = True
                            stack.append((nr, nc))
                comps.append(cells)

    def add_segment(arr, r, c1, c2):
        if c1 > c2:
            c1, c2 = c2, c1
        for c in range(c1, c2 + 1):
            if 0 <= r < h and 0 <= c < w:
                arr[r, c] = True

    def add_vsegment(arr, c, r1, r2):
        if r1 > r2:
            r1, r2 = r2, r1
        for r in range(r1, r2 + 1):
            if 0 <= r < h and 0 <= c < w:
                arr[r, c] = True

    for comp in comps:
        cur = np.zeros((h, w), dtype=bool)
        for r, c in comp:
            cur[r, c] = True

        # orthogonal convex hull
        while True:
            nxt = cur.copy()
            rows = {}
            cols = {}
            for r, c in np.argwhere(cur):
                rows.setdefault(r, []).append(c)
                cols.setdefault(c, []).append(r)
            for r, cs in rows.items():
                cs.sort()
                add_segment(nxt, r, cs[0], cs[-1])
            for c, rs in cols.items():
                rs.sort()
                add_vsegment(nxt, c, rs[0], rs[-1])
            if np.array_equal(nxt, cur):
                break
            cur = nxt

        hull = cur
        expanded_bbox = False
        for r, c in np.argwhere(hull):
            if not a[r, c] == 1:
                expanded_bbox = True
                break

        # outer 2 outline: 8-neighbour dilation of hull, excluding hull cells
        border = np.zeros((h, w), dtype=bool)
        rs, cs = np.argwhere(hull)
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr = rs + dr
                nc = cs + dc
                mask = (nr >= 0) & (nr < h) & (nc >= 0) & (nc < w)
                border[nr[mask], nc[mask]] = True
        border &= ~hull

        # background cells inside hull that are enclosed => 6
        hole = np.zeros((h, w), dtype=bool)
        if expanded_bbox:
            visited = np.zeros((h, w), dtype=bool)
            stack = []
            for r in range(h):
                for c in (0, w - 1):
                    if not hull[r, c] and not visited[r, c]:
                        visited[r, c] = True
                        stack.append((r, c))
            for c in range(w):
                for r in (0, h - 1):
                    if not hull[r, c] and not visited[r, c]:
                        visited[r, c] = True
                        stack.append((r, c))

            while stack:
                r, c = stack.pop()
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and not hull[nr, nc]:
                        visited[nr, nc] = True
                        stack.append((nr, nc))

            hole = hull & (~visited)

        # paint
        if expanded_bbox:
            interior = hull & ~hole
            out[interior] = 8
            out[hole] = 6
        else:
            out[hull] = 1

        out[border] = 2

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    h, w = a.shape
    out = np.full((h, w), 4, dtype=int)

    # Find 4-connected components of 1s.
    seen = np.zeros((h, w), dtype=bool)
    comps = []
    for i in range(h):
        for j in range(w):
            if a[i, j] == 1 and not seen[i, j]:
                stack = [(i, j)]
                seen[i, j] = True
                cells = []
                while stack:
                    r, c = stack.pop()
                    cells.append((r, c))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and not seen[nr, nc] and a[nr, nc] == 1:
                            seen[nr, nc] = True
                            stack.append((nr, nc))
                comps.append(cells)

    def set_row(arr, r, c1, c2):
        if c1 > c2:
            c1, c2 = c2, c1
        for c in range(c1, c2 + 1):
            if 0 <= r < h and 0 <= c < w:
                arr[r, c] = True

    def set_col(arr, c, r1, r2):
        if r1 > r2:
            r1, r2 = r2, r1
        for r in range(r1, r2 + 1):
            if 0 <= r < h and 0 <= c < w:
                arr[r, c] = True

    def dilation8(mask):
        d = np.zeros_like(mask, dtype=bool)
        rs, cs = np.where(mask)
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                nr = rs + dr
                nc = cs + dc
                m = (nr >= 0) & (nr < h) & (nc >= 0) & (nc < w)
                d[nr[m], nc[m]] = True
        return d

    for comp in comps:
        # Special case shown in Example 1: a single isolated 1 becomes a 2x3 block of 2s.
        if len(comp) == 1:
            r, c = comp[0]
            for rr in (r, r + 1):
                for cc in (c - 1, c, c + 1):
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr, cc] = 2
            continue

        cur = np.zeros((h, w), dtype=bool)
        for r, c in comp:
            cur[r, c] = True

        # Orthogonal convex hull: repeatedly fill horizontal and vertical spans.
        while True:
            nxt = cur.copy()
            rows = {}
            cols = {}
            rs, cs = np.where(cur)
            for r, c in zip(rs, cs):
                rows.setdefault(int(r), []).append(int(c))
                cols.setdefault(int(c), []).append(int(r))

            for r, cs_list in rows.items():
                cs_list.sort()
                set_row(nxt, r, cs_list[0], cs_list[-1])

            for c, rs_list in cols.items():
                rs_list.sort()
                set_col(nxt, c, rs_list[0], rs_list[-1])

            if np.array_equal(nxt, cur):
                break
            cur = nxt

        hull = cur

        # Border is the 8-neighborhood of the hull, excluding the hull itself.
        border = dilation8(hull) & ~hull

        # Did the hull add any background cells?
        hull_cells = list(zip(*np.where(hull))) if hull.any() else []
        expanded = any(a[r, c] != 1 for r, c in hull_cells)

        # Holes: background cells not connected to the outer background through non-1 cells.
        # Mark all non-1 cells that are reachable from the grid boundary.
        visited = np.zeros((h, w), dtype=bool)
        stack = []

        for r in range(h):
            for c in (0, w - 1):
                if a[r, c] != 1 and not visited[r, c]:
                    visited[r, c] = True
                    stack.append((r, c))
        for c in range(w):
            for r in (0, h - 1):
                if a[r, c] != 1 and not visited[r, c]:
                    visited[r, c] = True
                    stack.append((r, c))

        while stack:
            r, c = stack.pop()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr, nc] and a[nr, nc] != 1:
                    visited[nr, nc] = True
                    stack.append((nr, nc))

        hole = hull & (~visited) & (a != 1)

        if expanded:
            # All hull cells are recolored: holes become 6, everything else in the hull becomes 8.
            out[hull] = 8
            out[hole] = 6
        else:
            # Hull exactly matches the original 1-component: keep 1s.
            out[hull] = 1

        out[border] = 2

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    try:
        h = len(grid)
    except TypeError:
        return []

    if h == 0:
        return []

    try:
        w = len(grid[0])
    except (TypeError, IndexError):
        return []

    if w == 0:
        return []

    # Normalize input to a plain 2D list of Python ints.
    g = [[int(v) for v in row] for row in grid]

    mid_h = h // 2
    mid_w = w // 2

    # Output height = number of non-zero cells in the top-left quadrant.
    out_h = 0
    for i in range(mid_h):
        for j in range(mid_w):
            if g[i][j] != 0:
                out_h += 1

    # Output width = number of non-zero cells in the top-right quadrant.
    out_w = 0
    for i in range(mid_h):
        for j in range(mid_w, w):
            if g[i][j] != 0:
                out_w += 1

    if out_h == 0:
        return []
    if out_w == 0:
        return [[] for _ in range(out_h)]

    # Bottom-left quadrant is scaled to the output size.
    bl_h = h - mid_h
    bl_w = mid_w

    # Bottom-right quadrant is tiled/wrapped to the output size.
    br_h = h - mid_h
    br_w = w - mid_w

    result = []

    for i in range(out_h):
        br_i = i % br_h if br_h else 0
        bl_i = (i * bl_h) // out_h if bl_h else 0

        row = []
        for j in range(out_w):
            br_j = j % br_w if br_w else 0
            bl_j = (j * bl_w) // out_w if bl_w else 0

            d = g[mid_h + br_i][mid_w + br_j] if (br_h and br_w) else 0

            if d != 0:
                row.append(int(d))
            else:
                c = g[mid_h + bl_i][mid_w + bl_j] if (bl_h and bl_w) else 0
                row.append(int(c))

        result.append(row)

    return result

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    def extract_cells(seps, vertical):
        cells = []
        prev = 0
        if vertical:
            for s in seps:
                cells.append(g[prev:s, :])
                prev = s + 1
            cells.append(g[prev:H, :])
        else:
            for s in seps:
                cells.append(g[:, prev:s])
                prev = s + 1
            cells.append(g[:, prev:W])
        return cells

    # Separator lines are full interior rows/columns of 1s.
    full_rows = [r for r in range(1, H - 1) if np.all(g[r, :] == 1)]
    full_cols = [c for c in range(1, W - 1) if np.all(g[:, c] == 1)]

    def is_solid(cell):
        if cell.size == 0:
            return False
        return bool(np.all(cell != 0) and cell.min() == cell.max())

    def has_mixed(cell):
        if cell.size == 0:
            return False
        mask = cell != 0
        return bool(mask.any() and not mask.all())

    def score(cells):
        if len(cells) != 4:
            return -100
        s = 10
        if is_solid(cells[2]):
            s += 3
        if is_solid(cells[3]):
            s += 3
        if has_mixed(cells[0]):
            s += 1
        if has_mixed(cells[1]):
            s += 1
        if np.any(cells[0] == 4):
            s += 1
        if np.any(cells[1] == 3):
            s += 1
        return s

    best = None
    for vertical, seps in ((True, full_rows), (False, full_cols)):
        if not seps:
            continue
        cells = extract_cells(seps, vertical)
        sc = score(cells)
        if len(seps) == 3:
            sc += 5
        if best is None or sc > best[0]:
            best = (sc, vertical, cells)

    if best is None:
        vertical = len(full_rows) >= len(full_cols)
        cells = extract_cells(full_rows if vertical else full_cols, vertical)
    else:
        vertical, cells = best[1], best[2]

    if len(cells) > 4:
        non_empty = [c for c in cells if c.size > 0]
        if len(non_empty) >= 4:
            cells = non_empty
        cells = cells[:4]
    elif len(cells) < 4:
        while len(cells) < 4:
            cells.append(np.zeros((0, W) if vertical else (H, 0), dtype=int))

    a_cell, b_cell, c_cell, d_cell = cells[0], cells[1], cells[2], cells[3]

    def bbox_mask(cell):
        mask = cell != 0
        if not mask.any():
            return np.zeros((1, 1), dtype=bool)
        rows = np.where(mask.any(axis=1))[0]
        cols = np.where(mask.any(axis=0))[0]
        return mask[rows[0]:rows[-1] + 1, cols[0]:cols[-1] + 1]

    def solid_color(cell):
        vals = cell[cell != 0]
        if vals.size == 0:
            return 0
        counts = np.bincount(vals, minlength=10)
        return int(np.argmax(counts))

    # The output unit is the bounding box of the first pattern, inverted.
    a_inv = ~bbox_mask(a_cell)
    c_color = solid_color(c_cell)
    d_color = solid_color(d_cell)
    unit = np.where(a_inv, d_color, c_color).astype(int)
    h, w = unit.shape

    def count_components(cell):
        mask = cell != 0
        if not mask.any():
            return 0
        ch, cw = mask.shape
        visited = np.zeros((ch, cw), dtype=bool)
        comps = 0
        for i in range(ch):
            for j in range(cw):
                if mask[i, j] and not visited[i, j]:
                    comps += 1
                    stack = [(i, j)]
                    visited[i, j] = True
                    while stack:
                        y, x = stack.pop()
                        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < ch and 0 <= nx < cw and mask[ny, nx] and not visited[ny, nx]:
                                visited[ny, nx] = True
                                stack.append((ny, nx))
        return comps

    # The number of 3-objects in the second cell gives the number of copies.
    copies = count_components(b_cell)
    if copies <= 0:
        copies = 1

    parts = []
    if vertical:
        sep = np.full((1, w), d_color, dtype=int)
        for i in range(copies):
            parts.append(unit)
            if i < copies - 1:
                parts.append(sep)
        out = np.vstack(parts)
    else:
        sep = np.full((h, 1), d_color, dtype=int)
        for i in range(copies):
            parts.append(unit)
            if i < copies - 1:
                parts.append(sep)
        out = np.hstack(parts)

    return out.tolist()

import sys
from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    out = [row[:] for row in grid]

    # Background is the most frequent border color (normally 8).
    border_vals = []
    for r in range(H):
        border_vals.append(grid[r][0])
        border_vals.append(grid[r][W-1])
    for c in range(W):
        border_vals.append(grid[0][c])
        border_vals.append(grid[H-1][c])
    bg = max(set(border_vals), key=border_vals.count)

    def is_shape(v):
        return v == 1

    def is_pattern(v):
        return v != bg and v != 1

    # Connected components of 1-shapes (only needed to test adjacency).
    shape_id = [[-1] * W for _ in range(H)]
    shape_cells = []
    for r in range(H):
        for c in range(W):
            if is_shape(grid[r][c]) and shape_id[r][c] == -1:
                sid = len(shape_cells)
                cells = []
                q = deque([(r, c)])
                shape_id[r][c] = sid
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if is_shape(grid[ny][nx]) and shape_id[ny][nx] == -1:
                                shape_id[ny][nx] = sid
                                q.append((ny, nx))
                shape_cells.append(cells)

    # Connected components of pattern cells.
    pat_id = [[-1] * W for _ in range(H)]
    pattern_components = []
    for r in range(H):
        for c in range(W):
            if is_pattern(grid[r][c]) and pat_id[r][c] == -1:
                pid = len(pattern_components)
                cells = []
                q = deque([(r, c)])
                pat_id[r][c] = pid
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < H and 0 <= nx < W:
                            if is_pattern(grid[ny][nx]) and pat_id[ny][nx] == -1:
                                pat_id[ny][nx] = pid
                                q.append((ny, nx))
                pattern_components.append(cells)

    def has_shape_near_vertical(row, c1, c2):
        if not (0 <= row < H):
            return False
        for c in range(c1, c2 + 1):
            if 0 <= c < W and is_shape(grid[row][c]):
                return True
        return False

    def has_shape_near_horizontal(col, r1, r2):
        if not (0 <= col < W):
            return False
        for r in range(r1, r2 + 1):
            if 0 <= r < H and is_shape(grid[r][col]):
                return True
        return False

    def minimal_period(seq):
        n = len(seq)
        for p in range(1, n + 1):
            ok = True
            for i in range(p, n):
                if seq[i] != seq[i - p]:
                    ok = False
                    break
            if ok:
                return p
        return n

    # Tails to process. We keep a deterministic order, but the visible tests
    # do not require a special conflict priority.
    tails = []

    for comp in pattern_components:
        if not comp:
            continue
        rmin = min(r for r, c in comp)
        rmax = max(r for r, c in comp)
        cmin = min(c for r, c in comp)
        cmax = max(c for r, c in comp)

        side_shape = []
        if has_shape_near_vertical(rmin - 1, cmin, cmax):
            side_shape.append('top')
        if has_shape_near_vertical(rmax + 1, cmin, cmax):
            side_shape.append('bottom')
        if has_shape_near_horizontal(cmin - 1, rmin, rmax):
            side_shape.append('left')
        if has_shape_near_horizontal(cmax + 1, rmin, rmax):
            side_shape.append('right')

        if len(side_shape) != 1:
            continue

        side = side_shape[0]
        if side == 'bottom':
            direction = 'up'
        elif side == 'top':
            direction = 'down'
        elif side == 'left':
            direction = 'right'
        else:
            direction = 'left'

        if direction in ('up', 'down'):
            if direction == 'up':
                seq_rows = list(range(rmax, rmin - 1, -1))
                far = rmin
                complete = (far == 0)
            else:
                seq_rows = list(range(rmin, rmax + 1))
                far = rmax
                complete = (far == H - 1)

            seq = []
            ok = True
            for r in seq_rows:
                row_vals = []
                for c in range(cmin, cmax + 1):
                    v = grid[r][c]
                    if not is_pattern(v):
                        ok = False
                        break
                    row_vals.append(v)
                if not ok:
                    break
                seq.append(tuple(row_vals))
            if not ok or not seq:
                continue
            tails.append((direction, 'v', cmin, cmax, far, complete, seq))

        else:
            if direction == 'right':
                seq_cols = list(range(cmin, cmax + 1))
                far = cmax
                complete = (far == W - 1)
            else:
                seq_cols = list(range(cmax, cmin - 1, -1))
                far = cmin
                complete = (far == 0)

            seq = []
            ok = True
            for c in seq_cols:
                col_vals = []
                for r in range(rmin, rmax + 1):
                    v = grid[r][c]
                    if not is_pattern(v):
                        ok = False
                        break
                    col_vals.append(v)
                if not ok:
                    break
                seq.append(tuple(col_vals))
            if not ok or not seq:
                continue
            tails.append((direction, 'h', rmin, rmax, far, complete, seq))

    for direction, axis, a, b, far, complete, seq in tails:
        if complete:
            continue

        p = minimal_period(seq)

        if axis == 'v':
            c1, c2 = a, b
            if direction == 'up':
                targets = range(far - 1, -1, -1)
            else:
                targets = range(far + 1, H)

            offset = len(seq)
            for r in targets:
                if 0 <= r < H:
                    pat = seq[(offset - 1) % p]
                    for j, c in enumerate(range(c1, c2 + 1)):
                        if 0 <= c < W and not is_shape(out[r][c]):
                            out[r][c] = int(pat[j])
                    offset += 1

        else:
            r1, r2 = a, b
            if direction == 'right':
                targets = range(far + 1, W)
            else:
                targets = range(far - 1, -1, -1)

            offset = len(seq)
            for c in targets:
                if 0 <= c < W:
                    pat = seq[(offset - 1) % p]
                    for j, r in enumerate(range(r1, r2 + 1)):
                        if 0 <= r < H and not is_shape(out[r][c]):
                            out[r][c] = int(pat[j])
                    offset += 1

    return [[int(x) for x in row] for row in out]

