from collections import deque

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    H = len(grid)
    W = len(grid[0])
    inp = [[int(x) for x in row] for row in grid]

    out = [row[:] for row in inp]

    colors = sorted({inp[r][c] for r in range(H) for c in range(W)
                     if inp[r][c] not in (0, 2, 4)})

    def inside(r, c):
        return 0 <= r < H and 0 <= c < W

    # For each non-placeholder color, infer horizontal/vertical line supports.
    # - normal cells of that color are strong supports
    # - 2 and 4 are placeholder cells that may be used if adjacent to the color
    #   in the same row/column
    # - 4 additionally extends to the grid edge in the direction away from the
    #   existing color support, which matches the examples where 4 opens a
    #   line to the border.
    for color in colors:
        anchors = {}
        for r in range(H):
            for c in range(W):
                if inp[r][c] == color:
                    anchors[(r, c)] = 1
        for r in range(H):
            for c in range(W):
                if inp[r][c] in (2, 4):
                    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        rr, cc = r + dr, c + dc
                        if inside(rr, cc) and inp[rr][cc] == color:
                            anchors[(r, c)] = 1
                            break

        # Horizontal spans.
        for r in range(H):
            cols = sorted(c for (rr, c) in anchors if rr == r)
            if len(cols) >= 2:
                for c in range(cols[0], cols[-1] + 1):
                    out[r][c] = color
        # Vertical spans.
        for c in range(W):
            rows = sorted(r for (r, cc) in anchors if cc == c)
            if len(rows) >= 2:
                for r in range(rows[0], rows[-1] + 1):
                    out[r][c] = color

        # 4-cell extension: if a 4 is anchored by a color on one side,
        # extend the line to the edge on the opposite side.
        for r in range(H):
            for c in range(W):
                if inp[r][c] != 4:
                    continue
                # vertical
                if inside(r - 1, c) and inp[r - 1][c] == color and not (inside(r + 1, c) and inp[r + 1][c] == color):
                    for rr in range(r, H):
                        out[rr][c] = color
                if inside(r + 1, c) and inp[r + 1][c] == color and not (inside(r - 1, c) and inp[r - 1][c] == color):
                    for rr in range(r, -1, -1):
                        out[rr][c] = color
                # horizontal
                if inside(r, c - 1) and inp[r][c - 1] == color and not (inside(r, c + 1) and inp[r][c + 1] == color):
                    for cc in range(c, W):
                        out[r][cc] = color
                if inside(r, c + 1) and inp[r][c + 1] == color and not (inside(r, c - 1) and inp[r][c - 1] == color):
                    for cc in range(c, -1, -1):
                        out[r][cc] = color

    # Resolve overlaps.
    # The rule inferred from the examples:
    # - if a cell is claimed by several completed lines, prefer the line whose
    #   cell was not already present in that color in the input;
    # - if all/tie, prefer the smaller color id (stable and deterministic).
    for r in range(H):
        for c in range(W):
            claimers = set()
            # A color claims a cell if the cell lies on one of its completed
            # horizontal/vertical spans.  We recompute lightweight claim sets.
            for color in colors:
                # horizontal
                cols = [cc for cc in range(W) if inp[r][cc] == color]
                if not cols:
                    # placeholder adjacent anchors can also claim; use out row
                    # after first fill for this color only if it was set.
                    if out[r][c] == color:
                        claimers.add(color)
                    continue
                if cols[0] <= c <= cols[-1]:
                    claimers.add(color)
                # vertical
                rows = [rr for rr in range(H) if inp[rr][c] == color]
                if rows and rows[0] <= r <= rows[-1]:
                    claimers.add(color)
                # If the cell was explicitly set by 4-extension/placeholder
                # even without two raw anchors, keep it as a claimer.
                if out[r][c] == color:
                    claimers.add(color)

            if not claimers:
                continue

            present = [color for color in claimers if inp[r][c] == color]
            absent = [color for color in claimers if inp[r][c] != color]
            if absent:
                best = min(absent)
            else:
                best = min(claimers)
            out[r][c] = best

    # Remove placeholder colors in the final output.
    for r in range(H):
        for c in range(W):
            if out[r][c] in (2, 4):
                out[r][c] = 0

    return [[int(out[r][c]) for c in range(W)] for r in range(H)]

