def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape
    N = max(h, w)
    S = N + 2  # implicit 32x32 symmetry size for 30x30 inputs

    # Collect all masked cells.  In this task the mask colour is 8.
    mask_cells = [(r, c) for r in range(h) for c in range(w) if g[r, c] == 8]
    if not mask_cells:
        return [[int(x) for x in row] for row in g]

    r0 = min(r for r, _ in mask_cells)
    r1 = max(r for r, _ in mask_cells)
    c0 = min(c for _, c in mask_cells)
    c1 = max(c for _, c in mask_cells)

    # Rebuild values in the masked rectangle using the implicit 32x32
    # 180-degree rotational symmetry: (r, c) <-> (S-1-r, S-1-c).
    out = [[8] * (c1 - c0 + 1) for _ in range(r1 - r0 + 1)]

    def get(r, c):
        if 0 <= r < h and 0 <= c < w:
            return g[r, c]
        return None

    # Iterate a few times: some cells can be filled directly, others only
    # after their symmetric partner has been filled.
    for _ in range(4):
        for dr, r in enumerate(range(r0, r1 + 1)):
            for dc, c in enumerate(range(c0, c1 + 1)):
                if out[dr][dc] != 8:
                    continue
                sr, sc = S - 1 - r, S - 1 - c
                val = get(sr, sc)
                if val is not None and val != 8:
                    out[dr][dc] = int(val)
                else:
                    # If the partner is already reconstructed in the mask,
                    # use it.
                    if 0 <= sr - r0 < len(out) and 0 <= sc - c0 < len(out[0]):
                        pv = out[sr - r0][sc - c0]
                        if pv != 8:
                            out[dr][dc] = pv

    # Fallback: if any 8s remain because they touch the implicit missing
    # border, use the nearest recoverable value in the same row/column if
    # possible; otherwise leave them as 8.  The supplied examples and
    # well-formed tests should not rely on this fallback.
    for dr in range(len(out)):
        row = out[dr]
        for dc in range(len(row)):
            if row[dc] != 8:
                continue
            # nearest non-8 in row
            for off in range(1, len(row)):
                if 0 <= dc - off and row[dc - off] != 8:
                    row[dc] = row[dc - off]
                    break
                if dc + off < len(row) and row[dc + off] != 8:
                    row[dc] = row[dc + off]
                    break
        else:
            continue
        continue

    for dc in range(len(out[0])):
        col = [out[dr][dc] for dr in range(len(out))]
        for dr in range(len(col)):
            if col[dr] != 8:
                continue
            for off in range(1, len(col)):
                if 0 <= dr - off and col[dr - off] != 8:
                    out[dr][dc] = col[dr - off]
                    break
                if dr + off < len(col) and col[dr + off] != 8:
                    out[dr][dc] = col[dr + off]
                    break

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    w = len(grid[0])

    # background is the dominant non-special colour
    from collections import Counter
    cnt = Counter(grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != 2)
    bg = cnt.most_common(1)[0][0]

    out = [[bg] * w for _ in range(h)]

    # Find the 2 markers and the lines they imply.
    v_lines = set()
    h_lines = set()
    v_edge = None
    h_edge = None

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if r == 0 or r == h - 1:
                v_lines.add(c)
                v_edge = "T" if r == 0 else "B"
            if c == 0 or c == w - 1:
                h_lines.add(r)
                h_edge = "L" if c == 0 else "R"

    # Fixed 7-cells are those lying on any marker line.
    def is_fixed(r, c):
        return c in v_lines or r in h_lines

    # Collect 7-cells and split into regions separated by marker lines.
    # A region is a maximal 4-connected component of non-fixed 7 cells.
    visited = [[False] * w for _ in range(h)]
    regions = []

    def region_component(r0, c0):
        stack = [(r0, c0)]
        cells = []
        visited[r0][c0] = True
        while stack:
            r, c = stack.pop()
            cells.append((r, c))
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if not visited[nr][nc] and grid[nr][nc] == 7 and not is_fixed(nr, nc):
                        visited[nr][nc] = True
                        stack.append((nr, nc))
        return cells

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7 and not is_fixed(r, c) and not visited[r][c]:
                regions.append(region_component(r, c))

    # Determine which corner a region belongs to.
    #
    # The corner is determined by the sides of the region relative to the
    # marker lines, with the marker edge supplying the side that is otherwise
    # unknown.  For the test cases and examples this is:
    #   - top/bottom 2 gives the vertical edge (T/B)
    #   - left/right 2 gives the horizontal edge (L/R)
    #   - if both lines exist, use the region's actual side of each line.
    #
    # If a region lies on the "inactive" side of a marker pair, it is omitted.
    corners = []

    for cells in regions:
        rs = [r for r, _ in cells]
        cs = [c for _, c in cells]
        top = min(rs)
        bot = max(rs)
        left = min(cs)
        right = max(cs)

        # Decide vertical corner side.
        # If there is a horizontal line, use whether region is above/below it.
        # If not, use the vertical marker edge (top/bottom 2).
        if h_lines:
            # Use the first horizontal line; puzzle inputs have at most one in practice.
            hl = next(iter(h_lines))
            vert = "T" if bot < hl else "B"
        elif v_edge in ("T", "B"):
            vert = v_edge
        else:
            # No lines: no movement
            continue

        # Decide horizontal corner side.
        # If there is a vertical line, use whether region is left/right of it.
        # If not, use the horizontal marker edge (left/right 2).
        if v_lines:
            vl = next(iter(v_lines))
            horiz = "L" if right < vl else "R"
        elif h_edge in ("L", "R"):
            horiz = h_edge
        else:
            continue

        # A region is moved only if at least one of its two corner edges is
        # actively marked by a 2.
        active = False
        if (vert == "T" and v_edge == "T") or (vert == "B" and v_edge == "B"):
            active = True
        if (horiz == "L" and h_edge == "L") or (horiz == "R" and h_edge == "R"):
            active = True

        if not active:
            continue

        # Translate this component's bounding box into the chosen corner.
        height = bot - top + 1
        width = right - left + 1

        if vert == "T":
            tr = 0
        else:
            tr = h - height

        if horiz == "L":
            tc = 0
        else:
            tc = w - width

        for (r, c) in cells:
            nr = tr + (r - top)
            nc = tc + (c - left)
            out[nr][nc] = 7

    # Place fixed 7-cells.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7 and is_fixed(r, c):
                out[r][c] = 7

    # Draw 2-rays from each marker to the farthest 7 in that line.
    # The ray stops just after the farthest original 7 in that line, but keeps
    # any original 7s on the line.
    def fill_line(line, vertical):
        if vertical:
            c = line
            cols7 = [r for r in range(h) if grid[r][c] == 7]
            if not cols7:
                # If no 7s, draw the whole line with 2?  In examples there are always 7s.
                start = 0
                end = h - 1
            else:
                far = max(cols7)
                near = min(cols7)
                # Ray starts at marker edge and proceeds inward to farthest 7.
                if v_edge == "T":
                    start, end = 0, far
                else:
                    start, end = far, h - 1
            for r in range(start, end + 1):
                if grid[r][c] != 7:
                    out[r][c] = 2
        else:
            r = line
            rows7 = [c for c in range(w) if grid[r][c] == 7]
            if not rows7:
                start = 0
                end = w - 1
            else:
                far = max(rows7)
                if h_edge == "L":
                    start, end = 0, far
                else:
                    start, end = far, w - 1
            for c in range(start, end + 1):
                if grid[r][c] != 7:
                    out[r][c] = 2

    for c in v_lines:
        fill_line(c, True)
    for r in h_lines:
        fill_line(r, False)

    return out

