def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    out = g.copy()

    H, W = g.shape

    # Fixed layout positions for the 3x3 tiles in these puzzles.
    top_row_start = 1
    lower_row_starts = [8, 13, 18, 23]
    col_starts = [2, 7, 12, 17]

    def tile(r0, c0):
        return tuple(int(x) for x in g[r0:r0+3, c0:c0+3].flatten())

    top_tiles = [tile(top_row_start, c) for c in col_starts]
    top_patterns = [t for t in top_tiles if any(v != 8 for v in t)]
    top_set = frozenset(top_patterns)

    def lower_tile(r0, c0):
        return tile(r0, c0)

    # Mark every lower tile that exactly matches one of the non-empty top tiles.
    matched_positions = set()
    for ri, r0 in enumerate(lower_row_starts):
        for ci, c0 in enumerate(col_starts):
            t = lower_tile(r0, c0)
            if t in top_set:
                matched_positions.add((ri, ci))

    # Draw 5x5 highlight boxes around matched lower tiles.
    for ri, ci in matched_positions:
        r0 = lower_row_starts[ri]
        c0 = col_starts[ci]
        box = out[r0-1:r0+4, c0-1:c0+4]
        box[box == 8] = 3

    # Decide whether the top patterns form an exact row or column in the lower 4x4 area.
    line_true = False
    if len(top_patterns) == 4:
        top_sorted = tuple(sorted(top_patterns))

        for ri, r0 in enumerate(lower_row_starts):
            row_tuple = tuple(sorted(tile(r0, c0) for c0 in col_starts))
            if row_tuple == top_sorted:
                line_true = True
                break

        if not line_true:
            for c0 in col_starts:
                col_tuple = tuple(sorted(tile(r0, c0) for r0 in lower_row_starts))
                if col_tuple == top_sorted:
                    line_true = True
                    break

    # If the top row is a complete matching line, fill the whole top band.
    if line_true:
        top_band = out[0:5, :]
        top_band[top_band == 8] = 3

    # Bottom status rows: 3 for a matching line, otherwise 2.
    if H >= 29 and W > 0:
        out[H-2:H, :] = 3 if line_true else 2

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # The 3x3 glyph blocks are in these row bands and column blocks.
    bands = [(1, 0), (8, 1), (13, 2), (18, 3), (23, 4)]
    cols = [2, 7, 12, 17]

    def get_pat(rt, ct):
        return g[rt:rt + 3, ct:ct + 3].copy()

    def nonblank(pat):
        return (pat != 8).any()

    def dist(p, q):
        return int((p != q).sum())

    # Collect lower glyphs (bands 1-4).
    lower = []
    for band_idx in range(1, 5):
        rt, _ = bands[band_idx]
        for col_idx, ct in enumerate(cols):
            lower.append((band_idx, col_idx, rt, ct, get_pat(rt, ct)))

    top_patterns = []
    rt_top, _ = bands[0]
    for col_idx, ct in enumerate(cols):
        pat = get_pat(rt_top, ct)
        top_patterns.append((col_idx, ct, pat))

    # Choose the same fill colour used by the examples.
    highlight = 3
    bottom_fill = 2

    # For each non-empty top glyph, choose its nearest lower glyph of the same colour.
    selected_lower = []
    selected_lower_ids = set()
    for _, _, top_pat in top_patterns:
        if not nonblank(top_pat):
            continue
        c = int(top_pat[0, 0])
        # In this puzzle every non-background glyph pixel has the same colour.
        candidates = [x for x in lower if int(x[4][0, 0]) == c]
        if not candidates:
            continue

        def score(x):
            d = dist(top_pat, x[4])
            return (d, x[0], x[1])

        best = min(candidates, key=score)
        if (best[0], best[1]) not in selected_lower_ids:
            selected_lower_ids.add((best[0], best[1]))
            selected_lower.append(best)

    # Draw 5x5 frames around selected lower glyphs.
    out = g.copy()
    for _, _, rt, ct, _ in selected_lower:
        for r in range(rt - 1, rt + 4):
            for c in range(ct - 1, ct + 4):
                if 0 <= r < H and 0 <= c < W and out[r, c] == 8:
                    out[r, c] = highlight

    # If all selected lower glyphs lie in one lower band, that is the complete-match case.
    complete = False
    if selected_lower:
        band_set = {x[0] for x in selected_lower}
        if len(band_set) == 1:
            complete = True
            # Fill the top zone completely (background cells become highlight colour).
            for r in range(0, 5):
                for c in range(W):
                    if out[r, c] == 8:
                        out[r, c] = highlight

            # In the examples the bottom zone uses the same colour for complete match.
            bottom_fill = highlight

    # Fill the bottom two rows.
    if H >= 29:
        for r in (H - 2, H - 1):
            for c in range(W):
                if out[r, c] == 8:
                    out[r, c] = bottom_fill

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    H = len(grid)
    W = len(grid[0])

    # Work with plain lists of ints.
    old = [list(row) for row in grid]
    out = [row[:] for row in old]

    # Find the left edge of the right-hand 5-border block on the top row.
    start = W - 1
    while start > 0 and old[0][start - 1] == 5:
        start -= 1

    # Interior of the right block:
    # rows 1 .. H-2, columns start+1 .. W-2
    top, bottom = 1, H - 2
    left, right = start + 1, W - 2

    # Clear the source pattern area on the left.
    for r in range(H):
        for c in range(start):
            out[r][c] = 0

    # Scroll the interior of the right block upward by one row.
    # The topmost interior row disappears; the bottommost interior row becomes empty.
    for r in range(top, bottom + 1):
        for c in range(left, right + 1):
            src_r = r + 1
            if src_r <= bottom:
                out[r][c] = old[src_r][c]
            else:
                out[r][c] = 0

    # Stamp the old 5-pattern from the left side into the right block.
    # Left column c maps to right interior column start + 1 + c.
    for r in range(top, bottom + 1):
        for c in range(start):
            if old[r][c] == 5:
                tc = start + 1 + c
                if 0 <= tc < W:
                    out[r][tc] = 5

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])

    zeros = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                zeros.append((r, c))

    if not zeros:
        return [list(row) for row in grid]

    rmin = min(z[0] for z in zeros)
    rmax = max(z[0] for z in zeros)
    cmin = min(z[1] for z in zeros)
    cmax = max(z[1] for z in zeros)

    out_h = rmax - rmin + 1
    out_w = cmax - cmin + 1

    def in_box(r, c):
        return rmin <= r <= rmax and cmin <= c <= cmax

    labels = []
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            v = grid[r][c]
            if v != 0:
                labels.append((r - rmin, c - cmin, v))

    def count_components(color):
        seen = [[False] * w for _ in range(h)]
        count = 0

        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or seen[r][c] or in_box(r, c):
                    continue

                count += 1
                seen[r][c] = True
                stack = [(r, c)]

                while stack:
                    cr, cc = stack.pop()
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue

                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if not seen[nr][nc] and not in_box(nr, nc) and grid[nr][nc] == color:
                                    seen[nr][nc] = True
                                    stack.append((nr, nc))

        return count

    component_counts = {}
    for _, _, color in labels:
        if color not in component_counts:
            component_counts[color] = count_components(color)

    out = [[0] * out_w for _ in range(out_h)]

    for rr, cc, color in labels:
        for i in range(component_counts[color]):
            pos = cc + 2 * i
            if pos >= out_w:
                break
            out[rr][pos] = color

    return out

