from collections import deque, defaultdict

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    h, w = g.shape

    nonzero = g != 0
    if not nonzero.any():
        return g.tolist()

    # connected components of non-background pixels (8-connectivity)
    comps = []
    seen = np.zeros((h, w), dtype=bool)
    for r in range(h):
        for c in range(w):
            if nonzero[r, c] and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            ny, nx = y + dy, x + dx
                            if 0 <= ny < h and 0 <= nx < w and nonzero[ny, nx] and not seen[ny, nx]:
                                seen[ny, nx] = True
                                q.append((ny, nx))
                comps.append(cells)

    if not comps:
        return g.tolist()

    def bbox(cells):
        ys = [p[0] for p in cells]
        xs = [p[1] for p in cells]
        return min(ys), max(ys), min(xs), max(xs)

    # Pick the frame component: largest bounding-box area, tie by size.
    main_idx = max(range(len(comps)), key=lambda i: ( (bbox(comps[i])[1]-bbox(comps[i])[0]+1) *
                                                     (bbox(comps[i])[3]-bbox(comps[i])[2]+1),
                                                     len(comps[i]) ))
    main = comps[main_idx]
    frame_color = max(set(g[y, x] for y, x in main), key=lambda col: sum(1 for y, x in main if g[y, x] == col))
    main_y0, main_y1, main_x0, main_x1 = bbox(main)
    H = main_y1 - main_y0 + 1
    W = main_x1 - main_x0 + 1

    # Main output rectangle: the largest component's bounding box, shifted to origin.
    out = np.zeros((H, W), dtype=int)
    for y, x in main:
        out[y - main_y0, x - main_x0] = g[y, x]

    # Other frame-color cells are "marks".  Move each mark by the same vector
    # as the main frame component was shifted, then keep it if it lies on a
    # one-cell extension of the main rectangle (as in the examples).
    dy_main = -main_y0
    dx_main = -main_x0
    marks = []
    for i, cells in enumerate(comps):
        if i == main_idx:
            continue
        cols = set(g[y, x] for y, x in cells)
        if frame_color in cols:
            for y, x in cells:
                if g[y, x] != frame_color:
                    continue
                ny = y + dy_main
                nx = x + dx_main
                inside = (0 <= ny < H and 0 <= nx < W)
                top = ny == -1 and 0 <= nx < W
                bottom = ny == H and 0 <= nx < W
                left = nx == -1 and 0 <= ny < H
                right = nx == W and 0 <= ny < H
                if inside or top or bottom or left or right:
                    if top or bottom or left or right:
                        if ny < 0:
                            ny = 0
                        if ny >= H:
                            ny = H - 1
                        if nx < 0:
                            nx = 0
                        if nx >= W:
                            nx = W - 1
                    out[ny, nx] = frame_color

    # Non-frame pixels: place all components other than the main frame component
    # using the same shift.  If a non-frame component is not inside the main box,
    # it is not part of the final compact grid.
    for i, cells in enumerate(comps):
        if i == main_idx:
            continue
        for y, x in cells:
            col = g[y, x]
            if col == frame_color:
                continue
            ny = y + dy_main
            nx = x + dx_main
            if 0 <= ny < H and 0 <= nx < W:
                out[ny, nx] = col

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape
    non_zero = a > 0

    # Bounding box of the large object: rows/columns with most non-zero pixels.
    row_sums = non_zero.sum(axis=1)
    col_sums = non_zero.sum(axis=0)
    r1 = int(np.argmax(row_sums))
    r2 = int(H - 1 - np.argmax(row_sums[::-1]))
    c1 = int(np.argmax(col_sums))
    c2 = int(W - 1 - np.argmax(col_sums[::-1]))

    obj = a[r1:r2 + 1, c1:c2 + 1]
    oh, ow = obj.shape

    # Find small instruction cells: non-zero pixels outside the large object bbox.
    mask_out = np.ones_like(non_zero, dtype=bool)
    mask_out[r1:r2 + 1, c1:c2 + 1] = False
    small_mask = non_zero & mask_out

    sy, sx = np.where(small_mask)
    y0 = int(sy.min())
    y1 = int(sy.max())
    x0 = int(sx.min())
    x1 = int(sx.max())
    ky, kx = (y1 - y0 + 1), (x1 - x0 + 1)

    def norm_pos(rr, cc):
        # Position of the color's key component in the 3x3 key layout.
        fy = (rr - y0) / max(ky - 1, 1)
        fx = (cc - x0) / max(kx - 1, 1)
        band = 0 if fy < 1 / 3 else (2 if fy > 2 / 3 else 1)
        colband = 0 if fx < 1 / 3 else (2 if fx > 2 / 3 else 1)
        return band, colband

    def shape_kind(cells):
        if len(cells) <= 1:
            return 0  # single
        rs = {r for r, c in cells}
        cs = {c for r, c in cells}
        if len(cs) == 1:
            return 1  # vertical
        if len(rs) == 1:
            return 2  # horizontal
        return 3

    # Group instruction cells by colour.
    small_by_color = {}
    for r, c in zip(sy, sx):
        small_by_color.setdefault(int(obj_flat_val := a[r, c]), []).append((r, c))

    colors = []
    for val in np.unique(obj):
        if val == 0:
            continue
        if val in small_by_color:
            colors.append(int(val))
        else:
            # Fallback: infer from the dominant non-zero colour in the object.
            colors.append(int(val))
            break

    def flip(mask, mode):
        if mode == 'H':
            return np.fliplr(mask)
        if mode == 'V':
            return np.flipud(mask)
        if mode == '90':
            return np.rot90(mask, k=1)
        if mode == '270':
            return np.rot90(mask, k=3)
        if mode == '180':
            return np.rot90(mask, k=2)
        return mask

    out = np.zeros_like(obj)

    for col in colors:
        mask = (obj == col)
        key_cells = small_by_color.get(col)

        if not key_cells:
            mode = 'none'
        else:
            # Choose the representative cell/component of this colour in the key.
            # If several disconnected components exist for the colour, use the one
            # whose centroid is closest to the key bounding-box centre.
            cys = np.array([r for r, c in key_cells])
            cxs = np.array([c for r, c in key_cells])
            cy = (y0 + y1) / 2.0
            cx = (x0 + x1) / 2.0
            # A cheap connected-components pass for this colour's key cells.
            comps = []
            seen = set()
            for i, (r, c) in enumerate(key_cells):
                if i in seen:
                    continue
                stack = [i]
                comp = []
                seen.add(i)
                while stack:
                    j = stack.pop()
                    rr, cc = key_cells[j]
                    comp.append((rr, cc))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nj = key_cells.index((rr + dr, cc + dc)) if (rr + dr, cc + dc) in key_cells else -1
                            if nj != -1 and nj not in seen:
                                seen.add(nj)
                                stack.append(nj)
                comps.append(comp)

            def comp_centroid(comp):
                return sum(r for r, c in comp) / len(comp), sum(c for r, c in comp) / len(comp)

            comps.sort(key=lambda comp: (comp_centroid(comp)[0] - cy) ** 2 + (comp_centroid(comp)[1] - cx) ** 2)
            rep = comps[0]
            band, colband = norm_pos(*comp_centroid(rep))
            kind = shape_kind(rep)

            # The transformation is taken from the key layout:
            #   top row -> H/V/none, middle -> 90/270, bottom -> 180/V/none
            # Shape refines the exact operation.
            if band == 0:
                if kind == 1:       # vertical mark in top row
                    mode = '180'
                elif kind == 2:     # horizontal mark in top row
                    mode = 'H'
                else:               # single in top row
                    mode = 'H' if colband == 0 else ('V' if colband == 2 else 'none')
            elif band == 1:
                if kind == 1:
                    mode = 'V'
                elif kind == 2:
                    mode = 'H'
                else:
                    mode = '90' if colband >= 1 else '270'
            else:  # band == 2
                if kind == 1:
                    mode = 'V'
                elif kind == 2:
                    mode = 'none'
                else:
                    mode = '180' if colband == 0 else ('V' if colband == 2 else '90')

        out += flip(mask, mode) * col

    return out.astype(int).tolist()

