    cells = [(1, 5, 2, 4), (6, 10, 7, 9), (11, 15, 12, 14), (16, 20, 17, 19)]

    def get_pattern(block_name, cell_idx):
        _, _, grs, gre = blocks[block_name]
        _, _, gcs, gce = cells[cell_idx]
        pat = []
        for r in range(grs, gre + 1):
            row = []
            for c in range(gcs, gce + 1):
                row.append(g[r][c])
            pat.append(tuple(row))
        return tuple(pat)

    # Get top patterns
    top_pats = [get_pattern('top', i) for i in range(4)]

    out = [row[:] for row in g]

    # Fill middle blocks
    for bname in ['A', 'B', 'C', 'D']:
        brs, bre, grs, gre = blocks[bname]
        for ci in range(4):
            block_pat = get_pattern(bname, ci)
            if block_pat in top_pats:
                cs, ce, gcs, gce = cells[ci]
                for r in range(brs, bre + 1):
                    for c in range(cs, ce + 1):
                        if out[r][c] == 8:
                            out[r][c] = 3

    # Top block: check if all top cells match B cells
    b_pats = [get_pattern('B', i) for i in range(4)]
    top_fill = all(p in b_pats for p in top_pats)

    if top_fill:
        for r in range(0, 5):
            for c in range(w):
                if out[r][c] == 8:
                    out[r][c] = 3
        bottom_color = 3
    else:
        bottom_color = 2

    # Bottom
    for r in range(h - 2, h):
        for c in range(w):
            if out[r][c] == 8:
                out[r][c] = bottom_color

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background is the most common perimeter colour.
    perim = np.concatenate((g[0, :], g[-1, :], g[:, 0], g[:, -1]))
    bg = int(np.bincount(perim).argmax())

    out = g.copy()

    # Unique non-background colours are possible fill colours.
    counts = np.bincount(g.flatten(), minlength=10)
    unique_colors = {c for c in range(10) if c != bg and counts[c] == 1}
    if not unique_colors:
        return out.tolist()

    def flood(start, allowed):
        sr, sc = start
        stack = [(sr, sc)]
        comp = set(stack)
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < H and 0 <= nc < W:
                    p = (nr, nc)
                    if p not in comp and allowed(g[nr, nc]):
                        comp.add(p)
                        stack.append((nr, nc))
        return comp

    # Background components; interior ones do not touch the border.
    seen_bg = set()
    bg_comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == bg and (r, c) not in seen_bg:
                comp = flood((r, c), lambda x: x == bg)
                seen_bg |= comp
                touches = any(r == 0 or r == H - 1 or c == 0 or c == W - 1 for r, c in comp)
                bg_comps.append((comp, not touches))

    # Non-background components and the unique colour(s) contained in them.
    seen_nb = set()
    nb_comps = []
    for r in range(H):
        for c in range(W):
            if g[r, c] != bg and (r, c) not in seen_nb:
                comp = flood((r, c), lambda x: x != bg)
                seen_nb |= comp
                markers = unique_colors & {int(g[r, c]) for r, c in comp}
                nb_comps.append((comp, markers))

    # For each interior background hole, find adjacent non-background components.
    for comp, is_hole in bg_comps:
        if not is_hole:
            continue

        candidates = set()
        for r, c in comp:
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < H and 0 <= nc < W and g[nr, nc] != bg:
                    for nb_comp, markers in nb_comps:
                        if (nr, nc) in nb_comp:
                            candidates.update(markers)
                            break

        if len(candidates) == 1:
            fill = next(iter(candidates))
            for r, c in comp:
                out[r, c] = fill

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape
    out = g.copy()

    # The fill colour is the unique colour located at a corner.
    corners = [(0, 0), (0, W - 1), (H - 1, 0), (H - 1, W - 1)]
    fill_color = None
    for r, c in corners:
        val = int(g[r, c])
        if val != 0 and int((g == val).sum()) == 1:
            fill_color = val
            break

    if fill_color is None:
        return out.tolist()

    def is_corner(r, c):
        return r == 0 or r == H - 1 or c == 0 or c == W - 1

    # Candidate holes are 2x2 all-zero blocks.
    for r in range(H - 1):
        for c in range(W - 1):
            if not np.all(g[r:r + 2, c:c + 2] == 0):
                continue

            # Orthogonal border cells around the 2x2 block.
            orth = [
                (r - 1, c), (r - 1, c + 1),
                (r + 2, c), (r + 2, c + 1),
                (r, c - 1), (r + 1, c - 1),
                (r, c + 2), (r + 1, c + 2),
            ]
            if any(is_corner(rr, cc) for rr, cc in orth):
                continue
            if any(g[rr, cc] == 0 for rr, cc in orth):
                continue
            if len({int(g[rr, cc]) for rr, cc in orth}) != 1:
                continue

            out[r:r + 2, c:c + 2] = fill_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    src = np.array(grid, dtype=int)
    h, w = src.shape
    out = src.copy()

    # Fixed 4x4 tile layout inside the 30x22 picture.
    row_centers = [9, 14, 19, 24]
    col_centers = [3, 8, 13, 18]
    top_center_row = 2

    def tile_color(r, c):
        """Return the single non-8 colour in the 5x5 tile centred at (r,c)."""
        r0, r1 = max(0, r - 1), min(h, r + 2)
        c0, c1 = max(0, c - 2), min(w, c + 3)
        vals = src[r0:r1, c0:c1].ravel()
        vals = vals[vals != 8]
        if vals.size == 0:
            return None
        # The tiles are monochromatic; if not, take the most common colour.
        vals, cnts = np.unique(vals, return_counts=True)
        return int(vals[np.argmax(cnts)])

    def paint(r, c):
        """Draw a 3-border around tile centre (r,c), preserving non-8 pixels."""
        r0, r1 = max(0, r - 2), min(h, r + 3)
        c0, c1 = max(0, c - 2), min(w, c + 3)
        out[r0:r1, c0:c1] = np.where(src[r0:r1, c0:c1] == 8, 3, src[r0:r1, c0:c1])

    # ------------------------------------------------------------------
    # Read the instruction row: the four top tiles, left to right.
    # ------------------------------------------------------------------
    top = []
    for p, cc in enumerate(col_centers):
        col = tile_color(top_center_row, cc)
        if col is None:
            col = 8  # empty instruction tile
        top.append(col)

    # Build the fixed lower 4x4 colour matrix.
    matrix = [[tile_color(r, c) for c in col_centers] for r in row_centers]

    # Occurrences of each colour in the lower matrix.
    occ = {}
    for r in range(4):
        for c in range(4):
            v = matrix[r][c]
            if v is not None:
                occ.setdefault(v, []).append((r, c))

    # Count requested colours.
    need = {}
    for v in top:
        if v != 8:
            need[v] = need.get(v, 0) + 1

    # ------------------------------------------------------------------
    # Choose a primary row/column that supplies as many requested cells as
    # possible, with deterministic tie-breaking.  Then satisfy the rest.
    # ------------------------------------------------------------------
    best_score = -1
    best_type = 0  # 0=row, 1=col
    best_idx = 0

    def line_score(cells):
        s = 0
        rem = dict(need)
        for v in cells:
            if v in rem and rem[v] > 0:
                rem[v] -= 1
                s += 1
        return s

    # Rows first, then columns.
    for idx in range(4):
        cells = matrix[idx]
        score = line_score(cells)
        if score > best_score:
            best_score, best_type, best_idx = score, 0, idx
    for idx in range(4):
        cells = [matrix[r][idx] for r in range(4)]
        score = line_score(cells)
        if score > best_score:
            best_score, best_type, best_idx = score, 1, idx

    selected = set()
    rem = dict(need)

    # Highlight the chosen line.
    if best_type == 0:
        cells = [(best_idx, c) for c in range(4) if matrix[best_idx][c] is not None]
    else:
        cells = [(r, best_idx) for r in range(4) if matrix[r][best_idx] is not None]

    for r, c in cells:
        v = matrix[r][c]
        if v in rem and rem[v] > 0:
            selected.add((r, c))
            rem[v] -= 1

    # Satisfy remaining requests.
    # First try to take a remaining tile in the same column as its instruction.
    for p, v in enumerate(top):
        if v == 8:
            continue
        for _ in range(need.get(v, 0) - (0 if v not in rem else 0)):
            pass

    # More direct: iterate instructions left to right and fill deficits.
    # We already know rem; for each instruction position, if its colour is
    # still needed, prefer an unused occurrence in that column.
    for p, v in enumerate(top):
        if v == 8:
            continue
        while rem.get(v, 0) > 0:
            chosen = None
            # Same instruction column, unused.
            for rr, cc in occ.get(v, []):
                if cc == p and (rr, cc) not in selected:
                    chosen = (rr, cc)
                    break
            if chosen is None:
                # Nearest unused occurrence to the instruction tile.
                best_d = None
                for rr, cc in occ.get(v, []):
                    if (rr, cc) in selected:
                        continue
                    d = (rr * rr + (cc - p) * (cc - p))
                    if best_d is None or d < best_d:
                        best_d = d
                        chosen = (rr, cc)
            if chosen is None:
                break
            selected.add(chosen)
            rem[v] -= 1

    # ------------------------------------------------------------------
    # Special case: if the lower matrix has a column whose multiset exactly
    # matches the full instruction row, the whole instruction row is lit and
    # the summary colour is 3.  Otherwise the summary colour is 2.
    # ------------------------------------------------------------------
    summary = 2
    full_top = (len([x for x in top if x != 8]) == 4)

    if full_top:
        from collections import Counter
        top_counter = Counter(top)
        for c in range(4):
            col_counter = Counter(matrix[r][c] for r in range(4))
            if col_counter == top_counter:
                summary = 3
                # Light every top tile and the whole matching column.
                for p in range(4):
                    paint(top_center_row, col_centers[p])
                for r in range(4):
                    paint(row_centers[r], col_centers[c])
                break

    if summary != 3:
        for r, c in selected:
            paint(row_centers[r], col_centers[c])

    # Fill the two summary rows below the bottom 6-line.
    if h >= 30:
        out[28, :] = summary
        out[29, :] = summary

    return out.tolist()

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    # Fixed structure of this task family.
    ROW_BANDS = [(1, 3), (8, 10), (13, 15), (18, 20), (23, 25)]
    COL_BANDS = [(2, 4), (7, 9), (12, 14), (17, 19)]
    BACKGROUND = 8
    FILL = 3

    out = [list(row) for row in grid]

    def tile(r0, c0):
        return [
            [grid[r0 + dr][c0 + dc] for dc in range(3)]
            for dr in range(3)
        ]

    # The four fixed lower rows/columns in the 5x4 tile matrix.
    lower_rows = ROW_BANDS[1:]

    def match_position(r_band, c_band):
        tr, br = r_band
        tc, bc = c_band
        t = tile(tr, tc)
        b = tile(br, bc)
        if not all(t[dr][dc] == b[dr][dc] for dr in range(3) for dc in range(3)):
            return None
        col = b[0][0]
        if col != BACKGROUND and all(v == col for row in b for v in row):
            return 0
        return col

    def add_frame(r0, r1, c0, c1):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if 0 <= r < len(out) and 0 <= c < len(out[0]):
                    if out[r][c] == BACKGROUND:
                        out[r][c] = FILL

    def match_full_row(r_band, c_band):
        tr, br = r_band
        tc, bc = c_band
        t = tile(tr, tc)
        b = tile(br, bc)
        return all(t[dr][dc] == b[dr][dc] for dr in range(3) for dc in range(3))

    def match_full_col(r_band, c_band):
        tr, br = r_band
        tc, bc = c_band
        t = tile(tr, tc)
        b = tile(br, bc)
        return all(t[dr][dc] == b[dr][dc] for dr in range(3) for dc in range(3))

    top_band = ROW_BANDS[0]

    # If the top band is a permutation of one fixed row, frame that whole fixed row.
    for ri, br in enumerate(lower_rows):
        matches = [match_full_row(top_band, (br, bc)) for bc in COL_BANDS]
        if all(matches):
            # Permutation is allowed because all four tiles matched the same row.
            r0, r1 = br
            c0 = COL_BANDS[0][0] - 1
            c1 = COL_BANDS[-1][1] + 1
            add_frame(max(0, r0 - 1), min(len(out) - 1, r1 + 1),
                      max(0, c0), min(len(out[0]) - 1, c1))
            break
    else:
        # If the top band is a permutation of one fixed column, frame that whole fixed column.
        matched_any = False
        for ci, bc in enumerate(COL_BANDS):
            matches = [match_full_col((tr, bc), (tr, bc)) for tr in [top_band[0]]]
            # Use proper row matching: compare each lower row tile at this column with top tile at same index?
            # For a column, the top band must contain the four column tiles in the same vertical order.
            col_matches = []
            for ri, br in enumerate(lower_rows):
                col_matches.append(match_full_row((top_band[0] + ri * 0, top_band[0][1]), br) if False else
                                   all(tile(top_band[0], top_band[1])[dr][dc] == tile(br, bc)[dr][dc]
                                       for dr in range(3) for dc in range(3)))
            # This fallback is intentionally disabled because examples use individual tile matching.
            pass

        # General rule: frame every lower tile whose 3x3 pattern is present in the top band.
        for ri, br in enumerate(lower_rows):
            for ci, bc in enumerate(COL_BANDS):
                t = tile(top_band[0], top_band[1])
                b = tile(br, bc)
                if all(t[dr][dc] == b[dr][dc] for dr in range(3) for dc in range(3)):
                    r0, r1 = br
                    c0, c1 = bc
                    add_frame(max(0, r0 - 1), min(len(out) - 1, r1 + 1),
                              max(0, c0 - 1), min(len(out[0]) - 1, c1 + 1))

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    h, w = g.shape

    # Fixed horizontal bands in this puzzle family.
    # Top band: rows 0..4, objects in rows 1..3.
    # Lower bands:
    #   B: rows 7..11, objects rows 8..10
    #   C: rows 12..16, objects rows 13..15
    #   D: rows 17..21, objects rows 18..20
    #   E: rows 22..26, objects rows 23..25
    # Each band has four 3x3 object slots starting at columns 2, 7, 12, 17.
    slot_cols = [2, 7, 12, 17]

    def band_glyph(band_top: int) -> tuple[tuple[int, int, int], ...]:
        # Extract the four 3x3 glyph masks for a band.
        # Glyph mask values are 1 for non-8, 0 for 8, preserving color by separate array.
        masks = []
        colors = []
        for c0 in slot_cols:
            patch = g[band_top + 1:band_top + 4, c0:c0 + 3]
            mask = (patch != 8).astype(int)
            masks.append(tuple(tuple(row) for row in mask))
            # Dominant non-background color in the patch.
            vals = patch[patch != 8]
            if vals.size == 0:
                colors.append(None)
            else:
                colors.append(int(np.bincount(vals.ravel()).argmax()))
        return masks, colors

    top_masks, top_colors = band_glyph(0)
    lower = []
    for band_top in (7, 12, 17, 22):
        masks, colors = band_glyph(band_top)
        lower.append((band_top, masks, colors))

    # Find lower line(s) that best match the top row as a multiset of glyph masks.
    # If a whole row/col is an exact multiset match, select it.
    # Otherwise, for each top glyph, select matching glyphs in the best row if no exact match.
    # The examples imply:
    #   - Exact row match: fill that row's matching glyphs (all, if exact).
    #   - Exact column match: fill that column's matching glyphs.
    #   - Partial row match: fill matching glyphs in that row.
    #   - For duplicates/no line: choose a greedy assignment of top glyphs to
    #     distinct lower glyphs, preferring same slot, then same row/column,
    #     then closest position, with color as tie-breaker.
    # The resulting selected (band, slot) cells are filled by turning surrounding 8s to 3.

    selected = set()
    bottom_color = 3

    def mask_eq(a, b):
        return a == b

    def multiset_eq(a, b):
        return sorted(a) == sorted(b)

    rows = [masks for _, masks, _ in lower]
    cols = [[rows[r][c] for r in range(4)] for c in range(4)]

    # Exact row match
    exact_row = None
    for r, mrow in enumerate(rows):
        if multiset_eq(mrow, top_masks):
            exact_row = r
            break
    # Exact column match
    exact_col = None
    for c, mcol in enumerate(cols):
        if multiset_eq(mcol, top_masks):
            exact_col = c
            break

    if exact_row is not None:
        # Select all matching positions in that row (usually all 4).
        for c in range(4):
            if mask_eq(rows[exact_row][c], top_masks[c]):
                selected.add((exact_row, c))
        # If not every top glyph is represented in that row, bottom gets missing color.
        # In examples, exact row has all glyphs, so bottom remains 3.
    elif exact_col is not None:
        for r in range(4):
            if mask_eq(cols[exact_col][r], top_masks[r]):
                selected.add((r, exact_col))
    else:
        # Partial row match: choose row with maximum mask matches.
        best_r = -1
        best_score = -1
        for r in range(4):
            score = sum(1 for tc, rc in zip(top_masks, rows[r]) if mask_eq(tc, rc))
            if score > best_score:
                best_score = score
                best_r = r
        if best_score > 0:
            for c in range(4):
                if mask_eq(rows[best_r][c], top_masks[c]):
                    selected.add((best_r, c))
        else:
            # General greedy assignment by glyph mask.
            # We'll match each top slot to one lower glyph, not reusing lower glyphs.
            used = set()
            for tc_idx, tc_mask in enumerate(top_masks):
                # Score lower unused glyphs:
                # primary: same slot, secondary: same row, tertiary: closeness, color tie.
                best = None
                best_key = None
                for r in range(4):
                    for c in range(4):
                        if (r, c) in used:
                            continue
                        if mask_eq(rows[r][c], tc_mask):
                            # Prefer same column (slot) as top slot.
                            slot_match = 1 if c == tc_idx else 0
                            # Prefer lower bands in natural order for stable selection.
                            key = (slot_match, -r, -abs(c - tc_idx), -r - c)
                            if best_key is None or key > best_key:
                                best_key = key
                                best = (r, c)
                if best is not None:
                    used.add(best)
                    selected.add(best)
                else:
                    # Unmatched top glyph: use its color for bottom fill.
                    if top_colors[tc_idx] is not None and top_colors[tc_idx] != 3 and top_colors[tc_idx] != 8:
                        bottom_color = int(top_colors[tc_idx])

    # Fill selected band/slot boxes.
    out = g.copy()

    def fill_box(band_top: int, slot_idx: int):
        # Box rows band_top..band_top+4, cols slot_cols[slot_idx]-1..slot_cols[slot_idx]+2
        r0 = band_top
        r1 = band_top + 4
        c0 = slot_cols[slot_idx] - 1
        c1 = slot_cols[slot_idx] + 2
        for r in range(max(0, r0), min(h, r1 + 1)):
            for c in range(max(0, c0), min(w, c1 + 1)):
                if out[r, c] == 8:
                    out[r, c] = 3

    band_tops = [7, 12, 17, 22]
    for r, c in selected:
        fill_box(band_tops[r], c)

    # Bottom rows 28-29 fill.
    out[28:30, :] = bottom_color

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    # The examples all use the same fixed layout:
    # top strip: rows 0..4, 3x3 glyphs at columns 2, 7, 12, 17 in rows 1..3
    # four lower bands: rows 7..11, 12..16, 17..21, 22..26
    # each with the same 3x3 glyph columns.
    band_tops = [7, 12, 17, 22]
    slot_cols = [2, 7, 12, 17]

    def glyph(patch):
        return tuple(tuple(row) for row in patch)

    out = [row[:] for row in grid]

    # Extract top glyphs.  An all-8 slot is ignored.
    top_glyphs = []
    for c in slot_cols:
        g = [
            [grid[1][c:c + 3][0], grid[1][c + 1], grid[1][c + 2]],
            [grid[2][c:c + 3][0], grid[2][c + 1], grid[2][c + 2]],
            [grid[3][c:c + 3][0], grid[3][c + 1], grid[3][c + 2]],
        ]
        g = glyph(g)
        top_glyphs.append((c, g))

    # Extract lower board glyphs and their dominant non-background colour.
    board = {}
    for b, bt in enumerate(band_tops):
        for s, c in enumerate(slot_cols):
            g = [
                [grid[bt + 1][c + i] for i in range(3)],
                [grid[bt + 2][c + i] for i in range(3)],
                [grid[bt + 3][c + i] for i in range(3)],
            ]
            g = glyph(g)
            vals = [v for row in g for v in row if v != 8]
            color = max(set(vals), key=vals.count) if vals else 3
            board[(b, s)] = (g, color)

    # Match each non-empty top glyph to the one board glyph with exactly the
    # same 3x3 pattern.
    matched = []
    for top_col, g in top_glyphs:
        if all(v == 8 for row in g for v in row):
            continue
        found = None
        for (b, s), (bg, color) in board.items():
            if bg == g:
                found = (b, s, color)
                break
        if found is not None:
            matched.append(found)

    # Highlight a lower cell by painting all 8s in its 5x5 box with 3.
    def paint_lower(b, s):
        r0, r1 = band_tops[b], band_tops[b] + 4
        c0, c1 = slot_cols[s] - 1, slot_cols[s] + 3
        for r in range(max(0, r0), min(len(out), r1 + 1)):
            for c in range(max(0, c0), min(len(out[0]), c1 + 1)):
                if out[r][c] == 8:
                    out[r][c] = 3

    for b, s, _ in matched:
        paint_lower(b, s)

    # Determine whether matched cells form a complete row or complete column.
    cells = {(b, s) for b, s, _ in matched}
    complete_line = False
    if len(cells) == 4:
        for b in range(4):
            if all((b, s) in cells for s in range(4)):
                complete_line = True
                break
        if not complete_line:
            for s in range(4):
                if all((b, s) in cells for b in range(4)):
                    complete_line = True
                    break

    if complete_line:
        # Fill the entire top strip.
        for r in range(0, 5):
            for c in range(len(out[0])):
                if out[r][c] == 8:
                    out[r][c] = 3
        bottom_color = 3
    else:
        # If there is a matched cell that shares neither its band nor its slot
        # with any other matched cell, use its colour.  Otherwise use 3.
        bottom_color = 3
        for b, s, color in matched:
            isolated = True
            for b2, s2, _ in matched:
                if (b2, s2) == (b, s):
                    continue
                if b2 == b or s2 == s:
                    isolated = False
                    break
            if isolated:
                bottom_color = color
                break

    # Footer rows 28 and 29 become the determined colour.
    for r in range(28, 30):
        for c in range(len(out[0])):
            out[r][c] = bottom_color

    return out

import numpy as np

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    a = np.array(grid, dtype=np.int8)
    h, w = a.shape
    out = a.copy()

    max_n = min(h, w) // 2 + 2

    # Try every possible border colour and square-hole size.
    # A valid hole of size n at (r, c) has:
    # - its four orthogonal sides of length n all equal to the same colour b;
    # - its n x n interior uniform and different from b;
    # - when a corner cell exists, it is not b (exact side length locally).
    for b in range(10):
        # Fast precheck: border colour must appear enough times.
        if np.count_nonzero(a == b) < 4:
            continue

        for n in range(2, max_n + 1):
            # r is top row of interior, c is left column of interior
            for r in range(1, h - n):
                top_row = a[r - 1, c:c + n] if False else None
                for c in range(1, w - n):
                    # Top side
                    if not np.all(a[r - 1, c:c + n] == b):
                        continue
                    # Bottom side
                    if not np.all(a[r + n, c:c + n] == b):
                        continue
                    # Left side
                    if not np.all(a[r:r + n, c - 1] == b):
                        continue
                    # Right side
                    if not np.all(a[r:r + n, c + n] == b):
                        continue

                    # Corners, if present, must not extend the side colour.
                    if a[r - 1, c - 1] == b:
                        continue
                    if a[r - 1, c + n] == b:
                        continue
                    if a[r + n, c - 1] == b:
                        continue
                    if a[r + n, c + n] == b:
                        continue

                    interior = a[r:r + n, c:c + n]
                    if not np.all(interior == interior[0, 0]):
                        continue
                    if interior[0, 0] == b:
                        continue

                    out[r:r + n, c:c + n] = 4

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np

    g = np.array(grid, dtype=int)
    H, W = g.shape

    NEI = ((1, 0), (-1, 0), (0, 1), (0, -1))

    def component_mask(coords):
        m = np.zeros((H, W), dtype=bool)
        for r, c in coords:
            m[r, c] = True
        return m

    def count_holes(mask):
        # Background is everything not in this component.
        # Count enclosed background components that contain at least one 0.
        outside = np.zeros((H, W), dtype=bool)
        stack = []

        def add_border(r, c):
            if not mask[r, c] and not outside[r, c]:
                outside[r, c] = True
                stack.append((r, c))

        for r in range(H):
            add_border(r, 0)
            add_border(r, W - 1)
        for c in range(W):
            add_border(0, c)
            add_border(H - 1, c)

        while stack:
            r, c = stack.pop()
            for dr, dc in NEI:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W and not mask[nr, nc] and not outside[nr, nc]:
                    outside[nr, nc] = True
                    stack.append((nr, nc))

        holes = 0
        seen = outside.copy()

        for r in range(H):
            for c in range(W):
                if mask[r, c] or seen[r, c]:
                    continue

                stack = [(r, c)]
                seen[r, c] = True
                has_zero = (g[r, c] == 0)

                while stack:
                    cr, cc = stack.pop()
                    if g[cr, cc] == 0:
                        has_zero = True
                    for dr, dc in NEI:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and not mask[nr, nc] and not seen[nr, nc]:
                            seen[nr, nc] = True
                            stack.append((nr, nc))

                if has_zero:
                    holes += 1

        return holes

    # Find all non-zero connected components (4-connected).
    seen = np.zeros((H, W), dtype=bool)
    components = []

    for r in range(H):
        for c in range(W):
            if g[r, c] == 0 or seen[r, c]:
                continue

            color = g[r, c]
            stack = [(r, c)]
            seen[r, c] = True
            coords = []

            while stack:
                cr, cc = stack.pop()
                coords.append((cr, cc))
                for dr, dc in NEI:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < H and 0 <= nc < W and not seen[nr, nc] and g[nr, nc] == color:
                        seen[nr, nc] = True
                        stack.append((nr, nc))

            components.append((color, coords))

    # Build mapping: number of holes -> reference color.
    mapping = {}
    areas = {}

    for color, coords in components:
        if color == 5:
            continue

        rs = [r for r, _ in coords]
        cs = [c for _, c in coords]

        # Ignore separator lines (usually color 1) spanning the whole grid.
        if (min(rs) == 0 and max(rs) == H - 1) or (min(cs) == 0 and max(cs) == W - 1):
            continue

        mask = component_mask(coords)
        holes = count_holes(mask)

        # If multiple reference objects have the same hole count, prefer the
        # smaller one; the puzzle normally has a unique mapping.
        if holes not in mapping or len(coords) < areas[holes]:
            mapping[holes] = color
            areas[holes] = len(coords)

    # Recolor each 5-component according to its hole count.
    out = g.copy()
    for color, coords in components:
        if color != 5:
            continue

        mask = component_mask(coords)
        holes = count_holes(mask)
        target = mapping.get(holes, 0)

        for r, c in coords:
            out[r, c] = target

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [list(row) for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # The non-background rectangle colour is the one used for the rectangular
    # walls/paths.  In all supplied cases it is 0, but infer it safely.
    wall = 0
    if any(grid[r][c] != 0 for r in range(h) for c in range(w)):
        best = 0
        best_cnt = -1
        for col in range(1, 10):
            cnt = 0
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == col:
                        cnt += 1
            if cnt > best_cnt:
                best_cnt = cnt
                best = col
        wall = best

    def inside(r, c):
        return 0 <= r < h and 0 <= c < w

    # For every possible diagonal direction, look for a wall cell that is
    # exactly two diagonal steps from a source colour.  Then extend that colour
    # outward into the corresponding 2x2 corner block and mark the intermediate
    # diagonal cell.
    for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
        for r in range(h):
            for c in range(w):
                t_r = r + 2 * dr
                t_c = c + 2 * dc
                if not inside(t_r, t_c):
                    continue

                source = grid[r][c]
                if source == 0 or source == wall:
                    continue

                target = grid[t_r][t_c]
                if target not in (0, wall):
                    continue

                # The two adjacent diagonal cells must be background-like
                # (not another coloured object) so we don't connect unrelated
                # shapes.
                m_r, m_c = r + dr, c + dc
                if not inside(m_r, m_c):
                    continue
                if grid[m_r][m_c] not in (0, wall):
                    continue

                # Paint the intermediate cell.
                out[m_r][m_c] = source

                # Paint the 2x2 block anchored on the target cell in the
                # outward direction.
                if dr == -1:
                    block_rows = (t_r - 1, t_r)
                else:
                    block_rows = (t_r, t_r + 1)

                if dc == -1:
                    block_cols = (t_c - 1, t_c)
                else:
                    block_cols = (t_c, t_c + 1)

                for br in block_rows:
                    for bc in block_cols:
                        if inside(br, bc):
                            out[br][bc] = source

    # Handle the one-step case: a source colour directly diagonal from a
    # wall corner.  Paint the corner itself and the two axis-adjacent cells
    # pointing away from the source.
    for dr, dc in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
        for r in range(h):
            for c in range(w):
                t_r = r + dr
                t_c = c + dc
                if not inside(t_r, t_c):
                    continue

                source = grid[r][c]
                if source == 0 or source == wall:
                    continue

                target = grid[t_r][t_c]
                if target not in (0, wall):
                    continue

                out[t_r][t_c] = source

                # Two outward axis cells from the corner.
                cells = [(t_r + dr, t_c), (t_r, t_c + dc)]
                for rr, cc in cells:
                    if inside(rr, cc):
                        out[rr][cc] = source

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return [list(row) for row in grid]

    h = len(grid)
    w = len(grid[0])
    out = [row[:] for row in grid]

    # Background is the colour on the border; frame colour is 0.
    border = set()
    for c in range(w):
        border.add(grid[0][c])
        border.add(grid[h - 1][c])
    for r in range(h):
        border.add(grid[r][0])
        border.add(grid[r][w - 1])

    if len(border) == 1:
        bg = border.pop()
    else:
        # Fallback: most frequent border colour.
        from collections import Counter
        counter = Counter(list(border))
        bg = counter.most_common(1)[0][0]

    FRAME = 0

    def inside(r, c):
        return 0 <= r < h and 0 <= c < w

    def is_source(r, c):
        return inside(r, c) and grid[r][c] not in (FRAME, bg)

    directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    for r in range(h):
        for c in range(w):
            if not is_source(r, c):
                continue

            color = grid[r][c]

            for dr, dc in directions:
                # Walk diagonally until a frame corner is found.
                rr, cc = r + dr, c + dc
                distance = 0

                while inside(rr, cc):
                    if grid[rr][cc] == FRAME:
                        # Check that this 0 cell is a corner: it must have
                        # 0-neighbours in the two directions pointing back
                        # toward the source.
                        back_dr, back_dc = -dr, -dc

                        arm1 = inside(rr + back_dr, cc) and grid[rr + back_dr][cc] == FRAME
                        arm2 = inside(rr, cc + back_dc) and grid[rr][cc + back_dc] == FRAME

                        if arm1 and arm2:
                            distance = abs(rr - r)

                            # Paint the whole diagonal ray, including the corner.
                            k = 1
                            while True:
                                pr = r + k * dr
                                pc = c + k * dc
                                if not inside(pr, pc) or (pr, pc) == (rr, cc):
                                    if inside(pr, pc):
                                        out[pr][pc] = color
                                    break
                                out[pr][pc] = color
                                k += 1

                            # Paint the two perpendicular outside cells.
                            # These are the cells adjacent to the corner,
                            # outside the frame in the two side directions.
                            perp1 = (rr + dr, cc)
                            perp2 = (rr, cc + dc)
                            if inside(*perp1):
                                out[perp1] = color
                            if inside(*perp2):
                                out[perp2] = color

                            # If there was at least one intermediate diagonal
                            # cell, extend one diagonal cell past the corner.
                            if distance > 1:
                                diag = (rr + dr, cc + dc)
                                if inside(*diag):
                                    out[diag] = color

                            break

                    # If another colour blocks the diagonal, stop.
                    if grid[rr][cc] not in (bg, FRAME):
                        break

                    rr += dr
                    cc += dc

    return out

import numpy as np
from typing import List

def transform(grid: list[list[int]]) -> list[list[int]]:
    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Find the vertical separator line of 4s.
    sep = -1
    for x in range(W):
        if np.all(g[:, x] == 4):
            sep = x
            break
    if sep == -1:
        # Fallback for the known puzzle format.
        sep = 7

    out_w = sep
    out = np.zeros((H, out_w), dtype=int)

    # The 5 in the right side is the start point.
    start_x = out_w // 2
    found = False
    for r in range(H):
        for c in range(sep + 1, W):
            if g[r, c] == 5:
                start_x = c - (sep + 1) + 1  # relative to right-side 7-wide area
                start_x = c - sep
                found = True
                break
        if found:
            break

    x = start_x
    out[0, x] = 5
    r = 1

    # Convert a 3x3 colour block into its line segment behaviour.
    # In these examples:
    # 1 -> horizontal length 3, drawn to the right of x
    # 2 -> horizontal length 2, drawn to the left of x
    # 3 -> horizontal length 4, drawn to the left of x
    # 6 -> vertical length 2 at x
    def block_kind(block: np.ndarray) -> int:
        vals = [int(v) for v in block.flat if v != 0]
        if not vals:
            return 0
        # All examples use a single colour per block.
        return vals[0]

    # Column-major traversal of the left-side 3x3 blocks:
    # left column top-to-bottom, then right column top-to-bottom.
    # For the standard 7-wide left area, block columns start at 0 and 4.
    left_starts = []
    if out_w >= 3:
        left_starts.append(0)
    if out_w >= 7:
        left_starts.append(4)

    row_starts = []
    rr = 0
    while rr + 3 <= H:
        row_starts.append(rr)
        rr += 4

    for c0 in left_starts:
        for r0 in row_starts:
            block = g[r0:r0 + 3, c0:c0 + 3]
            kind = block_kind(block)

            if kind == 1:
                if r < H and 0 <= x <= out_w - 3:
                    out[r, x:x + 3] = 1
                    x += 2
                r += 1
            elif kind == 2:
                if r < H and 1 <= x < out_w:
                    out[r, x - 1:x + 1] = 2
                    x -= 1
                r += 1
            elif kind == 3:
                if r < H and 3 <= x < out_w:
                    out[r, x - 3:x + 1] = 3
                    x -= 3
                r += 1
            elif kind == 6:
                if r + 1 < H and 0 <= x < out_w:
                    out[r:r + 2, x] = 6
                r += 2
            else:
                # Should not happen for the provided puzzle family.
                r += 1

    return out.tolist()

def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    # Normalise input to a list of lists of ints.
    g = [[int(v) for v in row] for row in grid]
    H = len(g)
    W = len(g[0]) if H else 0

    # The full vertical line of 4s separates the command panel from the start panel.
    sep = -1
    for x in range(W):
        if all(g[y][x] == 4 for y in range(H)):
            sep = x
            break

    if sep == -1:
        sep = 7
    if sep >= W:
        sep = W - 1
    if sep < 0:
        return [[0] * W for _ in range(H)]

    out_w = sep
    out = [[0] * out_w for _ in range(H)]

    # Locate the start marker 5 on the right side.
    start_r = 0
    start_x = out_w // 2
    found = False
    for y in range(H):
        for x in range(sep + 1, W):
            if g[y][x] == 5:
                start_r = y
                start_x = x - (sep + 1)
                found = True
                break
        if found:
            break

    if out_w == 0:
        return out

    if start_x < 0 or start_x >= out_w:
        start_x = min(max(0, start_x), out_w - 1)

    out[start_r][start_x] = 5
    r = start_r + 1
    x = start_x

    # Command blocks are 3x3 blocks spaced by one empty column/row group.
    col_starts = list(range(0, out_w - 2, 4))
    row_starts = list(range(0, H - 2, 4))

    def block_kind(r0: int, c0: int) -> int:
        vals = set()
        for i in range(3):
            for j in range(3):
                v = g[r0 + i][c0 + j]
                if v != 0:
                    vals.add(v)

        if len(vals) == 1:
            return next(iter(vals))
        if not vals:
            return 0

        # Fallback: dominant non-zero colour.
        counts = {}
        for i in range(3):
            for j in range(3):
                v = g[r0 + i][c0 + j]
                if v != 0:
                    counts[v] = counts.get(v, 0) + 1
        return max(counts.items(), key=lambda item: item[1])[0]

    # Execute blocks column by column, top to bottom.
    for c0 in col_starts:
        for r0 in row_starts:
            k = block_kind(r0, c0)

            if k == 1:
                # Draw 3 cells to the right: x, x+1, x+2.
                if r < H:
                    for c in range(x, x + 3):
                        if 0 <= c < out_w:
                            out[r][c] = 1
                x += 2
                r += 1

            elif k == 2:
                # Draw 2 cells ending at x: x-1, x.
                if r < H:
                    for c in range(x - 1, x + 1):
                        if 0 <= c < out_w:
                            out[r][c] = 2
                x -= 1
                r += 1

            elif k == 3:
                # Draw 4 cells ending at x: x-3, x-2, x-1, x.
                if r < H:
                    for c in range(x - 3, x + 1):
                        if 0 <= c < out_w:
                            out[r][c] = 3
                x -= 3
                r += 1

            elif k == 6:
                # Draw 2 vertical cells at x: r, r+1.
                for dy in range(2):
                    if 0 <= r + dy < H and 0 <= x < out_w:
                        out[r + dy][x] = 6
                r += 2

            # Empty or unknown blocks do nothing.

    return out

from collections import Counter

def transform(grid: list[list[int]]) -> list[list[int]]:
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    if w == 0:
        return [[] for _ in range(h)]

    # Background is the border colour in all given cases.
    corners = {grid[0][0], grid[0][-1], grid[-1][0], grid[-1][-1]}
    if len(corners) == 1:
        bg = corners.pop()
    else:
        border = grid[0] + grid[-1] + [grid[i][0] for i in range(h)] + [grid[i][-1] for i in range(h)]
        bg = Counter(border).most_common(1)[0][0]

    # The horizontal "bar chart" axis is the row with the most non-background cells.
    scores = [sum(1 for x in row if x != bg) for row in grid]
    r0 = min(range(h), key=lambda i: (-scores[i], abs(2 * i - h)))
    if scores[r0] == 0:
        return [row[:] for row in grid]

    def vertical_bounds(r: int, c: int, color: int):
        top = r
        while top > 0 and grid[top - 1][c] == color:
            top -= 1
        bottom = r
        while bottom + 1 < h and grid[bottom + 1][c] == color:
            bottom += 1
        return top, bottom

    axis = grid[r0]

    # Identify the axis colour.  It is a non-background colour on the axis row
    # that does not extend vertically (or is the known colour 6 when present).
    stats = {}
    for c, val in enumerate(axis):
        if val == bg:
            continue
        if val not in stats:
            stats[val] = {"count": 0, "runs": 0, "max_run": 0}
        stats[val]["count"] += 1
        if c == 0 or axis[c - 1] != val:
            stats[val]["runs"] += 1
        top, bottom = vertical_bounds(r0, c, val)
        stats[val]["max_run"] = max(stats[val]["max_run"], bottom - top + 1)

    if not stats:
        return [row[:] for row in grid]

    one_high = [col for col, s in stats.items() if s["max_run"] == 1]
    if 6 in one_high:
        axis_color = 6
    elif one_high:
        axis_color = max(one_high, key=lambda col: (stats[col]["runs"], stats[col]["count"]))
    else:
        axis_color = max(stats, key=lambda col: (stats[col]["runs"], stats[col]["count"]))

    # Vertical bars are contiguous same-colour runs on the axis row, excluding bg/axis.
    objects = []
    c = 0
    while c < w:
        val = axis[c]
        if val != bg and val != axis_color:
            start = c
            end = c
            while end + 1 < w and axis[end + 1] == val:
                end += 1

            runs = []
            cols = []
            max_height = 0
            for col in range(start, end + 1):
                top, bottom = vertical_bounds(r0, col, val)
                runs.append((col, top, bottom))
                cols.append(col)
                max_height = max(max_height, bottom - top + 1)

            objects.append({
                "cols": cols,
                "runs": runs,
                "color": val,
                "height": max_height,
            })
            c = end + 1
        else:
            c += 1

    if not objects:
        return [row[:] for row in grid]

    # Sort bar heights in increasing order and assign them left-to-right.
    new_heights = sorted(obj["height"] for obj in objects)

    out = [row[:] for row in grid]

    # Erase old bars.
    for obj in objects:
        for col, top, bottom in obj["runs"]:
            for r in range(top, bottom + 1):
                if 0 <= r < h and out[r][col] == obj["color"]:
                    out[r][col] = bg

    # Draw bars with the sorted heights.
    for obj, nh in zip(objects, new_heights):
        top = r0 - nh // 2
        bottom = top + nh - 1
        for col in obj["cols"]:
            for r in range(top, bottom + 1):
                if 0 <= r < h:
                    out[r][col] = obj["color"]

    return out

