class Block:
    __slots__ = (
        "frame", "r0", "c0", "r1", "c1",
        "color", "cr0", "cc0", "cr1", "cc1"
    )

    def __init__(self, frame, r0, c0, r1, c1, color, cr0, cc0, cr1, cc1):
        self.frame = frame
        self.r0 = r0
        self.c0 = c0
        self.r1 = r1
        self.c1 = c1
        self.color = color
        self.cr0 = cr0
        self.cc0 = cc0
        self.cr1 = cr1
        self.cc1 = cc1


def transform(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    H = len(grid)
    W = len(grid[0])

    # Background is the most common color.
    counts = Counter(v for row in grid for v in row)
    max_cnt = max(counts.values())
    candidates_bg = [c for c, n in counts.items() if n == max_cnt]
    if 0 in candidates_bg:
        bg = 0
    else:
        bg = min(candidates_bg)

    # Find all framed blocks:
    # a rectangular component of one color surrounding a single rectangular color region.
    visited = [[False] * W for _ in range(H)]
    blocks = []

    for sr in range(H):
        for sc in range(W):
            start_color = grid[sr][sc]
            if start_color == bg or visited[sr][sc]:
                continue

            q = deque([(sr, sc)])
            visited[sr][sc] = True
            cells = []

            while q:
                r, c = q.popleft()
                cells.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < H and 0 <= nc < W:
                        if not visited[nr][nc] and grid[nr][nc] == start_color:
                            visited[nr][nc] = True
                            q.append((nr, nc))

            if len(cells) < 4:
                continue

            r0 = min(r for r, _ in cells)
            r1 = max(r for r, _ in cells)
            c0 = min(c for _, c in cells)
            c1 = max(c for _, c in cells)

            h = r1 - r0 + 1
            w = c1 - c0 + 1
            if h < 3 or w < 3:
                continue

            bbox_colors = {}
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    v = grid[r][c]
                    bbox_colors[v] = bbox_colors.get(v, 0) + 1

            # Valid block: exactly two colors inside its bounding box,
            # one is the frame component, the other is the inner color.
            if len(bbox_colors) != 2 or start_color not in bbox_colors:
                continue

            center_color = [x for x in bbox_colors if x != start_color][0]
            if center_color == bg:
                continue

            # All non-center cells in the bbox must belong to this component.
            if bbox_colors[start_color] != len(cells):
                continue

            # Inner color must be a solid rectangle strictly inside the frame.
            inner_cells = []
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if grid[r][c] == center_color:
                        inner_cells.append((r, c))

            if not inner_cells:
                continue

            cr0 = min(r for r, _ in inner_cells)
            cr1 = max(r for r, _ in inner_cells)
            cc0 = min(c for _, c in inner_cells)
            cc1 = max(c for _, c in inner_cells)

            inner_area = (cr1 - cr0 + 1) * (cc1 - cc0 + 1)
            if inner_area != bbox_colors[center_color]:
                continue

            if not (r0 < cr0 and cr1 < r1 and c0 < cc0 and cc1 < c1):
                continue

            blocks.append(Block(start_color, r0, c0, r1, c1,
                                center_color, cr0, cc0, cr1, cc1))

    if not blocks:
        return [row[:] for row in grid]

    # Mask cells belonging to any detected block.
    in_block = [[False] * W for _ in range(H)]
    for b in blocks:
        for r in range(b.r0, b.r1 + 1):
            for c in range(b.c0, b.c1 + 1):
                in_block[r][c] = True

    center_colors = {b.color for b in blocks}

    # Find the legend line: a row or column with the most outside-block cells
    # whose colors are block-center colors.
    best_seq = []
    best_score = 0

    for r in range(H):
        seq = []
        for c in range(W):
            if in_block[r][c]:
                continue
            v = grid[r][c]
            if v != bg and v in center_colors:
                seq.append(v)
        if len(seq) > best_score:
            best_score = len(seq)
            best_seq = seq

    for c in range(W):
        seq = []
        for r in range(H):
            if in_block[r][c]:
                continue
            v = grid[r][c]
            if v != bg and v in center_colors:
                seq.append(v)
        if len(seq) > best_score:
            best_score = len(seq)
            best_seq = seq

    # Fallback if something unexpected happened.
    if not best_seq:
        for r in range(H):
            seq = [grid[r][c] for c in range(W)
                   if grid[r][c] != bg and not in_block[r][c]]
            if len(seq) > best_score:
                best_score = len(seq)
                best_seq = seq
        for c in range(W):
            seq = [grid[r][c] for r in range(H)
                   if grid[r][c] != bg and not in_block[r][c]]
            if len(seq) > best_score:
                best_score = len(seq)
                best_seq = seq

    seq = [v for v in best_seq if v in center_colors]
    if len(seq) < 2:
        return [row[:] for row in grid]

    # Candidate block indices for each center color.
    candidates = {}
    for i, b in enumerate(blocks):
        candidates.setdefault(b.color, []).append(i)
    for color in candidates:
        candidates[color].sort(key=lambda i: (blocks[i].r0, blocks[i].c0))

    N = len(blocks)
    centers = []
    for b in blocks:
        centers.append(((b.cr0 + b.cr1) / 2.0, (b.cc0 + b.cc1) / 2.0))

    # Prefix sum of non-background cells, to test whether a rectangle is empty.
    ps = [[0] * (W + 1) for _ in range(H + 1)]
    for r in range(H):
        row_sum = 0
        for c in range(W):
            row_sum += 0 if grid[r][c] == bg else 1
            ps[r + 1][c + 1] = ps[r][c + 1] + row_sum

    def rect_is_bg(r0, r1, c0, c1):
        if r0 > r1 or c0 > c1:
            return True
        s = (ps[r1 + 1][c1 + 1]
             - ps[r0][c1 + 1]
             - ps[r1 + 1][c0]
             + ps[r0][c0])
        return s == 0

    def block_intersects_rect(b, r0, r1, c0, c1):
        return (b.r0 <= r1 and b.r1 >= r0 and
                b.c0 <= c1 and b.c1 >= c0)

    def connection(i, j):
        """Return (connectable, fill_rect_or_None)."""
        A = blocks[i]
        B = blocks[j]

        # Horizontal connection.
        r0 = max(A.cr0, B.cr0)
        r1 = min(A.cr1, B.cr1)
        if r0 <= r1:
            if A.c1 < B.c0:
                left, right = A, B
            elif B.c1 < A.c0:
                left, right = B, A
            else:
                left = None

            if left is not None:
                c0 = left.c1 + 1
                c1 = right.c0 - 1
                if c0 <= c1:
                    if rect_is_bg(r0, r1, c0, c1):
                        blocked = False
                        for k, blk in enumerate(blocks):
                            if k == i or k == j:
                                continue
                            if block_intersects_rect(blk, r0, r1, c0, c1):
                                blocked = True
                                break
                        if not blocked:
                            return True, (r0, r1, c0, c1)
                elif left.c1 + 1 == right.c0:
                    # Adjacent, no fill needed, but still a legal step.
                    return True, None

        # Vertical connection.
        c0 = max(A.cc0, B.cc0)
        c1 = min(A.cc1, B.cc1)
        if c0 <= c1:
            if A.r1 < B.r0:
                top, bottom = A, B
            elif B.r1 < A.r0:
                top, bottom = B, A
            else:
                top = None

            if top is not None:
                r0 = top.r1 + 1
                r1 = bottom.r0 - 1
                if r0 <= r1:
                    if rect_is_bg(r0, r1, c0, c1):
                        blocked = False
                        for k, blk in enumerate(blocks):
                            if k == i or k == j:
                                continue
                            if block_intersects_rect(blk, r0, r1, c0, c1):
                                blocked = True
                                break
                        if not blocked:
                            return True, (r0, r1, c0, c1)
                elif top.r1 + 1 == bottom.r0:
                    # Adjacent vertically.
                    return True, None

        return False, None

    conn = [[False] * N for _ in range(N)]
    rect_cache = [[None] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if i == j:
                continue
            ok, rect = connection(i, j)
            conn[i][j] = ok
            rect_cache[i][j] = rect

    def dist(i, j):
        return (abs(centers[i][0] - centers[j][0]) +
                abs(centers[i][1] - centers[j][1]))

    # Find a full path through the legend sequence.
    L = len(seq)
    best_path = None
    best_score_path = None

    def score_path(path):
        return sum(dist(path[k], path[k + 1]) for k in range(len(path) - 1))

    def dfs_distinct(i, last, used, path):
        nonlocal best_path, best_score_path
        if i == L:
            s = score_path(path)
            if best_score_path is None or s < best_score_path:
                best_score_path = s
                best_path = path[:]
            return

        color = seq[i]
        cands = candidates.get(color, [])
        if not cands:
            return

        if last is not None:
            cands = sorted(cands, key=lambda x: dist(last, x))

        for b in cands:
            if used & (1 << b):
                continue
            if last is not None and not conn[last][b]:
                continue
            path.append(b)
            dfs_distinct(i + 1, b, used | (1 << b), path)
            path.pop()

    if seq[0] in candidates:
        for b in candidates[seq[0]]:
            dfs_distinct(1, b, 1 << b, [b])

    # Fallback: allow reusing blocks (but not consecutively).
    if best_path is None:
        def dfs_allow(i, last, path):
            nonlocal best_path, best_score_path
            if i == L:
                s = score_path(path)
                if best_score_path is None or s < best_score_path:
                    best_score_path = s
                    best_path = path[:]
                return

            color = seq[i]
            cands = candidates.get(color, [])
            if not cands:
                return

            if last is not None:
                cands = sorted(cands, key=lambda x: dist(last, x))

            for b in cands:
                if last is not None and (b == last or not conn[last][b]):
                    continue
                path.append(b)
                dfs_allow(i + 1, b, path)
                path.pop()

        if seq[0] in candidates:
            for b in candidates[seq[0]]:
                dfs_allow(1, b, [b])

    # Very last fallback: choose each adjacent pair independently.
    fills = []
    if best_path is not None:
        fills = [(best_path[i], best_path[i + 1], seq[i])
                 for i in range(L - 1)]
    else:
        prev = None
        for i in range(L - 1):
            ca = seq[i]
            cb = seq[i + 1]
            best_pair = None
            best_d = None

            for a in candidates.get(ca, []):
                for b in candidates.get(cb, []):
                    if a == b or not conn[a][b]:
                        continue
                    # If possible, keep consistency with the previous chosen block.
                    d = dist(a, b)
                    if prev is not None and i > 0:
                        d += 0.1 * dist(prev, a)
                    if best_pair is None or d < best_d:
                        best_d = d
                        best_pair = (a, b)

            if best_pair is not None:
                fills.append((best_pair[0], best_pair[1], ca))
                prev = best_pair[1]
            else:
                prev = None

    out = [row[:] for row in grid]

    for a, b, fill_color in fills:
        rect = rect_cache[a][b]
        if rect is None:
            continue
        r0, r1, c0, c1 = rect
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if out[r][c] == bg:
                    out[r][c] = fill_color

    return out

def transform(grid: list[list[int]]) -> list[list[int]]:
    import numpy as np
    from collections import Counter, deque

    g = np.array(grid, dtype=int)
    H, W = g.shape

    # Background: the most frequent colour (usually the outer border colour).
    cnt = Counter(int(v) for row in g for v in row)
    bg = cnt.most_common(1)[0][0]

    # Border colour: the most frequent non-background colour.
    nonbg = Counter(c for c, n in cnt.items() if c != bg)
    if not nonbg:
        return g.tolist()
    border = nonbg.most_common(1)[0][0]

    payload_colors = set(c for c in cnt if c not in (bg, border))

    def four_neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    # Connected components of the border colour (4-connected).
    seen = np.zeros((H, W), dtype=bool)
    components = []
    for r in range(H):
        for c in range(W):
            if g[r, c] == border and not seen[r, c]:
                q = deque([(r, c)])
                seen[r, c] = True
                cells = []
                min_r = max_r = r
                min_c = max_c = c
                while q:
                    cr, cc = q.popleft()
                    cells.append((cr, cc))
                    min_r = min(min_r, cr)
                    max_r = max(max_r, cr)
                    min_c = min(min_c, cc)
                    max_c = max(max_c, cc)
                    for nr, nc in four_neighbors(cr, cc):
                        if not seen[nr, nc] and g[nr, nc] == border:
                            seen[nr, nc] = True
                            q.append((nr, nc))
                components.append((min_r, min_c, max_r, max_c, cells))

    # For each border component, collect the payload colours present inside its bbox.
    # Components with no payload are empty templates and are ignored.
    selected = []
    for min_r, min_c, max_r, max_c, cells in components:
        payload_inside = set()
        for r in range(min_r, max_r + 1):
            row = g[r, min_c:max_c + 1]
            for v in row:
                if v in payload_colors:
                    payload_inside.add(int(v))
        if payload_inside:
            selected.append((min_r, min_c, max_r, max_c))

    if not selected:
        return g.tolist()

    # Order: top-to-bottom; tie-break left-to-right.
    selected.sort(key=lambda b: (b[0], b[1]))

    out_rows = []
    for min_r, min_c, max_r, max_c in selected:
        crop = g[min_r:max_r + 1, min_c:max_c + 1].copy()
        crop = crop.tolist()
        out_rows.extend(crop)

    return out_rows

import numpy as np
from collections import Counter
import itertools

def transform(grid: list[list[int]]) -> list[list[int]]:
    a = np.array(grid, dtype=int)
    H, W = a.shape
    bg = a[0, 0]

    # Find the largest rectangular solid-color block with holes of the background color.
    best = None
    for r in range(H):
        for c in range(W):
            color = a[r, c]
            if color == bg:
                continue
            max_r = r
            while max_r + 1 < H and (a[max_r + 1, c:max_r] if False else True):
                break
            # simpler scan for all-4 block
            mr = r
            while mr + 1 < H:
                row = a[mr + 1, c:c+1]
                break
            break
        break

    # Robust rectangle detection:
    # A frame cell is the frame color; holes inside its bounding rectangle are background.
    def solid_block(r, c):
        color = a[r, c]
        # expand to maximal contiguous rectangle of cells that are either color or bg,
        # with all non-bg cells equal to color.
        r1, r2 = r, r
        c1, c2 = c, c
        while r1 > 0 and valid_row(r1-1, c, c+1):
            r1 -= 1
        while r2 + 1 < H and valid_row(r2+1, c, c+1):
            r2 += 1
        while c1 > 0 and valid_col(c1-1, r, r+1):
            c1 -= 1
        while c2 + 1 < W and valid_col(c2+1, r, r+1):
            c2 += 1
        sub = a[r1:r2+1, c1:c2+1]
        nonbg = sub[(sub != bg)]
        if len(nonbg) == 0:
            return None
        if np.all(nonbg == color):
            if (color != bg):
                return (r1, r2, c1, c2, color)
        return None

    def valid_row(r, c, c_end):
        for cc in range(c, c_end):
            if a[r, cc] not in (bg, a[0, 0]):  # placeholder not used
                return False
        return True

    # Use straightforward search over all possible rectangles that look like the frame.
    candidates = []
    colors = set(int(x) for x in a.flatten() if x != bg)
    for color in colors:
        mask_color = (a == color)
        mask_allowed = (a == color) | (a == bg)
        # For each start, expand maximal allowed rectangle; accept if border mostly color and holes exist.
        for r in range(H):
            for c in range(W):
                if not mask_allowed[r, c]:
                    continue
                r2 = r
                while r2 + 1 < H and np.all(mask_allowed[r2 + 1, c:c+1]):
                    r2 += 1
                c2 = c
                while c2 + 1 < W and np.all(mask_allowed[r:r2+1, c2 + 1]):
                    c2 += 1
                # expand left/up if still allowed and consistent
                r1 = r
                while r1 > 0 and np.all(mask_allowed[r1 - 1, c:c2+1]):
                    r1 -= 1
                c1 = c
                while c1 > 0 and np.all(mask_allowed[r1:r2+1, c1 - 1]):
                    c1 -= 1
                sub_allowed = mask_allowed[r1:r2+1, c1:c2+1]
                sub_color = mask_color[r1:r2+1, c1:c2+1]
                sub_bg = (a[r1:r2+1, c1:c2+1] == bg)
                holes = sub_bg & sub_allowed
                color_cells = sub_color
                # Frame should be large and have at least one hole.
                if holes.sum() > 0 and color_cells.sum() > 0:
                    area = (r2 - r1 + 1) * (c2 - c1 + 1)
                    # Prefer large, and color cells forming a connected frame.
                    candidates.append((area, holes.sum(), r1, r2, c1, c2, color))
    if not candidates:
        return [list(map(int, row)) for row in grid]

    candidates.sort(reverse=True)
    r1, r2, c1, c2, frame_color = None, None, None, None, None
    for area, hcnt, rr1, rr2, cc1, cc2, color in candidates:
        sub = a[rr1:rr2+1, cc1:cc2+1]
        # Require border to be frame color (allow small imperfections).
        border = np.concatenate([
            sub[0, :].flatten(),
            sub[-1, :].flatten(),
            sub[:, 0].flatten(),
            sub[:, -1].flatten()
        ])
        if np.mean(border == color) >= 0.95 and hcnt > 0:
