                    rr2 = r
                    while rr2 + 1 < H and np.all(allowed[rr2 + 1, c:c+1]):
                        rr2 += 1
                    cc2 = c
                    while cc2 + 1 < W and np.all(allowed[r:rr2+1, cc2 + 1]):
                        cc2 += 1
                    rr1 = r
                    while rr1 > 0 and np.all(allowed[rr1 - 1, c:cc2+1]):
                        rr1 -= 1
                    cc1 = c
                    while cc1 > 0 and np.all(allowed[rr1:rr2+1, cc1 - 1]):
                        cc1 -= 1
                    area = (rr2-rr1+1)*(cc2-cc1+1)
                    holes = np.sum((a[rr1:rr2+1, cc1:cc2+1] == bg))
                    if holes and area > best_area:
                        best_area = area
                        r1, r2, c1, c2, frame_color = rr1, rr2, cc1, cc2, color
        if r1 is None:
